export type EditorRegion = {
	id: string,
	element: HTMLElement,
	label: string,
};

/**
 * The five regions of the editor. The node settings panel, the debug bar and the process data
 * window are deliberately absent: the first is out of the scope of the feature, the second is
 * behind a feature flag, the third is a window of its own.
 */
export const EDITOR_REGION_ID: {
	HEADER: string,
	DIAGRAM: string,
	CATALOG: string,
	TOOLS_TOP: string,
	TOOLS_BOTTOM: string,
} = Object.freeze({
	HEADER: 'header',
	DIAGRAM: 'diagram',
	CATALOG: 'catalog',
	TOOLS_TOP: 'toolsTop',
	TOOLS_BOTTOM: 'toolsBottom',
});

/**
 * The walking order, and the only source of it. Neither the order of registration nor the order of
 * the nodes in the document takes part: a region mounted late still stands where this list puts it.
 */
export const EDITOR_REGION_ORDER: Array<string> = Object.freeze([
	EDITOR_REGION_ID.HEADER,
	EDITOR_REGION_ID.DIAGRAM,
	EDITOR_REGION_ID.CATALOG,
	EDITOR_REGION_ID.TOOLS_TOP,
	EDITOR_REGION_ID.TOOLS_BOTTOM,
]);

const registry: Map<string, EditorRegion> = new Map();

/**
 * The name comes from whoever owns the element and gives it its accessible name: the registry reads
 * no localization of its own. A region whose element is not on the page is registered as absent -
 * there is nothing to move the focus to.
 */
export function registerRegion(id: string, element: ?HTMLElement, label: string): void
{
	if (!EDITOR_REGION_ORDER.includes(id))
	{
		return;
	}

	if (!(element instanceof HTMLElement))
	{
		registry.delete(id);

		return;
	}

	registry.set(id, { id, element, label });
}

export function unregisterRegion(id: string): void
{
	registry.delete(id);
}

export function getOrderedRegions(): Array<EditorRegion>
{
	const regions: Array<EditorRegion> = [];

	EDITOR_REGION_ORDER.forEach((id) => {
		const region = registry.get(id);

		if (region !== undefined)
		{
			regions.push(region);
		}
	});

	return regions;
}

export function findRegionByElement(node: ?Node): ?EditorRegion
{
	if (!(node instanceof Node))
	{
		return null;
	}

	return getOrderedRegions().find((region) => region.element.contains(node)) ?? null;
}

/**
 * The neighbour of a region, as a ring. A caller standing outside every region enters the first one
 * of the order, whichever direction it asked for: there is nothing to step away from yet.
 */
export function getAdjacentRegion(fromId: ?string, step: 1 | -1): ?EditorRegion
{
	const regions = getOrderedRegions();

	if (regions.length === 0)
	{
		return null;
	}

	const current = regions.findIndex((region) => region.id === fromId);

	if (current < 0)
	{
		return regions[0];
	}

	return regions[(current + step + regions.length) % regions.length];
}
