import { ajax, Loc } from 'main.core';
import { FocusNavigator } from 'ui.a11y';
import { BLine } from 'ui.system.skeleton.vue';
import { markRaw, nextTick, onBeforeUnmount, ref } from 'ui.vue3';
import { FeatureCode } from 'bizprocdesigner.feature';

import { type TestRunField } from '../../../entities/test-run';
import { useFeature } from '../../../shared/composables';
import { BxControl } from '../../../shared/directives';
import { isRequiredField, startSettingsControlsRenderAsync } from '../../../shared/utils';
import { TestRunUserField } from './test-run-user-field';

const FIELD_ROW_ID_PREFIX = 'bizprocdesigner-test-run-field-';
const FIELD_LABEL_ID_PREFIX = 'bizprocdesigner-test-run-field-label-';
// The name of a field is a return property of an activity, so it is an identifier and stays a valid selector.
const FIELD_TEST_ID_PREFIX = 'bizprocdesigner-editor-test-run-field-';
// The height a typed control of `bizproc` takes, so a row keeps it before the control is there.
const CONTROL_SKELETON_HEIGHT = 32;

export const TEST_RUN_ERROR_ID = 'bizprocdesigner-test-run-error';

// The engine has no control to pick a user of the portal by, so such a field is drawn by the form itself.
function isUserField(field: TestRunField): boolean
{
	return field.property.Type === 'user';
}

// @vue/component
export const TestRunForm = {
	name: 'TestRunForm',
	components: { BLine, TestRunUserField },
	directives: { BxControl },
	props: {
		fields: {
			type: Array,
			required: true,
		},
		documentType: {
			type: Array,
			required: true,
		},
		invalidFieldNames: {
			type: Array,
			default: (): string[] => [],
		},
		scope: {
			type: String,
			default: '',
		},
		collapsesOptionalFields: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['change', 'rendered'],
	setup(props, { emit }): Object
	{
		const form = ref(null);
		// The map arrives a yield of control after the form itself: the boxes are asked for behind the lazy
		// load of the field framework. The rows of the fields stand in the markup from the mount either
		// way - the window of the dialog is measured over them - and it is the box inside a row that waits
		// for the map. `null` here means "not there yet"; a cancelled render never reaches this state,
		// because only an unmounted form cancels one (see `isRenderCancelled` below).
		const controls = ref(null);
		let isReleased = false;
		let release = null;

		// The boxes are asked for once, before the first render: the directive that puts a box into the
		// markup only fires on mount, and the component is mounted anew on every opening of the dialog and
		// keyed by the node and the revision of the draft, so no render of it ever sees other props and
		// none is ever superseded.
		void (async () => {
			// A user field is drawn by the form itself, so the engine is not asked for a box for it.
			const engineFields = props.fields.filter((field: TestRunField): boolean => !isUserField(field));

			// Nothing for the engine to draw: the form of the fields is whole as it stands, and waiting
			// for the lazy load of the framework would only hold the start button of the dialog off for
			// the length of it. The empty map is what the slice answers for an empty collection too
			// (`{}` - "nothing to fill in", as against `null` of a cancelled render), so the rows read it
			// the same way, and there is no render to release.
			// With the feature off there is nothing to wait out - the loader answers without loading the
			// framework at all - so the form hands the empty set over the way it always has.
			if (engineFields.length === 0 && useFeature().isFeatureAvailable(FeatureCode.fieldsFramework))
			{
				controls.value = markRaw({});

				await nextTick();

				if (!isReleased)
				{
					emit('rendered');
				}

				return;
			}

			const render = await startSettingsControlsRenderAsync({
				documentType: props.documentType,
				fields: engineFields.map((field: TestRunField) => ({
					property: { ...field.property, AllowSelection: false },
					fieldName: field.name,
					controlId: field.name,
					value: '',
				})),
				guardForeignEvent: true,
				isRenderCancelled: () => isReleased,
				resolveRendererType: () => null,
				// Nothing for the slice to run at the end of its own wait: the readiness of this form is
				// announced below, once the boxes have reached the markup, and the tail of the slice runs
				// before the map is even handed over.
				onRenderFinished: (): void => {},
			});

			// A form closed while the framework was still loading: the render is already given up by
			// `isRenderCancelled`, and this hands back the one that slipped through the window between the
			// answer of the slice and this line.
			if (isReleased)
			{
				render.release();

				return;
			}

			release = render.release;
			controls.value = markRaw(render.controls);

			await render.whenFinished;
			// The map reaches the markup on the flush the assignment above put into the queue, and the
			// wait for the finish of the render already outlasts that flush today - the tail of the slice
			// spends a microtask of its own after it. The tick is what keeps the guarantee from resting on
			// that count: `rendered` means "the fields are on the screen", the dialog unlocks the start by
			// it, and the values of the run are collected off that very markup.
			await nextTick();

			if (!isReleased)
			{
				emit('rendered');
			}
		})().catch((error: Error): void => {
			console.error(error);
			// A refusal shows as fields with nothing in them and never as fields that load forever: the
			// skeleton promises a control that is not coming. A map that was already handed over stays -
			// the refusal of the tail says nothing about the boxes that are already in the rows.
			if (!controls.value)
			{
				controls.value = markRaw({});
			}
		});

		onBeforeUnmount(() => {
			isReleased = true;
			release?.();
		});

		return { form, controls, errorId: TEST_RUN_ERROR_ID, skeletonHeight: CONTROL_SKELETON_HEIGHT };
	},
	data(): { areAllFieldsShown: boolean }
	{
		return { areAllFieldsShown: false };
	},
	computed: {
		// Hidden fields stay in the form: their default values still leave with the run.
		hasHiddenFields(): boolean
		{
			return this.collapsesOptionalFields
				&& !this.areAllFieldsShown
				&& this.fields.some((field: TestRunField): boolean => this.isRequired(field))
				&& this.fields.some((field: TestRunField): boolean => !this.isRequired(field))
			;
		},
		showAllFieldsText(): string
		{
			return Loc.getMessage('BIZPROCDESIGNER_EDITOR_TEST_RUN_SHOW_ALL_FIELDS') ?? '';
		},
		formTestId(): string
		{
			return `bizprocdesigner-editor-test-run-${this.scope}form`;
		},
		requiredHint(): string
		{
			return Loc.getMessage('BIZPROCDESIGNER_EDITOR_TEST_RUN_FIELD_REQUIRED_HINT') ?? '';
		},
	},
	watch: {
		invalidFieldNames(names: string[]): void
		{
			if (this.fields.some((field: TestRunField): boolean => names.includes(field.name) && this.isHidden(field)))
			{
				this.areAllFieldsShown = true;
			}
		},
	},
	methods: {
		isHidden(field: TestRunField): boolean
		{
			return this.hasHiddenFields && !this.isRequired(field);
		},
		async showAllFields(): Promise<void>
		{
			const firstHiddenField = this.fields.find((field: TestRunField): boolean => this.isHidden(field));
			this.areAllFieldsShown = true;
			await this.$nextTick();

			const row = this.findFieldRow(firstHiddenField);
			if (row && !FocusNavigator.focusFirst(row))
			{
				FocusNavigator.focusContainer(row);
			}
		},
		findFieldRow(field: TestRunField | undefined): HTMLElement | null
		{
			const rowId = field ? this.getFieldRowId(field) : null;

			return this.$refs.fieldRows?.find((element: HTMLElement): boolean => element.id === rowId) ?? null;
		},
		collectValues(): { [fieldName: string]: mixed }
		{
			if (!this.form)
			{
				return {};
			}

			const { data } = ajax.prepareForm(this.form);
			// The search box of a user selector has no name and is not a field.
			delete data[''];

			return data;
		},
		isUserField(field: TestRunField): boolean
		{
			return isUserField(field);
		},
		isRequired(field: TestRunField): boolean
		{
			return isRequiredField(field);
		},
		isInvalid(field: TestRunField): boolean
		{
			return this.invalidFieldNames.includes(field.name);
		},
		getFieldRowId(field: TestRunField): string
		{
			return `${FIELD_ROW_ID_PREFIX}${this.scope}${field.name}`;
		},
		getFieldLabelId(field: TestRunField): string
		{
			return `${FIELD_LABEL_ID_PREFIX}${this.scope}${field.name}`;
		},
		getFieldTestId(field: TestRunField): string
		{
			return `${FIELD_TEST_ID_PREFIX}${this.scope}${field.name}`;
		},
		focusFirstInvalidField(): boolean
		{
			const field = this.fields.find((item: TestRunField): boolean => this.isInvalid(item));
			if (!field)
			{
				return false;
			}

			const row = this.findFieldRow(field);
			if (!row)
			{
				return false;
			}

			// The control comes from a foreign extension and may not be in the markup yet: until it is,
			// the focus goes to the named group, so the field is still called by name.
			if (!FocusNavigator.focusFirst(row))
			{
				FocusNavigator.focusContainer(row);
			}

			return true;
		},
	},
	template: `
		<form
			ref="form"
			class="bizprocdesigner-test-run__fields node-settings-panel"
			:data-testid="formTestId"
			:aria-busy="!controls"
			@input="$emit('change')"
			@change="$emit('change')"
			@submit.prevent
		>
			<div
				v-for="field in fields"
				v-show="!isHidden(field)"
				:key="field.name"
				ref="fieldRows"
				:id="getFieldRowId(field)"
				:data-testid="getFieldTestId(field)"
				class="bizprocdesigner-test-run__field node-settings-edit-box"
				:class="{ '--invalid': isInvalid(field) }"
				role="group"
				:aria-labelledby="getFieldLabelId(field)"
				:aria-invalid="isInvalid(field) || null"
				:aria-describedby="isInvalid(field) ? errorId : null"
			>
				<div :id="getFieldLabelId(field)" class="bizprocdesigner-test-run__field-label">
					{{ field.title }}<span
						v-if="isRequired(field)"
						class="bizprocdesigner-test-run__field-required"
						aria-hidden="true"
					>*</span><visually-hidden v-if="isRequired(field)">, {{ requiredHint }}</visually-hidden>
				</div>
				<TestRunUserField
					v-if="isUserField(field)"
					class="bizprocdesigner-test-run__field-control field-row"
					:field="field"
					:label-id="getFieldLabelId(field)"
					:invalid="isInvalid(field)"
					@change="$emit('change')"
				/>
				<div v-else class="bizprocdesigner-test-run__field-control">
					<!-- The node carrying the box is created with the map and not before: the directive
					only fires on mount, so a node made earlier would never receive its control. Until the
					map is there the row holds a skeleton line of the height a control takes, so the window
					is measured over the rows it is going to show. The layout class stays on the node of the
					control itself, so the parts of a box are laid out as siblings, not through a wrapper. -->
					<div v-if="controls" class="field-row" v-bx-control="controls[field.name]"></div>
					<BLine v-else :height="skeletonHeight"/>
				</div>
			</div>
			<button
				v-if="hasHiddenFields"
				type="button"
				class="bizprocdesigner-test-run__show-all-fields"
				:data-testid="formTestId + '-show-all-fields'"
				@click="showAllFields"
			>{{ showAllFieldsText }}</button>
		</form>
	`,
};
