import { createUniqueId } from '../../../shared/utils';
import { type BlockId } from '../../../shared/types';

/**
 * A lane reads optional membership of ordinary activities; assigning it belongs to the move flow.
 * The height is read through `laneHeights()` alone, never off the record itself.
 */
export type PoolLaneModel = {
	id: string,
	title?: string,
	height?: number,
	activityIds?: Array<BlockId>,
};

/**
 * Id for a lane about to join `lanes`. Uniqueness is asked of this pool alone: a lane is addressed
 * together with its block wherever it is addressed at all, so ids repeat from pool to pool by design
 * and only a draw already taken here is drawn again.
 */
export function createLaneId(lanes: Array<PoolLaneModel>): string
{
	const taken = new Set(lanes.map((lane) => lane.id));
	let id = createUniqueId();

	while (taken.has(id))
	{
		id = createUniqueId();
	}

	return id;
}
