/**
 * The preview of a note beside its marker: who wrote last, when, and what. It is read and nothing
 * else - the conversation itself opens by a click on the marker. The pointer does reach the card
 * (WCAG 1.4.13), and how long it stands is the doing of the layer that draws it: the layer holds it
 * open while the pointer is on the marker or on the card, and takes it away by Escape.
 *
 * The text of a note does not travel with the list of the markers (DTO-01): the answer carries the
 * anchor, the author and the number of messages, and the messages themselves come with the thread. So
 * the preview asks for that thread - the same request the thread makes, into the same cache. A note
 * read here opens with nothing to wait for, and a note opened once previews without asking again -
 * until somebody writes into it, and the number of messages of the note says so.
 */

import { BLine } from 'ui.system.skeleton.vue';
import { Text3Xs, TextXs } from 'ui.system.typography.vue';
import { TextEditor } from 'ui.text-editor';
import { Loc, Type } from 'main.core';
import { defineComponent } from 'ui.vue3';

import { useNotesStore, type TemplateNoteMessage } from '../../../../entities/notes';
import { useEditorUsers, useLoc } from '../../../../shared/composables';
import { formatRelativeTime } from '../../../../shared/utils';
import { createNoteEditorOptions } from '../../lib/editor-options';
import { resolveNoteWindowPlacement, type NoteWindowPlacement } from '../note-thread/note-thread-popup';

import './note-preview.css';

const PREVIEW_TEST_ID = 'bizprocdesigner-note-preview';

const AUTHOR_UNKNOWN_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_NOTE_MESSAGE_AUTHOR_UNKNOWN';
const MORE_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_NOTE_PREVIEW_MORE';

/** The text is read and never typed into, so the editor is drawn without the frame of a field. */
const VISUAL_OPTIONS = Object.freeze({
	borderWidth: '0',
	colorBackground: 'transparent',
	blockSpaceInline: '0',
	blockSpaceStack: '0',
});

export const NotePreview = defineComponent({
	name: 'BizprocdesignerNotePreview',
	components: { BLine, Text3Xs, TextXs },
	props: {
		note: {
			/** @type TemplateNote */
			type: Object,
			required: true,
		},
		templateId: {
			type: Number,
			required: true,
		},
		// the point of the marker the preview stands beside, in the coordinates of the canvas layer
		anchorX: {
			type: Number,
			required: true,
		},
		anchorY: {
			type: Number,
			required: true,
		},
		viewportWidth: {
			type: Number,
			required: true,
		},
		viewportHeight: {
			type: Number,
			required: true,
		},
	},
	// The conversation could not be read: the card has nothing to show and asks the layer to take it
	// away, so the note it stands for is asked about anew the next time the pointer comes to it.
	emits: ['failed'],
	setup(): Object
	{
		const { getMessage } = useLoc();
		const { users, ensureUsers } = useEditorUsers();

		return {
			getMessage,
			users,
			ensureUsers,
			notesStore: useNotesStore(),
		};
	},
	data(): Object
	{
		return {
			width: 0,
			height: 0,
			// The side is chosen by the size of the card, and the size is only known once it is in the
			// document. It is therefore drawn once without being shown, and never in the wrong place.
			isMeasured: false,
			// the line of the author stands level with the marker, so its height is part of the placement
			headHeight: 0,
			isLoading: false,
			// A conversation that could not be read shows no card at all: what a preview would have to
			// say about a refusal belongs to the thread, which is where the refusal can be acted on.
			hasFailed: false,
		};
	},
	computed: {
		messages(): TemplateNoteMessage[]
		{
			return this.notesStore.messages[this.note.id] ?? [];
		},
		lastMessage(): TemplateNoteMessage | null
		{
			return this.messages[this.messages.length - 1] ?? null;
		},
		hasMessage(): boolean
		{
			return this.lastMessage !== null;
		},
		authorText(): string
		{
			const authorId = this.lastMessage?.authorId ?? 0;
			const name = this.users[String(authorId)]?.name ?? '';

			return name === '' ? this.getMessage(AUTHOR_UNKNOWN_MESSAGE_ID) : name;
		},
		timeText(): string
		{
			const written = Date.parse(this.lastMessage?.createdAt ?? '');

			return Number.isNaN(written) ? '' : formatRelativeTime(written, this.getMessage);
		},
		// What is left of the conversation behind the message that is shown. The count comes from the
		// note itself and not from the messages at hand: an older part of a long thread is not read.
		moreCount(): number
		{
			return Math.max(0, this.note.messageCount - 1);
		},
		hasMore(): boolean
		{
			return this.moreCount > 0;
		},
		moreText(): string
		{
			return Loc.getMessagePlural(MORE_MESSAGE_ID, this.moreCount, {
				'#COUNT#': String(this.moreCount),
			});
		},
		/**
		 * Whether the conversation at hand is the one from before the last message of the note. The
		 * thread answers with the whole of it and with the number of messages counted over the same
		 * answer (API-07), so a count of the note that has moved on says the messages are behind.
		 */
		isThreadBehind(): boolean
		{
			return this.messages.length !== this.note.messageCount;
		},
		placement(): NoteWindowPlacement
		{
			return resolveNoteWindowPlacement(
				{ x: this.anchorX, y: this.anchorY },
				{ width: this.width, height: this.height },
				{ width: this.viewportWidth, height: this.viewportHeight },
				this.headHeight,
			);
		},
		// A translation rather than left/top, as the markers of the layer above the same canvas.
		previewStyle(): { transform: string, visibility?: string }
		{
			const style = { transform: `translate(${this.placement.x}px, ${this.placement.y}px)` };

			return this.isMeasured ? style : { ...style, visibility: 'hidden' };
		},
		previewTestId(): string
		{
			return this.$testId(PREVIEW_TEST_ID, String(this.note.id));
		},
	},
	watch: {
		// The card is drawn before the conversation arrives, so the text is handed to the editor when
		// it does - and again if the last message changes while the card stands open.
		lastMessage(): void
		{
			this.editor?.setText(this.lastMessage?.text ?? '');
			void this.loadAuthor();
		},
		// The count of the note moved on while the card stands open: a live signal about a note that
		// is not open brings the count back and not the messages (EVENT-01), so the conversation is
		// read anew instead of standing beside a number it does not match.
		'note.messageCount': function(): void
		{
			void this.load();
		},
	},
	created(): void
	{
		// Off data() on purpose: the editor keeps private fields and drops its own prototype in
		// destroy(), neither of which survives a reactive proxy, and nothing renders it.
		this.editor = null;
		this.sizeObserver = null;
	},
	mounted(): void
	{
		this.editor = new TextEditor({
			...createNoteEditorOptions({
				templateId: this.templateId,
				placeholder: '',
			}),
			content: this.lastMessage?.text ?? '',
			editable: false,
			minHeight: null,
			maxHeight: null,
			visualOptions: { ...VISUAL_OPTIONS },
		});

		this.editor.renderTo(this.$refs.container);

		this.measure();
		this.observeSize();
		void this.load();
	},
	beforeUnmount(): void
	{
		this.sizeObserver?.disconnect();
		this.sizeObserver = null;
		this.editor?.destroy();
		this.editor = null;
	},
	methods: {
		/**
		 * The conversation of the note, and only when it is not at hand already or has fallen behind
		 * the note. The card is mounted once the pointer has stood on the marker long enough, so the
		 * wait of the preview is what keeps a schema crossed by the mouse from asking about every
		 * note it passed; a conversation read anew is read through the store, so a thread already
		 * being read is waited for instead of asked about twice.
		 */
		async load(): Promise<void>
		{
			if (this.messages.length > 0 && !this.isThreadBehind)
			{
				void this.loadAuthor();

				return;
			}

			this.isLoading = true;
			try
			{
				await this.notesStore.loadThread(this.note.id);
			}
			catch
			{
				this.hasFailed = true;
				this.$emit('failed');
			}
			finally
			{
				this.isLoading = false;
			}
		},
		async loadAuthor(): Promise<void>
		{
			const authorId = this.lastMessage?.authorId ?? 0;

			try
			{
				await this.ensureUsers([authorId]);
			}
			catch
			{
				// A message whose author could not be named is still a message that can be read.
			}
		},
		/**
		 * The size the card takes with the message it holds. It changes once - when the conversation
		 * arrives and the skeleton gives way to the text - and that change may turn the card to the
		 * other side of its marker.
		 */
		measure(): void
		{
			const preview = this.$refs.preview ?? null;
			if (preview === null)
			{
				return;
			}

			const box = preview.getBoundingClientRect();
			if (box.width !== this.width || box.height !== this.height)
			{
				this.width = box.width;
				this.height = box.height;
			}

			const head = this.$refs.head?.getBoundingClientRect().height ?? 0;
			if (head !== this.headHeight)
			{
				this.headHeight = head;
			}

			this.isMeasured = true;
		},
		observeSize(): void
		{
			if (!Type.isFunction(ResizeObserver) || !Type.isDomNode(this.$refs.preview))
			{
				return;
			}

			this.sizeObserver = new ResizeObserver(() => this.measure());
			this.sizeObserver.observe(this.$refs.preview);
		},
	},
	template: `
		<div
			v-show="!hasFailed"
			class="editor-chart-note-preview"
			:style="previewStyle"
			ref="preview"
			aria-hidden="true"
			:data-testid="previewTestId"
		>
			<div v-if="hasMessage" class="editor-chart-note-preview__head" ref="head">
				<TextXs className="editor-chart-note-preview__author">{{ authorText }}</TextXs>
				<Text3Xs className="editor-chart-note-preview__time">{{ timeText }}</Text3Xs>
			</div>
			<div v-else class="editor-chart-note-preview__head" ref="head">
				<BLine width="120"/>
			</div>
			<!-- ui.text-editor owns the children of this node; anything Vue renders stays its sibling -->
			<div
				v-show="hasMessage"
				class="editor-chart-note-preview__text"
				ref="container"
			></div>
			<div v-if="!hasMessage" class="editor-chart-note-preview__skeleton">
				<BLine/>
				<BLine width="180"/>
			</div>
			<Text3Xs
				v-if="hasMessage && hasMore"
				className="editor-chart-note-preview__more"
			>{{ moreText }}</Text3Xs>
		</div>
	`,
});
