import { Loc } from 'main.core';

import { formatRelativeTime } from '../../../shared/utils';
import { type ActiveRun } from '../types';

const SECOND = 1000;

function getMessage(phraseCode: string): string
{
	return Loc.getMessage(phraseCode) ?? '';
}

export function formatActiveRunStartTime(activeRun: ActiveRun | null): string
{
	return formatRelativeTime((activeRun?.startTime ?? 0) * SECOND, getMessage);
}
