import { storeToRefs } from 'ui.vue3.pinia';
import { computed, toValue } from 'ui.vue3';
import {
	CatalogGroup,
	useCatalogStore,
} from '../../../../entities/catalog';
import type { CatalogMenuGroup } from '../../../../entities/catalog';

type ChangeCatalogGroupSetup = {
	isShowItems: boolean,
	onChangeGroup: (group: CatalogMenuGroup) => void,
};

// @vue/component
export const ChangeCatalogGroup = {
	name: 'ChangeCatalogGroup',
	components: {
		CatalogGroup,
	},
	props: {
		/** @type CatalogMenuGroup */
		group: {
			type: Object,
			required: true,
		},
	},
	setup(props): ChangeCatalogGroupSetup
	{
		const catalogStore = useCatalogStore();
		const { currentGroup } = storeToRefs(catalogStore);

		const isShowItems = computed((): boolean => {
			return props.group.id === currentGroup?.value?.id;
		});

		// The header says `aria-expanded`, so it has to answer the second press as the state it
		// announces promises: leaving the group, exactly where ArrowLeft and Escape leave it.
		function onChangeGroup(group: CatalogMenuGroup): void
		{
			if (toValue(isShowItems))
			{
				catalogStore.resetFoundedGroupView();

				return;
			}

			catalogStore.changeCurrentGroup(group);
		}

		return {
			isShowItems,
			onChangeGroup,
		};
	},
	template: `
		<CatalogGroup
			:group="group"
			:showItems="isShowItems"
			@changeGroup="onChangeGroup"
		>
			<template #icon>
				<slot name="icon"/>
			</template>

			<template #back>
				<slot name="back"/>
			</template>

			<template #items>
				<slot name="items"/>
			</template>

			<template #empty-label>
				<slot name="empty-label"/>
			</template>
		</CatalogGroup>
	`,
};
