import { Loc } from 'main.core';
import { Outline } from 'ui.icon-set.api.core';
import { Text2Xs, TextMd, TextSm } from 'ui.system.typography.vue';

import { HotkeyKey, IconButton } from '../../../../shared/ui';

/**
 * One action of the panel. The row is told what to show and owns no state of its own: which combo
 * is the effective one and whether it differs from the default is answered once for the whole list,
 * not by every row over the same two maps.
 *
 * An action the catalog marks as not reassignable is shown with the others - the list is meant to
 * be the full reference of the editor - but its combo is a plain read-only key: an element offering
 * an assignment that will be refused is worse than no element at all.
 */
// @vue/component
export const HotkeysActionRow = {
	name: 'HotkeysActionRow',
	components: {
		HotkeyKey,
		IconButton,
		Text2Xs,
		TextMd,
		TextSm,
	},
	props: {
		label: {
			type: String,
			required: true,
		},
		combo: {
			type: String,
			default: '',
		},
		isCustom: {
			type: Boolean,
			default: false,
		},
		isReassignable: {
			type: Boolean,
			default: true,
		},
	},
	emits: ['assign', 'reset'],
	setup(): Object
	{
		return { Outline };
	},
	computed: {
		hasCombo(): boolean
		{
			return this.combo !== '';
		},
		// Only a row a user has changed has something to go back to.
		hasReset(): boolean
		{
			return this.isReassignable && this.isCustom;
		},
	},
	methods: {
		loc(phraseCode: string): string
		{
			return Loc.getMessage(phraseCode) ?? '';
		},
		handleAssign(): void
		{
			if (!this.isReassignable)
			{
				return;
			}

			this.$emit('assign');
		},
	},
	template: `
		<div class="bizprocdesigner-hotkeys-row" data-testid="bizprocdesigner-editor-hotkeys-row">
			<TextMd
				class="bizprocdesigner-hotkeys-row__label"
				data-testid="bizprocdesigner-editor-hotkeys-row-label"
			>{{ label }}</TextMd>
			<div class="bizprocdesigner-hotkeys-row__state">
				<Text2Xs
					v-if="isCustom"
					class="bizprocdesigner-hotkeys-row__mark"
					data-testid="bizprocdesigner-editor-hotkeys-row-modified"
				>{{ loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_ROW_MODIFIED') }}</Text2Xs>
				<component
					:is="isReassignable ? 'button' : 'span'"
					class="bizprocdesigner-hotkeys-row__combo"
					:class="{ '--assignable': isReassignable }"
					:type="isReassignable ? 'button' : null"
					:aria-label="isReassignable ? label : null"
					:data-testid="isReassignable ? 'bizprocdesigner-editor-hotkeys-assign' : 'bizprocdesigner-editor-hotkeys-row-combo'"
					@click="handleAssign"
				>
					<HotkeyKey v-if="hasCombo" :combo="combo"/>
					<TextSm v-else class="bizprocdesigner-hotkeys-row__empty">
						{{ loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_COMBO_EMPTY') }}
					</TextSm>
				</component>
				<IconButton
					v-if="hasReset"
					class="bizprocdesigner-hotkeys-row__reset"
					:iconName="Outline.REFRESH"
					:size="18"
					:aria-label="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_ROW_RESET')"
					:title="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_ROW_RESET')"
					data-testid="bizprocdesigner-editor-hotkeys-row-reset"
					@click="$emit('reset')"
				/>
			</div>
		</div>
	`,
};
