import { resolveBrokenLinkOwners } from './broken-links-owner';

/**
 * A field of a form of a construction: the name of its control, the value the control holds and the
 * caption the person reads next to it.
 */
export type BrokenLinkFormField = {
	name: string,
	value: mixed,
	title: string,
	// The row the control of the field stands on, for a field read off the markup of a form. A field
	// read off the descriptions the server sent has none: its control is drawn later.
	row?: ?HTMLElement,
};

/**
 * The fields a single broken reference is written in, named in the order of the fields themselves.
 * More than one of them may hold the reference, and which one the transition leads to is the caller's
 * to choose: this is where the share of the references leading nowhere is decided.
 */
export function resolveBrokenLinkFieldNames(link: string, fields: Array<BrokenLinkFormField>): Array<string>
{
	const { owners } = resolveBrokenLinkOwners(
		[link],
		fields.map((field) => ({ ownerId: field.name, value: field.value })),
	);

	return owners.get(link) ?? [];
}
