import { Loc, Type } from 'main.core';
import { DateTimeFormat } from 'main.date';
import { Outline } from 'ui.icon-set.api.vue';

import {
	type ChangeFeedRow,
	type TemplateChangeDetails,
	type TemplateChangeEvent,
	EVENT_TYPES,
} from '../../../../entities/blocks/stores/change-history';
import { buildChangePhrase } from './change-phrase';

export type GroupHeaderRow = {
	type: 'group',
	key: string,
	day: string,
	author: string,
	authorTypeLabel: string,
	aiInitiator: string,
};

export type ChangeRow = {
	type: 'change',
	key: string,
	eventId: number,
	index: number,
	kind: string,
	time: string,
	text: string,
};

export type ToggleRow = {
	type: 'toggle',
	key: string,
	id: number,
	text: string,
	isExpanded: boolean,
	isLoading: boolean,
	errorMessage: string,
};

export type EventRow = {
	type: 'event',
	key: string,
	id: number,
	time: string,
	eventTitle: string,
	eventIcon: string,
	eventModifier: string,
	versionLabel: string,
};

export type FeedRow = GroupHeaderRow | ChangeRow | EventRow | ToggleRow;

export type DisplayRowsContext = {
	userNames: { [string]: string },
	expandedEventIds: Array<number>,
	eventDetails: { [string]: TemplateChangeDetails },
};

type EventMark = {
	icon: string,
	modifier: string,
};

const AUTHOR_TYPES = Object.freeze({
	human: 1,
	ai: 2,
	system: 3,
});

const EVENT_TYPE_PHRASES = {
	[EVENT_TYPES.publication]: 'BIZPROCDESIGNER_EDITOR_HISTORY_EVENT_PUBLICATION',
	[EVENT_TYPES.creation]: 'BIZPROCDESIGNER_EDITOR_HISTORY_EVENT_CREATION',
	[EVENT_TYPES.draftSave]: 'BIZPROCDESIGNER_EDITOR_HISTORY_EVENT_DRAFT_SAVE',
};

/** The mark an event is recognised by while scrolling, before its title is read. */
const EVENT_TYPE_MARKS = {
	[EVENT_TYPES.publication]: { icon: Outline.ROCKET, modifier: 'publication' },
	[EVENT_TYPES.creation]: { icon: Outline.FLAG, modifier: 'creation' },
	[EVENT_TYPES.draftSave]: { icon: Outline.DOCUMENT_UPDATE, modifier: 'draft-save' },
};

const UNKNOWN_EVENT_MARK = Object.freeze({ icon: Outline.NOTE, modifier: 'unknown' });

const AUTHOR_TYPE_PHRASES = {
	[AUTHOR_TYPES.ai]: 'BIZPROCDESIGNER_EDITOR_HISTORY_AUTHOR_AI',
	[AUTHOR_TYPES.system]: 'BIZPROCDESIGNER_EDITOR_HISTORY_AUTHOR_SYSTEM',
};

const AI_TOOL_PHRASES = new Map([
	['marta', 'BIZPROCDESIGNER_EDITOR_HISTORY_AI_TOOL_MARTA'],
	['rest', 'BIZPROCDESIGNER_EDITOR_HISTORY_AI_TOOL_EXTERNAL_AGENT'],
]);

const SHOW_MORE_CHANGES_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_ACTION_SHOW_MORE_CHANGES';
const COLLAPSE_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_ACTION_COLLAPSE';

const NO_DATA_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_NO_DATA';
const UNKNOWN_AUTHOR_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_AUTHOR_UNKNOWN';
const UNKNOWN_AI_TOOL_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_AI_TOOL_UNKNOWN';
const UNKNOWN_INITIATOR_PHRASE = 'BIZPROCDESIGNER_EDITOR_HISTORY_AI_INITIATOR_UNKNOWN';

/** A group header says today/yesterday, an exact date further back; its rows carry the time alone. */
const FEED_DAY_INTERVALS = [['today', 'today'], ['yesterday', 'yesterday']];

const FEED_DAY_FORMAT_CODE = 'FORMAT_DATE';
const FEED_TIME_FORMAT_CODE = 'SHORT_TIME_FORMAT';

function loc(phraseCode: string, replacements: ?{ [string]: string | number } = null): string
{
	return Loc.getMessage(phraseCode, replacements) ?? '';
}

function formatDay(timestamp: ?number): string
{
	if (!Type.isNumber(timestamp))
	{
		return loc(NO_DATA_PHRASE);
	}

	return DateTimeFormat.format(
		[...FEED_DAY_INTERVALS, ['', DateTimeFormat.getFormat(FEED_DAY_FORMAT_CODE)]],
		new Date(timestamp * 1000),
	);
}

function formatTime(timestamp: ?number): string
{
	if (!Type.isNumber(timestamp))
	{
		return loc(NO_DATA_PHRASE);
	}

	return DateTimeFormat.format(
		DateTimeFormat.getFormat(FEED_TIME_FORMAT_CODE),
		new Date(timestamp * 1000),
	);
}

function resolveEventTitle(eventType: number): string
{
	return loc(EVENT_TYPE_PHRASES[eventType] ?? NO_DATA_PHRASE);
}

function resolveEventMark(eventType: number): EventMark
{
	return EVENT_TYPE_MARKS[eventType] ?? UNKNOWN_EVENT_MARK;
}

function resolveVersionLabel(event: TemplateChangeEvent): string
{
	if (event.eventType !== EVENT_TYPES.publication || !Type.isNumber(event.versionNumber))
	{
		return '';
	}

	return loc('BIZPROCDESIGNER_EDITOR_HISTORY_VERSION', { '#NUMBER#': event.versionNumber });
}

function resolveAuthorTypeLabel(authorType: number): string
{
	const phraseCode = AUTHOR_TYPE_PHRASES[authorType];

	return phraseCode ? loc(phraseCode) : '';
}

function resolveUserName(userNames: { [string]: string }, userId: ?number, fallbackPhrase: string): string
{
	const name = Type.isNumber(userId) ? userNames[String(userId)] : null;

	return Type.isStringFilled(name) ? name : loc(fallbackPhrase);
}

/**
 * A system event has no name of its own: the author type mark stands for it.
 */
function resolveAuthor(event: TemplateChangeEvent, userNames: { [string]: string }): string
{
	if (event.authorType === AUTHOR_TYPES.system)
	{
		return '';
	}

	if (event.authorType === AUTHOR_TYPES.ai)
	{
		return loc(AI_TOOL_PHRASES.get(event.aiTool) ?? UNKNOWN_AI_TOOL_PHRASE);
	}

	return resolveUserName(userNames, event.authorId, UNKNOWN_AUTHOR_PHRASE);
}

function resolveAiInitiator(event: TemplateChangeEvent, userNames: { [string]: string }): string
{
	if (event.authorType !== AUTHOR_TYPES.ai)
	{
		return '';
	}

	return loc('BIZPROCDESIGNER_EDITOR_HISTORY_AI_INITIATOR', {
		'#INITIATOR#': resolveUserName(userNames, event.initiatorUserId, UNKNOWN_INITIATOR_PHRASE),
	});
}

function buildToggleRow(row: ChangeFeedRow, context: DisplayRowsContext): ToggleRow
{
	const eventId = row.event.id;
	const isExpanded = context.expandedEventIds.includes(eventId);
	const details = context.eventDetails[eventId];
	const errorMessage = details?.errorMessage;

	return {
		type: 'toggle',
		key: row.key,
		id: eventId,
		text: isExpanded
			? loc(COLLAPSE_PHRASE)
			: loc(SHOW_MORE_CHANGES_PHRASE, { '#COUNT#': row.hiddenCount }),
		isExpanded,
		isLoading: details?.isLoading === true,
		errorMessage: Type.isStringFilled(errorMessage) ? errorMessage : '',
	};
}

function buildDisplayRow(row: ChangeFeedRow, context: DisplayRowsContext): FeedRow
{
	if (row.type === 'group')
	{
		return {
			type: 'group',
			key: row.key,
			day: formatDay(row.timestamp),
			author: resolveAuthor(row.event, context.userNames),
			authorTypeLabel: resolveAuthorTypeLabel(row.event.authorType),
			aiInitiator: resolveAiInitiator(row.event, context.userNames),
		};
	}

	if (row.type === 'change')
	{
		return {
			type: 'change',
			key: row.key,
			eventId: row.event.id,
			index: row.index,
			kind: row.entry.kind,
			time: formatTime(row.timestamp),
			text: buildChangePhrase(row.entry),
		};
	}

	if (row.type === 'toggle')
	{
		return buildToggleRow(row, context);
	}

	const mark = resolveEventMark(row.event.eventType);

	return {
		type: 'event',
		key: row.key,
		id: row.event.id,
		time: formatTime(row.timestamp),
		eventTitle: resolveEventTitle(row.event.eventType),
		eventIcon: mark.icon,
		eventModifier: mark.modifier,
		versionLabel: resolveVersionLabel(row.event),
	};
}

/**
 * What the feed shows, apart from where its data comes from: the rows of the store are turned into
 * the words, dates and marks of the screen, so the template only lays them out.
 */
export function buildDisplayRows(feedRows: Array<ChangeFeedRow>, context: DisplayRowsContext): Array<FeedRow>
{
	return feedRows.map((row) => buildDisplayRow(row, context));
}
