import { Type } from 'main.core';

import { PORT_TYPES } from '../../shared/constants';
import { type Block, type Connection, type Port } from '../../shared/types';

import { buttonPortId } from './buttons';
import { TASK_NODE_ACTIVITY_TYPE } from './constants';

/** Diagram store surface the ports of a task node are kept in: nothing else of it is needed here. */
type DiagramPorts = {
	connections: Array<Connection>,
	setPorts: (blockId: string, ports: Array<Port>) => void,
	deleteConnectionByBlockIdAndPortId: (blockId: string, portId: string) => void,
};

function toInt(value: mixed, fallback: number): number
{
	const parsed = Number.parseInt(value, 10);

	return Number.isNaN(parsed) ? fallback : parsed;
}

/**
 * The buttons as the form carries them: a JSON string of the hidden field, or the plain array the
 * template keeps. Broken JSON reads as "no buttons", the way the activity reads it - the ports then
 * follow an empty configuration instead of staying out of sync with it.
 */
function toButtonList(value: mixed): Array<Object>
{
	if (Type.isArray(value))
	{
		return value.filter((button) => Type.isPlainObject(button));
	}

	if (!Type.isStringFilled(value))
	{
		return [];
	}

	try
	{
		return toButtonList(JSON.parse(value));
	}
	catch
	{
		return [];
	}
}

export function isTaskNodeBlock(block: ?Block): boolean
{
	return block?.activity?.Type === TASK_NODE_ACTIVITY_TYPE;
}

function portsOf(block: ?Block): Array<Port>
{
	return Type.isArray(block?.ports) ? block.ports : [];
}

export function outputPorts(block: ?Block): Array<Port>
{
	return portsOf(block).filter((port) => port.type === PORT_TYPES.output);
}

/**
 * The output ports the buttons ask for, in the order of the task (ALG-02). A port is named by the slot
 * of its button (MAP-01), so renaming a button only changes the title of its port and reordering only
 * changes the place of the port in the list - neither recreates the port, and the branch that continues
 * from the button survives both.
 */
export function wantedButtonPorts(buttonsValue: mixed): Array<Port>
{
	return toButtonList(buttonsValue)
		.map((button) => ({
			slot: toInt(button.Slot, -1),
			title: Type.isString(button.Title) ? button.Title : '',
			sort: toInt(button.Sort, 0),
		}))
		.filter((button) => button.slot >= 0)
		.sort((first, second) => first.sort - second.sort)
		.map((button) => ({
			id: buttonPortId(button.slot),
			title: button.title,
			type: PORT_TYPES.output,
		}))
	;
}

/** Whether a branch of the diagram continues through the port, in either direction. */
export function hasConnections(connections: ?Array<Connection>, blockId: string, portId: string): boolean
{
	return (Type.isArray(connections) ? connections : []).some((connection) => {
		const { sourceBlockId, sourcePortId, targetBlockId, targetPortId } = connection;

		return (sourceBlockId === blockId && sourcePortId === portId)
			|| (targetBlockId === blockId && targetPortId === portId)
		;
	});
}

/**
 * The button that owns each output port of a configuration, by the id of that port (MAP-01). A button
 * keeps its id for good, so the map tells the answer a slot belongs to from the answer that held the
 * slot before.
 */
function buttonOwnerByPort(buttonsValue: mixed): Map<string, string>
{
	const owners = new Map();

	toButtonList(buttonsValue).forEach((button) => {
		const slot = toInt(button.Slot, -1);

		if (slot >= 0)
		{
			owners.set(buttonPortId(slot), Type.isString(button.Id) ? button.Id : '');
		}
	});

	return owners;
}

/**
 * Whether the slot has changed hands. A configuration that names no id for a button says nothing about
 * the owner of its slot, and the slot alone decides then, the way it did.
 */
function isOtherButton(before: ?string, after: ?string): boolean
{
	return Type.isStringFilled(before) && Type.isStringFilled(after) && before !== after;
}

/**
 * The output ports the buttons of the node stop owning with the save: the slot is gone from the
 * configuration, or it now belongs to another button. A slot a deleted button frees is handed to the
 * next button added, so the port alone does not say whose branch it carries - by its id only, the
 * branch of the deleted answer would silently continue the answer that took its slot.
 *
 * `buttonsBefore` is the configuration the node is saved with, and has to be read before the save
 * replaces the activity of the block.
 */
export function releasedButtonPorts(
	block: ?Block,
	buttonsBefore: mixed,
	buttonsAfter: mixed,
): Array<Port>
{
	const ownerBefore = buttonOwnerByPort(buttonsBefore);
	const ownerAfter = buttonOwnerByPort(buttonsAfter);

	return outputPorts(block).filter((port) => (
		!ownerAfter.has(port.id)
		|| isOtherButton(ownerBefore.get(port.id), ownerAfter.get(port.id))
	));
}

/**
 * Released ports a branch of the diagram still continues from. Asked before the save: the ports are
 * still on the block, so the connections that would be cut are still there to be found.
 */
export function portsLosingBranch(
	diagram: DiagramPorts,
	block: ?Block,
	released: Array<Port>,
): Array<Port>
{
	return released.filter((port) => hasConnections(diagram.connections, block.id, port.id));
}

/**
 * ALG-02: brings the output ports of the block to the buttons of the node. The branch of every released
 * port is cut here - the author has confirmed it before the save (AC-012).
 */
export function syncButtonPorts(
	diagram: DiagramPorts,
	block: ?Block,
	want: Array<Port>,
	released: Array<Port>,
): void
{
	// Ports of any other kind are none of the business of the buttons: the input port of the node and
	// its aux ports keep both their place and their connections.
	const keptPorts = portsOf(block).filter((port) => port.type !== PORT_TYPES.output);

	released.forEach((port) => {
		if (hasConnections(diagram.connections, block.id, port.id))
		{
			diagram.deleteConnectionByBlockIdAndPortId(block.id, port.id);
		}
	});

	diagram.setPorts(block.id, [...keptPorts, ...want]);
}
