import { BIcon, Outline } from 'ui.icon-set.api.vue';
import { watch, computed, nextTick, onBeforeUnmount, onMounted, ref, toValue } from 'ui.vue3';
import { Loc } from 'main.core';
import { useCanvasFocus, useKeyboardShortcuts } from 'ui.block-diagram';

import { diagramStore } from '../../../entities/blocks';
import { useDebugStatus } from '../../composables';
import { clearFocusAnchor, FocusAnchor, setFocusAnchor } from '../../utils/focus-rescue';
import { DEBUG_BAR_LABELS } from '../../../entities/debug-bar/constants';

// @vue/component
export const DebugButton = {
	name: 'DebugButton',
	components: {
		BIcon,
	},
	props: {
		// Comes from app.js: shared must not reach up to the action catalog of entities/hotkeys.
		actionId: {
			type: String,
			required: true,
		},
		// Comes from app.js for the same reason: the state of the panel lives in entities/app.
		isShownDebugBar: {
			type: Boolean,
			default: false,
		},
		isTestRunActive: {
			type: Boolean,
			default: false,
		},
	},
	// Mounted only while the feature is on (see app.js `v-if="isDebugBarAvailable"`), so the
	// shortcut it registers here is live only where the button itself would be.
	setup(props)
	{
		const { isDebugEnabled, isLoading, toggleDebug, checkDebugStatus } = useDebugStatus(() => props.isTestRunActive);
		const diagramStoreObj = diagramStore();
		const { returnFocusToCanvas } = useCanvasFocus();
		const root = ref(null);

		// A press that closed the panel leaves the keyboard on nothing, so the canvas takes it back.
		// A press that opened the panel moves nothing: the panel is where the user is heading.
		async function toggleDebugFromKeyboard(): Promise<void>
		{
			const wasPanelShown = props.isShownDebugBar;

			await toggleDebug();
			// The panel gives up its exclusive claim on Escape in a watcher, and the canvas takes the
			// focus only once that stack is empty.
			await nextTick();

			if (!wasPanelShown || props.isShownDebugBar)
			{
				return;
			}

			// A layer below still holding Escape refuses the canvas, and the panel the focus may have
			// stood on is gone: the button the press came through is what is left on the screen.
			if (!returnFocusToCanvas())
			{
				toValue(root)?.focus({ preventScroll: true });
			}
		}

		// The panel of the debug bar is mounted apart from the button and closes to it the same way.
		onMounted(() => {
			setFocusAnchor(FocusAnchor.debugButton, toValue(root));
		});

		onBeforeUnmount(() => {
			clearFocusAnchor(FocusAnchor.debugButton, toValue(root));
		});

		useKeyboardShortcuts([
			{
				actionId: props.actionId,
				// toggleDebug() already refuses a press while a request of its own is in flight.
				handler: () => { void toggleDebugFromKeyboard(); },
			},
		]);

		watch(
			() => diagramStoreObj.templateId,
			(newTemplateId) => {
				if (newTemplateId && newTemplateId > 0)
				{
					checkDebugStatus(newTemplateId);
				}
			},
			{ immediate: true },
		);

		const isHighlighted = computed(() => isDebugEnabled.value || props.isTestRunActive);

		const buttonTitle = computed(() => {
			if (props.isTestRunActive && !isDebugEnabled.value)
			{
				return Loc.getMessage(DEBUG_BAR_LABELS.BUTTON_TEST_RUN_TITLE) ?? '';
			}

			return isDebugEnabled.value
				? Loc.getMessage(DEBUG_BAR_LABELS.BUTTON_DISABLE_TITLE)
				: Loc.getMessage(DEBUG_BAR_LABELS.BUTTON_ENABLE_TITLE);
		});

		return {
			root,
			isHighlighted,
			isLoading,
			toggleDebug,
			buttonTitle,
			outline: Outline,
		};
	},
	template: `
		<button
			ref="root"
			@click="toggleDebug"
			:disabled="isLoading"
			:class="{
				'bp-debug-button': true,
				'bp-debug-button--active': isHighlighted,
				'bp-debug-button--loading': isLoading,
			}"
			:title="buttonTitle"
			:data-test-id="$testId('debugButton')"
		>
			<BIcon
				class="bp-debug-button__icon"
				:name="outline.BUG"
				:size="24"
			/>
		</button>
	`,
};
