import { Type } from 'main.core';

import { TITLE_FIELD_NAME } from '../../../shared/constants';
import { collectLegacyFormFields, type BrokenLinkFormField } from '../../../shared/utils';

/**
 * What a construction whose form stands on the screen answers an approach to a broken reference with
 * (TPL-01). Both panels that put such a form up answer the same way, and the panel asks whichever
 * construction the approach reached - so the answers belong to neither of them in particular.
 *
 * Spread into `methods` of the host and not worn as a mixin: a mixin merges its methods into the
 * instance, while `Component.methods` keeps only what the component itself declared. The forms are
 * driven through `{ ...EditExtendedAction.methods }` in the stands of the specs, where a method that
 * lives in a mixin is simply absent.
 *
 * The host is expected to keep `construction`, `settingsForm` and `nodeControls`, and to spend
 * `unregisterBrokenLinkForm` while cleaning up the form it registered.
 */
export const brokenLinkFormMethods = {
	/**
	 * Tells the panel about this form while it stands on the screen (TPL-01) and keeps the way to
	 * take it off again, which cleanupFormResources spends. The two answers are functions and not
	 * values: the panel asks them at the moment an approach reaches this construction, not now.
	 */
	registerBrokenLinkForm(): void
	{
		this.unregisterBrokenLinkForm = this.registerConstructionForm?.(
			this.construction.id,
			() => this.readBrokenLinkFields(),
			() => this.settingsForm,
		) ?? null;
	},

	/**
	 * The fields of this form as the panel reads them (TPL-01): the name of the control, its value
	 * and the caption the person reads next to it. A form the server described controls for answers
	 * from those descriptions and not from the markup - the controls are drawn asynchronously, and
	 * the values the references were found in are the saved ones the descriptions carry. A form
	 * that came as ready HTML has no descriptions, answers from its markup and addresses the rows of
	 * that markup on the way (prepareLegacyBrokenLinkFields).
	 *
	 * The two keys ALG-03 leaves out are none of these: the title of the node is edited by the panel
	 * and not by the form, and the comment of the editor is not asked for (`hideEditorComment`). The
	 * title is named here for the panel that keeps it among the controls; the one that drops it
	 * earlier (BASE_SETTINGS_EXCLUDED_FIELD_NAMES of prepareSettingsControls, which reads the very
	 * `property.FieldName` this name is taken from) passes over a set that never holds it.
	 *
	 * A hidden field stays among them: its row is either not drawn at all or folded away, and that is
	 * what the approach reports as a field it cannot bring on the screen instead of settling for it.
	 */
	readBrokenLinkFields(): Array<BrokenLinkFormField>
	{
		if (!Type.isArray(this.nodeControls))
		{
			return this.prepareLegacyBrokenLinkFields();
		}

		return this.nodeControls
			.filter((field: Object) => {
				return Type.isStringFilled(field.fieldName) && field.fieldName !== TITLE_FIELD_NAME;
			})
			.map((field: Object) => ({
				name: field.fieldName,
				value: field.value,
				title: field.property?.Name ?? '',
			}))
		;
	},

	/**
	 * The fields of a form that came as ready HTML (ALG-03), read from the markup at the moment of
	 * a request: it is the only source there is, and the person has been editing it since. Reading
	 * such a form writes to it as well - addressLegacyFieldRows - which is what makes this a
	 * preparation and not a read.
	 */
	prepareLegacyBrokenLinkFields(): Array<BrokenLinkFormField>
	{
		const fields = collectLegacyFormFields(this.settingsForm);
		this.addressLegacyFieldRows(fields);

		return fields;
	},

	/**
	 * Writes the address of the row of every field read off the markup (DTO-01): such a row carries
	 * no id of its own, while the panel looks a row up by one. The address goes on the row the field
	 * was found on and on no other - a multiple control clones the markup of its rows, and an id
	 * standing on all of them would be carried into the copy.
	 *
	 * Done together with the read and not at the render of the form: the rows of a multiple control
	 * appear while the person edits, and a row that came after the render would be left without an
	 * address.
	 */
	addressLegacyFieldRows(fields: Array<BrokenLinkFormField>): void
	{
		fields.forEach(({ name, row }: BrokenLinkFormField) => {
			// An id already on the row belongs to the markup of the activity: taken over, the row
			// would be lost to whoever wrote it, and the approach settles for the card instead.
			if (row && !Type.isStringFilled(row.id))
			{
				row.id = `row_${name}`;
			}
		});
	},
};
