import { Event, Loc, Text } from 'main.core';
import { useBlockDiagram, useContextMenu } from 'ui.block-diagram';
import { Outline } from 'ui.icon-set.api.vue';
import { BInput, InputDesign, InputSize } from 'ui.system.input.vue';
import { type MenuItemOptions } from 'ui.vue3.components.menu';
import { Popup } from 'ui.vue3.components.popup';

import { IconButton } from '../../../../shared/ui';

import { poolLaneTitle } from '../../lib';

import './pool-lane.css';

const ADD_LANE_ARIA_LABEL_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_LANE_ADD_ARIA_LABEL';
const TITLE_ARIA_LABEL_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_LANE_TITLE_ARIA_LABEL';
const TITLE_POPUP_ARIA_LABEL_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_LANE_TITLE_POPUP_ARIA_LABEL';

const ADD_BUTTON_SIZE = 16;
// In model pixels, so the gap between the button and the menu holds at any scale of the canvas.
const MENU_OFFSET_LEFT = 6;

// The window of the name is drawn outside the canvas, so its numbers are screen pixels and the zoom
// leaves them alone. Wide enough for a name, narrow enough to stay a window of one field.
const TITLE_POPUP_WIDTH = 240;
const TITLE_POPUP_OFFSET_TOP = 4;

// The press, not the click, ends the editing: the control under the cursor gets its click only
// after this one, so it acts on a name that is already saved and already put into the history.
// Any button ends it, so a right press that opens the pool menu saves the name too.
const OUTSIDE_COMMIT_EVENT = 'mousedown';

type Setup = {
	iconSet: { [string]: string },
	zoom: number,
	addButtonSize: number,
	showMenu: (
		point: { clientX: number, clientY: number },
		options: ?{ items: Array<MenuItemOptions> },
	) => void,
	InputDesign: { [string]: string },
	InputSize: { [string]: string },
};

type PoolLaneData = {
	editedTitle: string,
	focusRestored: boolean,
	titleAnchor: ?HTMLElement,
	titlePopupId: string,
};

// While an IME composes, Enter accepts the suggested variant and Escape drops it: both keys belong
// to the composition, not to the editor, and the field still holds the value from before it.
// Engines older than isComposing report the same state as keyCode 229.
function isComposingKey(event: KeyboardEvent): boolean
{
	return event.isComposing === true || event.keyCode === 229;
}

// @vue/component
export const PoolLane = {
	name: 'PoolLane',
	components: {
		BInput,
		IconButton,
		Popup,
	},
	props: {
		// the pool the lane belongs to: lane ids repeat from pool to pool, the block id does not
		blockId: {
			type: String,
			required: true,
		},
		// one item of node.poolLanes: an id and, once it is given one, a title
		lane: {
			type: Object,
			required: true,
		},
		// the lanes of a pool are numbered from one, their array from zero
		index: {
			type: Number,
			required: true,
		},
		/** @type Array<MenuItemOptions> */
		menuItems: {
			type: Array,
			default: () => ([]),
		},
		// set for the lane an insert has just added, and dropped again by the feature that set it
		highlighted: {
			type: Boolean,
			default: false,
		},
		// set for the lane a drag of an activity aims at, and dropped with the end of the gesture
		dropTarget: {
			type: Boolean,
			default: false,
		},
		// the mode belongs to the pool: a menu item and the caption itself switch the same one on
		editing: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['editRequest', 'confirm', 'cancel'],
	setup(): Setup
	{
		// Nameless on purpose: a named menu holds the top panel of its block open, and the lane would
		// then fight the pool for that panel.
		const { showMenu } = useContextMenu();
		const { zoom } = useBlockDiagram();

		return {
			iconSet: Outline,
			zoom,
			addButtonSize: ADD_BUTTON_SIZE,
			showMenu,
			InputDesign,
			InputSize,
		};
	},
	data(): PoolLaneData
	{
		return {
			editedTitle: '',
			focusRestored: false,
			// The window hangs on the caption, and the caption is drawn before it: the element is kept
			// here rather than read off the refs, so the options of the window are recomputed once the
			// anchor is there. Vue leaves a DOM node unwrapped, so what is stored is the node itself.
			titleAnchor: null,
			// The id names the layer in the DOM, and the wrapper of the window hands it to Teleport as a
			// selector: born here rather than built out of the ids of the model, which carry no schema of
			// their own. One draw per instance - the lane asks the document for the layer by this name.
			titlePopupId: `bizprocdesigner-pool-lane-title-popup-${Text.getRandom()}`,
		};
	},
	computed: {
		title(): string
		{
			return poolLaneTitle(this.lane, this.index);
		},
		// The name of the button says which lane it belongs to: the buttons of a pool stand in one
		// column, and read one after another they are told apart by nothing else.
		// a phrase that failed to load comes back as null, and the attribute takes a string
		addLaneAriaLabel(): string
		{
			return Loc.getMessage(ADD_LANE_ARIA_LABEL_MESSAGE_ID, { '#TITLE#': this.title }) ?? '';
		},
		// a phrase that failed to load comes back as null, and the attribute takes a string
		titleAriaLabel(): string
		{
			return Loc.getMessage(TITLE_ARIA_LABEL_MESSAGE_ID) ?? '';
		},
		// The window is named by the lane it was opened for, and the field inside it keeps the name of
		// a field: one name said twice tells the reader nothing the first one did not.
		// a phrase that failed to load comes back as null, and the option takes a string
		titlePopupAriaLabel(): string
		{
			return Loc.getMessage(TITLE_POPUP_ARIA_LABEL_MESSAGE_ID, { '#TITLE#': this.title }) ?? '';
		},
		// The button is the whole way into the menu, so it goes where the menu has nothing to offer:
		// the write lock and the feature code empty the array, the ceiling leaves a disabled item in it.
		hasMenu(): boolean
		{
			return this.menuItems.length > 0;
		},
		titlePopupOptions(): Object
		{
			return {
				id: this.titlePopupId,
				className: 'editor-chart-pool-lane-title-popup',
				bindElement: this.titleAnchor,
				targetContainer: document.body,
				width: TITLE_POPUP_WIDTH,
				offsetTop: TITLE_POPUP_OFFSET_TOP,
				// the inset is the one of the design system, so the window keeps none of its own
				padding: 0,
				borderRadius: 'var(--ui-border-radius-md)',
				// A press past the window writes the name, so the window is not allowed to close on
				// its own: auto-hide would take it down before the press that keeps the name is read.
				autoHide: false,
				closeByEsc: true,
				// The window lives in `document.body`, at the very end of the tab order, and holds the
				// single field it was opened for: the trap takes the focus into it. Giving the focus
				// back is the business of the lane - it marks the caption first - so the trap does not
				// restore it itself.
				focusTrap: { initialFocus: 'input', restoreFocus: false },
				ariaLabel: this.titlePopupAriaLabel,
			};
		},
	},
	watch: {
		editing(editing: boolean): void
		{
			if (editing)
			{
				this.startEditing();
			}
			else
			{
				this.stopEditing();
			}
		},
	},
	mounted(): void
	{
		this.titleAnchor = this.$refs.titleBox;

		// the edit mode may come with the very first render, not only as a prop change
		if (this.editing)
		{
			this.startEditing();
		}
	},
	beforeUnmount(): void
	{
		this.unbindOutsideCommit();
	},
	methods: {
		onShowMenu(): void
		{
			const buttonEl = this.$refs.addButton?.$el;
			const { top = 0, right = 0 } = buttonEl?.getBoundingClientRect() ?? {};

			this.showMenu(
				{ clientX: right + (MENU_OFFSET_LEFT * this.zoom), clientY: top },
				{ items: this.menuItems },
			);
		},
		startEditing(): void
		{
			// the lane carries its own name only once it has one: the number belongs to the place
			this.editedTitle = this.lane.title ?? '';
			this.bindOutsideCommit();

			this.$nextTick(() => {
				this.$refs.titleInput?.focus();
				// BInput does not expose select(), so full selection goes through its own input
				this.$refs.titleInput?.$el?.querySelector('input')?.select();
			});
		},
		stopEditing(): void
		{
			// the focused input goes away with the window: the focus has to move to the caption itself
			const holdsFocus = this.isInsideTitleEditor(document.activeElement);
			this.unbindOutsideCommit();

			if (holdsFocus)
			{
				// the focus is given back, not navigated to: no ring of the keyboard navigation for it
				this.focusRestored = document.activeElement !== this.$refs.titleBox;
				this.$nextTick(() => {
					this.$refs.titleBox?.focus({ preventScroll: true });
					if (document.activeElement !== this.$refs.titleBox)
					{
						// only a blur of the caption drops the mark, and a focus that never landed brings none
						this.focusRestored = false;
					}
				});
			}
		},
		bindOutsideCommit(): void
		{
			// capture: the press is caught before the pressed control stops it or acts on it
			Event.bind(document, OUTSIDE_COMMIT_EVENT, this.onPressOutside, { capture: true });
		},
		unbindOutsideCommit(): void
		{
			Event.unbind(document, OUTSIDE_COMMIT_EVENT, this.onPressOutside, { capture: true });
		},
		requestEdit(): void
		{
			if (this.editing)
			{
				return;
			}

			this.$emit('editRequest');
		},
		onConfirm(): void
		{
			this.$emit('confirm', this.editedTitle.trim());
		},
		onCancel(): void
		{
			this.$emit('cancel');
		},
		// the default action stays with the composition, so it is dropped only for a key the
		// editor itself takes
		onEnterKey(event: KeyboardEvent): void
		{
			if (isComposingKey(event))
			{
				return;
			}

			event.preventDefault();
			this.onConfirm();
		},
		onEscapeKey(event: KeyboardEvent): void
		{
			if (isComposingKey(event))
			{
				return;
			}

			event.preventDefault();
			this.onCancel();
		},
		onBlur(): void
		{
			// the caption is left: the next focus on it is navigation again and shows the ring
			this.focusRestored = false;
		},
		// Anything that takes the window down on its own - Escape read by the window itself, a layer
		// closing above it - ends the editing the way Escape does: an unconfirmed name is not written.
		onPopupClose(): void
		{
			if (this.editing)
			{
				this.onCancel();
			}
		},
		// The window is drawn outside the lane, so what counts as inside is the caption and the window
		// together, not the subtree of the lane. The layer is asked for by its id rather than held:
		// it is created and taken down by the popup itself, and the answer has to be what is there now.
		isInsideTitleEditor(target: ?EventTarget): boolean
		{
			return this.$refs.titleBox?.contains(target) === true
				|| document.getElementById(this.titlePopupId)?.contains(target) === true;
		},
		onPressOutside(event: MouseEvent): void
		{
			if (!this.isInsideTitleEditor(event.target))
			{
				this.onConfirm();
			}
		},
	},
	template: `
		<div
			class="editor-chart-pool-lane"
			:class="{ '--highlighted': highlighted, '--drop-target': dropTarget }"
			:data-testid="$testId('bizprocdesigner-pool-lane', blockId, lane.id)"
		>
			<div class="editor-chart-pool-lane__column">
				<IconButton
					v-if="hasMenu"
					ref="addButton"
					class="editor-chart-pool-lane__add"
					:size="addButtonSize"
					:iconName="iconSet.PLUS_M"
					:color="'var(--ui-color-base-3)'"
					:aria-label="addLaneAriaLabel"
					aria-haspopup="menu"
					:data-testid="$testId('bizprocdesigner-pool-lane-add', blockId, lane.id)"
					@click="onShowMenu"
				/>
				<div
					ref="titleBox"
					class="editor-chart-pool-lane__title"
					:class="{ '--editing': editing, '--focus-restored': focusRestored }"
					:data-testid="$testId('bizprocdesigner-pool-lane-title', blockId, lane.id)"
					role="group"
					tabindex="0"
					aria-keyshortcuts="Enter"
					:aria-label="titleAriaLabel"
					@dblclick.stop="requestEdit"
					@keydown.enter.self.prevent="requestEdit"
					@blur="onBlur"
				>{{ title }}</div>
				<Popup
					v-if="editing && titleAnchor"
					:options="titlePopupOptions"
					@close="onPopupClose"
				>
					<div
						class="editor-chart-pool-lane-title-popup__content"
						:data-testid="$testId('bizprocdesigner-pool-lane-title-popup', blockId, lane.id)"
					>
						<BInput
							ref="titleInput"
							v-model="editedTitle"
							class="editor-chart-pool-lane-title-popup__input"
							:design="InputDesign.Grey"
							:size="InputSize.Md"
							:ariaLabel="titleAriaLabel"
							:data-testid="$testId('bizprocdesigner-pool-lane-title-input', blockId, lane.id)"
							stretched
							@keydown.enter="onEnterKey"
							@keydown.esc="onEscapeKey"
						/>
					</div>
				</Popup>
			</div>
			<div class="editor-chart-pool-lane__area"></div>
		</div>
	`,
};
