/**
 * Which lane an activity lands in, and the lane lists a move of it rewrites.
 *
 * The lane is decided by the centre of the activity: the last pool in block order that contains it
 * and has lanes, then the lane by the reconciled heights, the service zones going to the outer lanes.
 * Nothing here reads the store or the DOM.
 */

import { BLOCK_TYPES, isBackdropBlockType } from '../../../shared/constants';
import { CHROME_TOP } from '../constants';
import { laneCount, laneHeights } from './pool-geometry';

/**
 * @typedef {{ blockId: BlockId, laneId: string, index: number }} LaneTarget
 * @typedef {{ x: number, y: number, width: number, height: number }} ActivityRect
 */

/**
 * @param {Block} block
 * @returns {boolean}
 */
export function isLaneActivity(block)
{
	return !isBackdropBlockType(block.type);
}

/**
 * @param {Block} block
 * @returns {boolean}
 */
function isPool(block)
{
	return block.type === BLOCK_TYPES.POOL;
}

/**
 * @param {Block} pool
 * @param {number} x
 * @param {number} y
 * @returns {boolean}
 */
function containsPoint(pool, x, y)
{
	return x >= pool.position.x
		&& x <= pool.position.x + pool.dimensions.width
		&& y >= pool.position.y
		&& y <= pool.position.y + pool.dimensions.height
	;
}

/**
 * A point on a boundary between two lanes belongs to the lower one.
 *
 * @param {Block} pool
 * @param {number} y
 * @returns {number}
 */
function laneIndexAt(pool, y)
{
	const heights = laneHeights(pool);
	let laneBottom = pool.position.y + CHROME_TOP;

	for (const [index, height] of heights.entries())
	{
		laneBottom += height;
		if (y < laneBottom)
		{
			return index;
		}
	}

	return heights.length - 1;
}

/**
 * @param {Block} pool
 * @param {number} index
 * @returns {LaneTarget}
 */
function laneTarget(pool, index)
{
	return { blockId: pool.id, laneId: pool.node.poolLanes[index].id, index };
}

/**
 * @param {Array<Block>} blocks
 * @param {ActivityRect} rect
 * @returns {LaneTarget | null}
 */
export function laneTargetAt(blocks, rect)
{
	const x = rect.x + (rect.width / 2);
	const y = rect.y + (rect.height / 2);

	for (let index = blocks.length - 1; index >= 0; index--)
	{
		const block = blocks[index];
		if (isPool(block) && laneCount(block) > 0 && containsPoint(block, x, y))
		{
			return laneTarget(block, laneIndexAt(block, y));
		}
	}

	return null;
}

/**
 * @param {PoolLaneModel} lane
 * @returns {Array<BlockId> | null}
 */
function listedIds(lane)
{
	return Array.isArray(lane.activityIds) ? lane.activityIds : null;
}

/**
 * @param {Array<Block>} blocks
 * @param {BlockId} activityId
 * @returns {LaneTarget | null}
 */
export function listedLaneOf(blocks, activityId)
{
	for (const pool of blocks.filter((block) => isPool(block)))
	{
		const index = (pool.node?.poolLanes ?? []).findIndex((lane) => listedIds(lane)?.includes(activityId));
		if (index !== -1)
		{
			return laneTarget(pool, index);
		}
	}

	return null;
}

/**
 * @param {PoolLaneModel} lane
 * @param {BlockId} activityId
 * @param {boolean} isTarget
 * @returns {PoolLaneModel}
 */
function laneWithMembership(lane, activityId, isTarget)
{
	const ids = listedIds(lane);
	if (isTarget)
	{
		return ids?.includes(activityId) ? lane : { ...lane, activityIds: [...(ids ?? []), activityId] };
	}

	return ids?.includes(activityId) ? { ...lane, activityIds: ids.filter((id) => id !== activityId) } : lane;
}

/**
 * Copies of the pools whose lane lists change when the activity ends up in `target`, or outside any.
 *
 * @param {Array<Block>} blocks
 * @param {BlockId} activityId
 * @param {LaneTarget | null} target
 * @returns {Array<Block>}
 */
export function laneMembershipChanges(blocks, activityId, target)
{
	const changes = [];

	for (const pool of blocks.filter((block) => isPool(block)))
	{
		const lanes = pool.node?.poolLanes ?? [];
		const nextLanes = lanes.map((lane, index) => laneWithMembership(
			lane,
			activityId,
			target?.blockId === pool.id && target.index === index,
		));

		if (nextLanes.some((lane, index) => lane !== lanes[index]))
		{
			changes.push({ ...pool, node: { ...pool.node, poolLanes: nextLanes } });
		}
	}

	return changes;
}
