import { Event } from 'main.core';
import { storeToRefs } from 'ui.vue3.pinia';
import { onMounted, onUnmounted, toValue, watch } from 'ui.vue3';
import {
	isKeyboardBusyByOverlay,
	KEY_TOKEN,
	useBlockDiagram,
	useCanvasFocus,
} from 'ui.block-diagram';

import { useAppStore } from '../../../../entities/app';
import { useDebugBarStore } from '../../../../entities/debug-bar';
import { DebugBarPanel } from '../../../../entities/debug-bar/ui/debug-bar-panel/debug-bar-panel';
import { isEditableElement } from '../../../../shared/utils';
import { FocusAnchor, focusAnchoredElement } from '../../../../shared/utils/focus-rescue';

type DebugBarSetup = {
	isShownDebugBar: boolean,
	onClose: () => void,
};

// @vue/component
export const DebugBar = {
	name: 'DebugBarWidget',
	components: {
		DebugBarPanel,
	},
	setup(): DebugBarSetup
	{
		const appStore = useAppStore();
		const debugBarStore = useDebugBarStore();
		const { isShownDebugBar } = storeToRefs(appStore);
		const { inputState } = useBlockDiagram();
		const { returnFocusToCanvas } = useCanvasFocus();

		// Neither the claim nor the focus answer is display data.
		let escapeClaim = null;
		let isFieldFocused = isEditableElement(document.activeElement);

		function closePanel(): void
		{
			debugBarStore.hide();
			appStore.hideDebugBar();
		}

		/**
		 * Escape hides the panel the way the cross does and leaves the debug mode on the server as it
		 * is: switching that off is what the shortcut of the debug button does, and one key must not
		 * do both.
		 */
		function hidePanelByEscape(): void
		{
			if (isKeyboardBusyByOverlay())
			{
				return;
			}

			closePanel();

			// The own claim goes first: the canvas takes the focus only on an empty stack, and the
			// watcher that keeps the claim in step has not run yet.
			releaseEscapeClaim();

			// A layer below still holding Escape refuses the canvas, and the panel the focus stood on
			// is already gone: the button the panel opens from is what is left on the screen.
			if (!returnFocusToCanvas())
			{
				focusAnchoredElement(FocusAnchor.debugButton);
			}
		}

		// Both halves are idempotent: the widget asks for a key it may already hold and gives up one
		// it may have given up already.
		function claimEscape(): void
		{
			if (escapeClaim === null)
			{
				escapeClaim = inputState.onExclusive(KEY_TOKEN.ESCAPE, hidePanelByEscape);
			}
		}

		function releaseEscapeClaim(): void
		{
			escapeClaim?.();
			escapeClaim = null;
		}

		// The exclusive channel reaches past the layers above the canvas, so a claim held while a
		// popup is up would take Escape from the popup, which answers the very same key, and a claim
		// held over a text field being edited elsewhere would take it from the inline rename of a
		// node first of all - that field cancels by the very same key.
		function syncEscapeClaim(): void
		{
			if (toValue(isShownDebugBar) && !isFieldFocused && !isKeyboardBusyByOverlay())
			{
				claimEscape();

				return;
			}

			releaseEscapeClaim();
		}

		// `focusout` names where the focus goes next and `focusin` where it landed. Reading
		// `activeElement` instead would miss a focus that fell to the body: no `focusin` follows it.
		function onFocusChanged(event: FocusEvent): void
		{
			isFieldFocused = isEditableElement(
				event.type === 'focusout' ? event.relatedTarget : event.target,
			);
			syncEscapeClaim();
		}

		watch(isShownDebugBar, syncEscapeClaim, { immediate: true });

		onMounted(() => {
			Event.bind(document, 'focusin', onFocusChanged);
			Event.bind(document, 'focusout', onFocusChanged);
		});

		onUnmounted(() => {
			Event.unbind(document, 'focusin', onFocusChanged);
			Event.unbind(document, 'focusout', onFocusChanged);
			releaseEscapeClaim();
		});

		return {
			isShownDebugBar,
			onClose: closePanel,
		};
	},
	template: '<DebugBarPanel v-if="isShownDebugBar" @close="onClose"/>',
};
