import { MIN_RUNNING_DISPLAY_MS, TEST_RUN_NODE_STATES, type TestRunNodeState } from '../constants';

type NodeStates = { [blockId: string]: TestRunNodeState };

export type NodeStateChange = {
	blockId: string;
	state: TestRunNodeState;
};

export class NodeStateDisplay
{
	#onChange: (states: NodeStates) => void;
	#actual: NodeStates = {};
	#displayed: NodeStates = {};
	#runningSince: { [blockId: string]: number } = {};
	#holdTimers: Map<string, number> = new Map();
	#queue: string[] = [];
	#queueTimer: number | null = null;
	#isChanged: boolean = false;

	constructor(onChange: (states: NodeStates) => void)
	{
		this.#onChange = onChange;
	}

	apply(changes: NodeStateChange[], canReplay: boolean): void
	{
		// the journal repeats a trace of a node (a second close comes after the next node starts)
		const newChanges = changes.filter(({ blockId, state }) => state !== this.#displayed[blockId]);

		changes.forEach(({ blockId, state }) => {
			this.#actual[blockId] = state;
		});

		new Set(newChanges.map(({ blockId }) => blockId)).forEach((blockId) => {
			this.#showActual(blockId, canReplay);
		});

		this.#playNext();
		this.#publish();
	}

	settle(): void
	{
		this.#clearTimers();
		this.#displayed = { ...this.#actual };
		this.#isChanged = true;
		this.#publish();
	}

	reset(): void
	{
		this.#clearTimers();
		this.#actual = {};
		this.#displayed = {};
		this.#runningSince = {};
		this.#isChanged = true;
		this.#publish();
	}

	#showActual(blockId: string, canReplay: boolean): void
	{
		const state = this.#actual[blockId];

		if (this.#queue.includes(blockId))
		{
			return;
		}

		if (this.#displayed[blockId] === TEST_RUN_NODE_STATES.RUNNING)
		{
			this.#holdRunning(blockId);

			return;
		}

		if (canReplay && (this.#isReplaying() || state !== TEST_RUN_NODE_STATES.RUNNING))
		{
			this.#queue.push(blockId);

			return;
		}

		this.#display(blockId, state);
	}

	#holdRunning(blockId: string): void
	{
		clearTimeout(this.#holdTimers.get(blockId));
		this.#holdTimers.delete(blockId);

		if (this.#actual[blockId] === TEST_RUN_NODE_STATES.RUNNING)
		{
			return;
		}

		const remaining = this.#runningSince[blockId] + MIN_RUNNING_DISPLAY_MS - Date.now();
		if (remaining <= 0)
		{
			this.#display(blockId, this.#actual[blockId]);

			return;
		}

		this.#holdTimers.set(blockId, setTimeout(() => {
			this.#holdTimers.delete(blockId);
			this.#display(blockId, this.#actual[blockId]);
			this.#publish();
		}, remaining));
	}

	#playNext(): void
	{
		if (this.#queueTimer !== null || this.#queue.length === 0)
		{
			return;
		}

		const blockId = this.#queue.shift();
		this.#display(blockId, TEST_RUN_NODE_STATES.RUNNING);

		this.#queueTimer = setTimeout(() => {
			this.#queueTimer = null;
			this.#holdRunning(blockId);
			this.#playNext();
			this.#publish();
		}, MIN_RUNNING_DISPLAY_MS);
	}

	#isReplaying(): boolean
	{
		return this.#queueTimer !== null || this.#queue.length > 0;
	}

	#display(blockId: string, state: TestRunNodeState): void
	{
		if (state === TEST_RUN_NODE_STATES.RUNNING && this.#displayed[blockId] !== TEST_RUN_NODE_STATES.RUNNING)
		{
			this.#runningSince[blockId] = Date.now();
		}

		this.#isChanged ||= this.#displayed[blockId] !== state;
		this.#displayed[blockId] = state;
	}

	#publish(): void
	{
		if (!this.#isChanged)
		{
			return;
		}

		this.#isChanged = false;
		this.#onChange({ ...this.#displayed });
	}

	#clearTimers(): void
	{
		this.#holdTimers.forEach((timerId) => clearTimeout(timerId));
		this.#holdTimers.clear();
		clearTimeout(this.#queueTimer);
		this.#queueTimer = null;
		this.#queue = [];
	}
}
