import { Loc } from 'main.core';
import { PopupManager } from 'main.popup';
import { AirButtonStyle, Button } from 'ui.buttons';
import { AlertDesign } from 'ui.system.alert';
import { Alert } from 'ui.system.alert.vue';
import { Dialog } from 'ui.system.dialog';
import { BInput, InputSize } from 'ui.system.input.vue';
import { HeadlineXs, TextMd } from 'ui.system.typography.vue';
import { markRaw } from 'ui.vue3';
import { mapActions, mapState } from 'ui.vue3.pinia';
import { normalizeSearchText } from 'bizprocdesigner.lib.search';

import { EDITOR_ACTION_GROUPS, getEditorActionCatalog, useHotkeysStore } from '../../../../entities/hotkeys';
import { HotkeysActionRow } from '../hotkeys-action-row/hotkeys-action-row';
import { HotkeysComboCapture } from '../hotkeys-combo-capture/hotkeys-combo-capture';

import './style.css';

// ui.system.dialog fixes the width (it passes width as both minWidth and maxWidth) and the
// popup only shifts a box that does not fit, so the viewport cap has to be applied here.
const DIALOG_WIDTH = 640;
const DIALOG_VIEWPORT_GAP = 32;

const POPUP_SELECTOR = '.popup-window';
const DIALOG_HEADER_SELECTOR = '.ui-system-dialog__header';

// @vue/component
export const HotkeysDialog = {
	name: 'HotkeysDialog',
	components: {
		Alert,
		BInput,
		HeadlineXs,
		HotkeysActionRow,
		HotkeysComboCapture,
		TextMd,
	},
	emits: ['close'],
	setup(): Object
	{
		return { AlertDesign, InputSize };
	},
	data(): Object
	{
		return {
			instance: null,
			query: '',
			captureActionId: null,
			saveButton: null,
			resetAllButton: null,
		};
	},
	computed: {
		...mapState(useHotkeysStore, [
			'isMac',
			'defaultCombos',
			'effectiveBindings',
			'errorMessage',
			'hasSaveError',
			'hasOverrides',
			'hasUnsavedChanges',
		]),
		captureAction(): ?Object
		{
			return this.actionRows.find((row) => row.id === this.captureActionId) ?? null;
		},
		/**
		 * The catalog with its names resolved. Depends on the platform alone, so the phrases are read
		 * and normalized once for the whole panel instead of on every keystroke of the search.
		 */
		actionRows(): Array<Object>
		{
			return getEditorActionCatalog(this.isMac).map((editorAction) => {
				const label = this.loc(editorAction.labelKey);

				return {
					id: editorAction.id,
					group: editorAction.group,
					label,
					searchKey: normalizeSearchText(label),
					isReassignable: editorAction.isReassignable,
				};
			});
		},
		searchQuery(): string
		{
			return normalizeSearchText(this.query.trim());
		},
		visibleGroups(): Array<Object>
		{
			const query = this.searchQuery;
			const matched = query === ''
				? this.actionRows
				: this.actionRows.filter((row) => row.searchKey.includes(query))
			;

			return EDITOR_ACTION_GROUPS
				.map((group) => ({
					id: group.id,
					label: this.loc(group.labelKey),
					actions: matched
						.filter((row) => row.group === group.id)
						.map((row) => this.toActionView(row))
					,
				}))
				.filter((group) => group.actions.length > 0)
			;
		},
	},
	watch: {
		hasUnsavedChanges(hasChanges: boolean): void
		{
			this.saveButton?.setDisabled(!hasChanges);
		},
		hasOverrides(hasAny: boolean): void
		{
			this.resetAllButton?.setDisabled(!hasAny);
		},
	},
	mounted(): void
	{
		this.getDialog().setContent(this.$refs.content);
		this.getDialog().show();
		this.makeDialogDraggable();
		this.saveButton.setDisabled(!this.hasUnsavedChanges);
		this.resetAllButton.setDisabled(!this.hasOverrides);
	},
	unmounted(): void
	{
		this.instance?.hide();
	},
	methods: {
		...mapActions(useHotkeysStore, ['discardDraft', 'resetAllDraftCombos', 'resetDraftCombo', 'save']),
		loc(phraseCode: string): string
		{
			return Loc.getMessage(phraseCode) ?? '';
		},
		startCapture(actionId: string): void
		{
			this.captureActionId = actionId;
		},
		stopCapture(): void
		{
			this.captureActionId = null;
		},
		/**
		 * An action without a combo in the effective bindings has none at all - the merge of the store
		 * drops the entry when a user takes the combo away, and an action of the catalog may ship
		 * without one to begin with.
		 */
		toActionView(row: Object): Object
		{
			const combo = this.effectiveBindings.get(row.id) ?? '';

			return {
				id: row.id,
				label: row.label,
				combo,
				isCustom: combo !== (this.defaultCombos.get(row.id) ?? ''),
				isReassignable: row.isReassignable,
			};
		},
		getDialog(): Dialog
		{
			if (!this.instance)
			{
				this.instance = markRaw(this.createDialog());
			}

			return this.instance;
		},
		createDialog(): Dialog
		{
			const close = new Button({
				text: this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_BUTTON_CLOSE'),
				useAirDesign: true,
				style: AirButtonStyle.OUTLINE,
				dataset: { testid: 'bizprocdesigner-editor-hotkeys-close' },
			});
			const save = new Button({
				text: this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_BUTTON_SAVE'),
				useAirDesign: true,
				style: AirButtonStyle.FILLED,
				dataset: { testid: 'bizprocdesigner-editor-hotkeys-save' },
			});
			const resetAll = new Button({
				text: this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_BUTTON_RESET_ALL'),
				useAirDesign: true,
				style: AirButtonStyle.PLAIN,
				dataset: { testid: 'bizprocdesigner-editor-hotkeys-reset-all' },
			});

			this.saveButton = markRaw(save);
			this.resetAllButton = markRaw(resetAll);

			const dialog = new Dialog({
				title: this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_TITLE'),
				leftButtons: [resetAll],
				rightButtons: [save, close],
				events: {
					onHide: this.closePopup,
				},
				width: Math.min(DIALOG_WIDTH, window.innerWidth - DIALOG_VIEWPORT_GAP),
				// The window is meant to stay open while a person edits the scheme, and every click on
				// the scheme lands outside it. Closing is left to the close button and the cross.
				closeByClickOutside: false,
				// Unlike the other windows of the editor: inside this panel Escape cancels the recording
				// of a combination, so the same key must not take the whole window away with it.
				closeByEsc: false,
			});

			close.bindEvent('click', () => {
				dialog.hide();
			});
			save.bindEvent('click', () => {
				void this.save();
			});
			resetAll.bindEvent('click', () => {
				this.stopCapture();
				this.resetAllDraftCombos();
			});

			return dialog;
		},
		/**
		 * The window stays open while a person edits the scheme, so it has to move off whatever it covers.
		 * ui.system.dialog keeps its popup private and takes no draggable option, and the popup is reached
		 * by the id its container carries. The handle is the header: the list below it stays scrollable and
		 * selectable. The content is set and shown before this runs - a re-rendered header would be a new
		 * element, and the handle would be bound to the previous one.
		 */
		makeDialogDraggable(): void
		{
			const container = this.$refs.content?.closest(POPUP_SELECTOR);
			const header = container?.querySelector(DIALOG_HEADER_SELECTOR);
			if (!header)
			{
				return;
			}

			PopupManager.getPopupById(container.id)?.setDraggable({ element: header, restrict: true });
		},
		/**
		 * Closing the panel is the way out of the unsaved changes: the store outlives the window, and a
		 * draft left behind would meet the user again the next time the panel is opened, as if it had
		 * been saved.
		 */
		closePopup(): void
		{
			this.discardDraft();
			this.$emit('close');
		},
	},
	template: `
		<div
			ref="content"
			class="bizprocdesigner-hotkeys"
			data-testid="bizprocdesigner-editor-hotkeys"
		>
			<div class="bizprocdesigner-hotkeys__search">
				<BInput
					v-model="query"
					:size="InputSize.Md"
					:placeholder="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_SEARCH_PLACEHOLDER')"
					:withSearch="query === ''"
					:withClear="query !== ''"
					stretched
					data-testid="bizprocdesigner-editor-hotkeys-search"
					@clear="query = ''"
				/>
			</div>
			<div class="bizprocdesigner-hotkeys__list" data-testid="bizprocdesigner-editor-hotkeys-list">
				<section
					v-for="group in visibleGroups"
					:key="group.id"
					class="bizprocdesigner-hotkeys__group"
					:data-group-id="group.id"
					data-testid="bizprocdesigner-editor-hotkeys-group"
				>
					<HeadlineXs
						tag="h3"
						class="bizprocdesigner-hotkeys__group-title"
						data-testid="bizprocdesigner-editor-hotkeys-group-title"
					>{{ group.label }}</HeadlineXs>
					<HotkeysActionRow
						v-for="action in group.actions"
						:key="action.id"
						:data-action-id="action.id"
						:label="action.label"
						:combo="action.combo"
						:isCustom="action.isCustom"
						:isReassignable="action.isReassignable"
						@assign="startCapture(action.id)"
						@reset="resetDraftCombo(action.id)"
					/>
				</section>
				<TextMd
					v-if="visibleGroups.length === 0"
					class="bizprocdesigner-hotkeys__empty"
					data-testid="bizprocdesigner-editor-hotkeys-empty"
				>
					{{ loc('BIZPROCDESIGNER_EDITOR_NOT_FOUND') }}
				</TextMd>
			</div>
			<HotkeysComboCapture
				v-if="captureAction !== null"
				:key="captureAction.id"
				:actionId="captureAction.id"
				:actionLabel="captureAction.label"
				@close="stopCapture"
			/>
			<Alert
				v-if="hasSaveError"
				:design="AlertDesign.tintedWarning"
				data-testid="bizprocdesigner-editor-hotkeys-save-error"
			>{{ errorMessage }}</Alert>
		</div>
	`,
};
