import { Runtime } from 'main.core';
import { PORT_TYPES } from '../../../shared/constants';
import { type Port, type Connection } from '../../../shared/types';
import { type Construction, type NodeSettings, type Rule, type TRuleCard } from '../types';
import { CONSTRUCTION_TYPES } from '../constants';
import { generateNextOutputPortId } from './port-ids';
import { getGroupRuleCards } from './rules-surface';

export type OutputReference = { portId: string; title: string };
export type AvailableOutput = OutputReference & { type: string };
export type OutputAddress = {
	ruleId: string;
	cardId: string;
	constructionId: string;
	previousExpression: Construction['expression'];
	createdConstruction: boolean;
	createdCard: boolean;
};
export type OutputCreation = {
	blockId: string;
	fetchId: number;
	port: OutputReference;
	addresses: OutputAddress[];
};

type OutputTarget = {
	rule: Rule;
	card: TRuleCard | null;
	construction: Construction | null;
};

export const hasConfiguredOutput = (rule: Rule): boolean => (
	rule.ruleCards.some((card) => card.constructions.some((construction) => (
		construction.type === CONSTRUCTION_TYPES.OUTPUT && Boolean(construction.expression?.portId)
	)))
);

export const collectOutputPorts = (ports: Port[], settings: NodeSettings | null): AvailableOutput[] => {
	const outputs = ports.filter((port) => [PORT_TYPES.output, PORT_TYPES.outputRelation].includes(port.type))
		.map((port) => ({ portId: port.id, title: port.title, type: port.type }))
	;
	for (const [collection, type] of [
		[settings?.rules, PORT_TYPES.output],
		[settings?.relations, PORT_TYPES.outputRelation],
	])
	{
		const references = [...(collection?.values() ?? [])]
			.flatMap((rule) => rule.ruleCards)
			.flatMap((card) => card.constructions)
			.filter((construction) => (
				construction.type === CONSTRUCTION_TYPES.OUTPUT && construction.expression?.portId
			))
			.map((construction) => ({ ...construction.expression, type }))
		;
		outputs.push(...references);
	}

	return outputs;
};

export const nextOutput = (ports: AvailableOutput[]): OutputReference => {
	const numberedPorts = ports.filter((port) => /^o\d+$/.test(port.portId))
		.map((port) => ({ id: port.portId, title: port.title, type: port.type }))
	;
	const titleNumber = ports.reduce((highest, port) => {
		const match = /^E(\d+)$/.exec(port.title ?? '');

		return match ? Math.max(highest, Number(match[1])) : highest;
	}, 0) + 1;

	return { portId: generateNextOutputPortId(numberedPorts), title: `E${titleNumber}` };
};

export const planOutputTargets = (
	rules: Map<string, Rule>,
	source: Construction,
	sourceRuleId: string,
	allRules: boolean,
): OutputTarget[] => {
	const targets: OutputTarget[] = [];
	for (const [ruleId, rule] of rules)
	{
		if ((!allRules && ruleId !== sourceRuleId) || hasConfiguredOutput(rule))
		{
			continue;
		}
		let target: OutputTarget | null = null;
		for (const card of rule.ruleCards)
		{
			const construction = card.constructions.find((item) => (
				ruleId === sourceRuleId ? item === source : item.type === CONSTRUCTION_TYPES.OUTPUT
			));
			if (construction)
			{
				target = { rule, card, construction };
				break;
			}
		}
		targets.push(target ?? { rule, card: getGroupRuleCards(rule.ruleCards).at(-1) ?? null, construction: null });
	}

	return targets;
};

const keepOutputConstruction = (
	construction: Construction,
	operation: OutputCreation,
	address: ?OutputAddress,
): boolean => {
	if (construction.type !== CONSTRUCTION_TYPES.OUTPUT
		|| construction.expression?.portId !== operation.port.portId)
	{
		return true;
	}

	if (address?.createdConstruction)
	{
		return false;
	}
	const expression = address
		? Runtime.clone(address.previousExpression)
		: { ...construction.expression, portId: null, title: null }
	;
	Object.assign(construction, { expression });

	return true;
};

const restoreRuleOutputReferences = (rule: Rule, operation: OutputCreation, addresses: OutputAddress[]): void => {
	for (const card of rule.ruleCards)
	{
		card.constructions = card.constructions.filter((construction) => keepOutputConstruction(
			construction,
			operation,
			addresses.find((address) => address.cardId === card.id && address.constructionId === construction.id),
		));
	}
	const ruleCards = rule.ruleCards.filter((card) => (
		card.constructions.length > 0 || !addresses.some((address) => address.cardId === card.id && address.createdCard)
	));
	Object.assign(rule, { ruleCards });
};

export const removeCreatedOutputReferences = (settings: NodeSettings | null, operation: OutputCreation): void => {
	for (const [collection, isRules] of [[settings?.rules, true], [settings?.relations, false]])
	{
		for (const [ruleId, rule] of collection ?? [])
		{
			const addresses = isRules ? operation.addresses.filter((address) => address.ruleId === ruleId) : [];
			restoreRuleOutputReferences(rule, operation, addresses);
		}
	}
};

export const isCreatedOutputConnection = (connection: Connection, operation: OutputCreation): boolean => (
	(connection.sourceBlockId === operation.blockId && connection.sourcePortId === operation.port.portId)
	|| (connection.targetBlockId === operation.blockId && connection.targetPortId === operation.port.portId)
);
