/**
 * The scrolling of an approach is an animation started by a press: a person who asked for less motion
 * is brought to the same place without the travel to it (WCAG 2.3.3).
 */
export function resolveScrollBehavior(): string
{
	return window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches === true ? 'auto' : 'smooth';
}

/**
 * Brings a row to the top of the scrolled area it lives in by moving that area alone: `scrollIntoView`
 * moves every scrollable ancestor, and at a large zoom on a narrow screen that carries the
 * surroundings of the panel along with it.
 *
 * The row is kept clear of the top edge by the `scroll-padding-top` of the area - the very offset
 * `scrollIntoView` would have honoured, standing for whatever is pinned over the area. An area that
 * declares none keeps the row clear by the offset the caller names.
 */
export function scrollRowIntoScrollArea(
	row: HTMLElement,
	container: HTMLElement,
	options: { fallbackOffset?: number } = {},
): void
{
	const paddingTop = Number.parseFloat(getComputedStyle(container).scrollPaddingTop);
	const offset = Number.isFinite(paddingTop) ? paddingTop : (options.fallbackOffset ?? 0);
	const top = row.getBoundingClientRect().top
		- container.getBoundingClientRect().top
		+ container.scrollTop
		- offset
	;

	container.scrollTo({ top: Math.max(top, 0), behavior: resolveScrollBehavior() });
}
