import { Loc } from 'main.core';
import { type BaseEvent } from 'main.core.events';
import { BannerDispatcher } from 'ui.banner-dispatcher';
import { Guide } from 'ui.tour';
import { nextTick } from 'ui.vue3';

import { usePublishMenuStore } from '../blocks/stores/publish-menu';
import { isOnboardingDismissed, markOnboardingDismissed } from './dismissed-flag';

const BANNER_ID = 'bizprocdesigner_pilot_publication_onboarding';

const PILOT_OPTION_SELECTOR = '[data-testid="bizprocdesigner-editor-publish-user-option"]';
const PILOT_BADGE_SELECTOR = '[data-testid="bizprocdesigner-pilot-badge"]';

/**
 * The hold of the publish menu the tour needs. The pair comes from the caller: the store behind it
 * belongs to the application of the editor, and the callback of the queue runs long after the moment
 * that application can be told from another one on the page.
 */
export type PublishMenuHold = {
	hold: () => void,
	release: () => void,
};

/**
 * Every step remembers itself. The mark of the step about the publication is the key the whole onboarding
 * used to be marked by: whoever has seen the one-step tour does not see it again, and the step about the
 * running pilot still awaits its turn.
 */
const STEPS = [
	{
		dismissedKey: 'bizprocdesigner_pilot_publication_onboarding_dismissed',
		selector: PILOT_OPTION_SELECTOR,
		needsPublishMenu: true,
		title: 'BIZPROCDESIGNER_EDITOR_PILOT_ONBOARDING_PUBLISH_TITLE',
		text: 'BIZPROCDESIGNER_EDITOR_PILOT_ONBOARDING_PUBLISH_TEXT',
	},
	{
		dismissedKey: 'bizprocdesigner_pilot_publication_badge_onboarding_dismissed',
		selector: PILOT_BADGE_SELECTOR,
		needsPublishMenu: false,
		title: 'BIZPROCDESIGNER_EDITOR_PILOT_ONBOARDING_BADGE_TITLE',
		text: 'BIZPROCDESIGNER_EDITOR_PILOT_ONBOARDING_BADGE_TEXT',
	},
];

// Long enough for any transition of the editor: an animation that never ends must not hold the tour back.
const TARGET_SETTLE_TIMEOUT = 1000;

function findVisibleNode(selector: string): ?HTMLElement
{
	const node: ?HTMLElement = document.querySelector(selector);

	return node?.offsetWidth > 0 ? node : null;
}

function nextFrame(): Promise<void>
{
	return new Promise((resolve: () => void) => {
		requestAnimationFrame(() => resolve());
	});
}

/**
 * The publish menu slides in: the item the tour points at is in the DOM a tick after the menu is asked
 * for, and travels a whole menu width to its place over the next 0.3s. Read any earlier, the place of
 * the item is the one the menu slides from, and the highlight and the popup land beside it. Everything
 * that moves the item - the transition of the menu around it or one of its own - is awaited here.
 */
async function waitUntilTargetSettles(target: ?HTMLElement): Promise<void>
{
	if (!target)
	{
		return;
	}

	// The node is inserted in the state the transition starts from, and Vue leaves that state on the
	// next frame: awaited before it, there is no transition to await yet.
	await nextFrame();
	await nextFrame();

	const moving = (document.getAnimations?.() ?? [])
		.filter((animation: Animation) => animation.effect?.target?.contains(target))
		.map((animation: Animation) => animation.finished.catch(() => {}))
	;

	if (moving.length === 0)
	{
		return;
	}

	await Promise.race([
		Promise.all(moving),
		new Promise((resolve: () => void) => {
			setTimeout(resolve, TARGET_SETTLE_TIMEOUT);
		}),
	]);
}

/**
 * Tells the publisher about the pilot publication: where a scheme is published for chosen employees and
 * where the running pilot is seen afterwards. The first step points at the item of the publish menu, so
 * the menu is opened for it and held open while that step is on the screen; the step about the running
 * pilot points at the toolbar, so on it the menu goes away. The mark of the pilot appears in the toolbar
 * only after the first pilot publication, so the step about it waits for the opening of the editor where
 * it is there to point at.
 */
export class PilotPublicationOnboarding
{
	#publishMenu: PublishMenuHold;
	// Every hold taken here is given back exactly once, whichever way the tour moves or ends: a release
	// the tour never took would close the menu of the publication that is running behind it.
	#isMenuHeld: boolean = false;
	// The guide does not cancel a step it has already scheduled: a "Back" click shows its step a moment
	// later, and the tour may be closed within that moment. A step shown after the end must change
	// nothing - a hold taken then would never be given back.
	#isFinished: boolean = false;

	// The store is read here, in the call of the component that starts the tour, and not in the
	// callback of the queue below: a store resolved there lands in whatever Pinia is active by then.
	static show(publishMenu: PublishMenuHold = usePublishMenuStore()): void
	{
		new PilotPublicationOnboarding(publishMenu).showOnboarding();
	}

	constructor(publishMenu: PublishMenuHold)
	{
		this.#publishMenu = publishMenu;
	}

	showOnboarding(): void
	{
		const pending = STEPS.filter((step: Object) => !isOnboardingDismissed(step.dismissedKey));
		if (pending.length === 0)
		{
			return;
		}

		// The queue is shared with the other onboardings of the editor, so the steps are collected at
		// the moment the turn comes: by then the toolbar may look different.
		BannerDispatcher.normal.toQueue(async (onDone) => {
			let closed = false;
			const finish = () => {
				if (closed)
				{
					return;
				}

				closed = true;
				this.#isFinished = true;
				this.#releasePublishMenu();
				onDone();
			};

			// The menu is taken while the steps are collected, and both the collecting and the start of
			// the tour can fail. Only a tour that really started gives the menu back by itself, so every
			// other outcome ends here: otherwise the editor keeps a menu nothing can close and the shared
			// queue of the banners never moves on.
			let isTourStarted = false;

			try
			{
				const steps = await this.#buildSteps(pending);
				if (steps.length === 0)
				{
					return;
				}

				new Guide({
					id: BANNER_ID,
					// A single step has nothing to count and nowhere to go back to.
					simpleMode: steps.length === 1,
					steps,
					events: { onFinish: finish },
				}).start();

				isTourStarted = true;
			}
			finally
			{
				if (!isTourStarted)
				{
					finish();
				}
			}
		}, { id: BANNER_ID });
	}

	async #buildSteps(pending: Array<Object>): Promise<Array<Object>>
	{
		const menuStep = pending.find((step: Object) => step.needsPublishMenu);
		if (menuStep)
		{
			this.#holdPublishMenu();
			await nextTick();
			await waitUntilTargetSettles(findVisibleNode(menuStep.selector));
		}

		const shown = pending
			.map((step: Object) => ({ ...step, target: findVisibleNode(step.selector) }))
			.filter((step: Object) => step.target !== null)
		;

		// The menu was opened for a step that has nothing to point at - a publication to an audience is
		// not offered here - so it goes back to how the publisher left it.
		if (!shown.some((step: Object) => step.needsPublishMenu))
		{
			this.#releasePublishMenu();
		}

		// The selector goes into the step instead of the found node: the tour resolves it again on every
		// show, so a step returned to after the menu was reopened points at the live item, not at the
		// node the closed menu took away.
		return shown.map((step: Object) => ({
			target: step.selector,
			title: Loc.getMessage(step.title),
			text: Loc.getMessage(step.text),
			position: 'bottom',
			events: { onShow: (event: BaseEvent) => this.#handleStepShown(step, event) },
		}));
	}

	#handleStepShown(step: Object, event: BaseEvent): void
	{
		if (this.#isFinished)
		{
			return;
		}

		// A step counts as told the moment it is on the screen: the tour left halfway keeps the steps
		// that were never reached for the next opening of the editor.
		markOnboardingDismissed(step.dismissedKey);
		this.#syncPublishMenuWithStep(step);
		this.#aimPointerAtTarget(event);
		this.#realignWhenTargetSettles(step, event);
	}

	// The menu belongs to the step that is on the screen: the step about the publication needs it open -
	// again, when the tour is walked back to it - and on any other step an open menu would hide what the
	// tour points at.
	#syncPublishMenuWithStep(step: Object): void
	{
		if (step.needsPublishMenu)
		{
			this.#holdPublishMenu();

			return;
		}

		this.#releasePublishMenu();
	}

	// The guide always creates the pointer of its popup at the default offset, and the popup keeps
	// returning it there on every reposition. The offset the popup keeps is the one the pointer is
	// created with, so it is recreated for the target of every shown step - and lands at its middle.
	#aimPointerAtTarget(event: BaseEvent): void
	{
		const { step, guide } = event.getData();
		const popup = guide.popup;
		const target: ?HTMLElement = step.getTarget();
		if (!popup || !target)
		{
			return;
		}

		popup.setAngle(false);
		popup.setAngle({ position: 'top', offset: target.offsetWidth / 2 });
	}

	// The step points into the publish menu, and the guide places the popup while that menu is still on
	// its way: the item is drawn a tick later, and slides to its place for a third of a second more.
	// Once the menu has stopped, the highlight, the pointer and the popup come back to the item.
	async #realignWhenTargetSettles(step: Object, event: BaseEvent): Promise<void>
	{
		const { step: tourStep, guide } = event.getData();
		if (!step.needsPublishMenu)
		{
			return;
		}

		await nextTick();
		await waitUntilTargetSettles(findVisibleNode(step.selector));

		if (this.#isFinished || !guide.popup || guide.getCurrentStep() !== tourStep)
		{
			return;
		}

		const target: ?HTMLElement = tourStep.getTarget();
		if (!target)
		{
			return;
		}

		guide.setCoords(target);
		this.#aimPointerAtTarget(event);
		guide.setPopupPosition();
	}

	#holdPublishMenu(): void
	{
		if (this.#isMenuHeld)
		{
			return;
		}

		this.#isMenuHeld = true;
		this.#publishMenu.hold();
	}

	#releasePublishMenu(): void
	{
		if (!this.#isMenuHeld)
		{
			return;
		}

		this.#isMenuHeld = false;
		this.#publishMenu.release();
	}
}
