import { focusProgrammatically } from '../utils/focus';
import { announce } from './announce';
import { findRegionByElement, getAdjacentRegion, getOrderedRegions } from './region-registry';

/**
 * Moves the focus to the region next to the one it stands in and says the name of the region it
 * entered. Returns false when there is nowhere to go: with a single live region the move would end
 * where it started, and a key without an effect is better left to the page.
 */
export function moveToAdjacentRegion(step: 1 | -1): boolean
{
	if (getOrderedRegions().length < 2)
	{
		return false;
	}

	const current = findRegionByElement(document.activeElement);
	const target = getAdjacentRegion(current === null ? null : current.id, step);

	if (target === null)
	{
		return false;
	}

	focusProgrammatically(target.element);
	announce(target.label);

	return true;
}
