import { Type } from 'main.core';
import { EventEmitter } from 'main.core.events';

const RENDER_FINISHED_EVENT = 'BX.Bizproc.FieldType.onDesignerRenderControlFinished';

export type FieldControlRequest = {
	documentType: string[],
	property: { [string]: mixed },
	fieldName: string,
	value: mixed,
};

export type UseFieldControl = {
	renderFieldControl: (request: FieldControlRequest) => HTMLElement,
	initFieldSelectors: (root: HTMLElement | null) => void,
	subscribeRenderFinished: (handler: () => void) => () => void,
};

function renderFieldControl({ documentType, property, fieldName, value }: FieldControlRequest): HTMLElement
{
	return BX.Bizproc.FieldType.renderControl(documentType, property, fieldName, value, 'designer');
}

function initFieldSelectors(root: HTMLElement | null): void
{
	if (root && !Type.isUndefined(BX.Bizproc?.Selector))
	{
		BX.Bizproc.Selector.initSelectors(root);
	}
}

function subscribeRenderFinished(handler: () => void): () => void
{
	EventEmitter.subscribe(RENDER_FINISHED_EVENT, handler);

	return (): void => {
		EventEmitter.unsubscribe(RENDER_FINISHED_EVENT, handler);
	};
}

/**
 * A single typed control of bizproc; a set of fields goes through `startSettingsControlsRender()`. In the
 * designer mode `renderControl` returns an empty box and fills it over ajax, so everything that reads the
 * markup of the control waits for the event of the render.
 */
export function useFieldControl(): UseFieldControl
{
	return {
		renderFieldControl,
		initFieldSelectors,
		subscribeRenderFinished,
	};
}
