import { formatComboCaption } from 'ui.block-diagram';

import './style.css';

/**
 * A combination as one key block. The caption already spells the whole combo ('Ctrl+C', '⌘C'), and
 * the context menu of a block shows it in a single block too - splitting it into a key per token
 * here would make the same combo look different in two places of the same editor.
 */
// @vue/component
export const HotkeyKey = {
	name: 'HotkeyKey',
	props: {
		combo: {
			type: String,
			required: true,
		},
	},
	computed: {
		caption(): string
		{
			return formatComboCaption(this.combo);
		},
	},
	template: `
		<kbd class="bizprocdesigner-hotkey-key">{{ caption }}</kbd>
	`,
};
