import { ajax } from 'main.core';

import { ApiError } from '../../../shared/api';

/**
 * Where the personal overrides of a user live. Contract for the backend SDD: the repository over
 * `\CUserOptions` reads and writes exactly this category and name, and puts the value it read into
 * the initial data of the editor as `initHotkeys`. Nothing but this pair names the storage key on
 * either side.
 */
export const HOTKEYS_OPTION_CATEGORY = 'bizprocdesigner.hotkeys';
export const HOTKEYS_OPTION_NAME = 'bindings';

// Version of the stored value (DTO-01). A value that names another one is dropped whole on load.
export const HOTKEYS_SETTINGS_VERSION = 1;

// The generic action of `main`: it writes personal options of the current user only, so the editor
// needs no controller of its own. Called directly rather than through BX.userOptions, which batches
// writes behind a delay and would lose the save of a tab that is being closed.
const SAVE_OPTIONS_ACTION = 'main.userOption.saveOptions';

export const hotkeysApi = {
	/**
	 * Writes the whole set of overrides as one value. The value travels as an object, and its two
	 * keys are replaced wholesale by `CUserOptions::SetOptionsFromArray()`: an override the user
	 * took back disappears with the rest of `bindings`, instead of surviving a per-key merge.
	 *
	 * @param {Object<string, string | null>} bindings difference from the catalog defaults
	 * @returns {Promise<?Object>}
	 */
	async saveOverrides(bindings)
	{
		let response = null;
		try
		{
			response = await ajax.runAction(SAVE_OPTIONS_ACTION, {
				json: {
					newValues: [
						{
							c: HOTKEYS_OPTION_CATEGORY,
							n: HOTKEYS_OPTION_NAME,
							v: {
								version: HOTKEYS_SETTINGS_VERSION,
								bindings,
							},
						},
					],
				},
			});
		}
		catch (error)
		{
			throw new ApiError(error);
		}

		if (response?.status === 'success')
		{
			return response.data;
		}

		throw new ApiError(response);
	},
};
