import { Browser, Type } from 'main.core';
import { CANVAS_ACTION_ID, getCanvasActionDefaults, normalizeCombo } from 'ui.block-diagram';

export const EDITOR_ACTION_GROUP_ID = Object.freeze({
	NAVIGATION: 'navigation',
	CANVAS: 'canvas',
	HISTORY: 'history',
	PANELS: 'panels',
	TEMPLATE: 'template',
	SEARCH: 'search',
});

/**
 * Render order of the groups and their names in one place. A group missing here is not rendered at
 * all, so this list is what decides whether an action of the catalog reaches the panel.
 *
 * @type {ReadonlyArray<EditorActionGroup>}
 */
export const EDITOR_ACTION_GROUPS = Object.freeze([
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.NAVIGATION,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_NAVIGATION',
	}),
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.CANVAS,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_CANVAS',
	}),
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.HISTORY,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_HISTORY',
	}),
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.PANELS,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_PANELS',
	}),
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.TEMPLATE,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_TEMPLATE',
	}),
	Object.freeze({
		id: EDITOR_ACTION_GROUP_ID.SEARCH,
		labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_GROUP_SEARCH',
	}),
]);

/**
 * Ids of the actions the editor owns. They travel into the saved settings of a user, so an id is
 * renamed only at the price of losing what people bound to it. The actions the canvas owns itself
 * (undo/redo/copy/paste, search/map toggle, zoom in/out, fit to view) keep the ids of
 * `ui.block-diagram` - the editor adds a name and a group, never a second id.
 */
export const EDITOR_ACTION_ID = Object.freeze({
	NEXT_REGION: 'bizproc.editor.nextRegion',
	PREV_REGION: 'bizproc.editor.prevRegion',
	DELETE_BLOCK: 'bizproc.editor.deleteBlock',
	AUTO_LAYOUT: 'bizproc.editor.autoLayout',
	PAN_CANVAS: 'bizproc.editor.panCanvas',
	TOGGLE_CATALOG: 'bizproc.editor.toggleCatalog',
	NAVIGATE_CATALOG: 'bizproc.editor.navigateCatalog',
	CLOSE_NODE_SETTINGS: 'bizproc.editor.closeNodeSettings',
	TOGGLE_NODE_DATA: 'bizproc.editor.toggleNodeData',
	TOGGLE_NOTES_MODE: 'bizproc.editor.toggleNotesMode',
	TOGGLE_DEBUG_BAR: 'bizproc.editor.toggleDebugBar',
	PUBLISH_TEMPLATE: 'bizproc.editor.publishTemplate',
	OPEN_TEMPLATE_SETTINGS: 'bizproc.editor.openTemplateSettings',
	OPEN_VERSION_HISTORY: 'bizproc.editor.openVersionHistory',
	OPEN_STORAGE_LIST: 'bizproc.editor.openStorageList',
	BACK_TO_TEMPLATE_LIST: 'bizproc.editor.backToTemplateList',
});

/**
 * Confirming input on Enter is an accessibility contract of the elements that already own it, not a
 * row the catalog could declare any more: no id of the editor claims the combo, so this is the one
 * name a caller that means Enter specifically - the capture panel, reporting which reserved combo it
 * just refused - can read instead of indexing into `RESERVED_EDITOR_COMBOS` and hoping it is still
 * alone in meaning Enter.
 */
export const RESERVED_CONFIRM_COMBO = 'enter';

/**
 * Combos the editor never hands out to a bound action, whatever the source of the binding is - the
 * settings panel, a stored personal override, or a value written past it. Cancelling on Escape is the
 * same kind of contract as confirming on Enter, and neither has a row the catalog could declare any
 * more, so nothing but this set stops one of them from reaching `ActionRegistry` through a saved
 * override.
 *
 * @type {ReadonlyArray<string>}
 */
export const RESERVED_EDITOR_COMBOS = Object.freeze([RESERVED_CONFIRM_COMBO, 'escape']);

/**
 * @typedef {Object} ActionRecord
 * @property {string} id
 * @property {string} group
 * @property {string} labelKey
 * @property {Array<string> | function(boolean): Array<string>} comboKeys keys of the combo the
 *   action ships with; empty means none. A function is asked about the platform, for a default that
 *   follows a convention of the system rather than the `mod` of the layer
 * @property {boolean} isReassignable
 */

/**
 * Fills the defaults, so a record below states only what makes it different.
 *
 * @param {Partial<ActionRecord>} entry at least id, group and labelKey
 * @returns {ActionRecord}
 */
function record(entry)
{
	return Object.freeze({
		comboKeys: [],
		isReassignable: true,
		...entry,
	});
}

const GROUP = EDITOR_ACTION_GROUP_ID;
const ACTION = EDITOR_ACTION_ID;

/**
 * Every action of the editor, in the order its groups are rendered.
 *
 * Two classes of records live here side by side, and the split is the one of ADR § 3. A global
 * action of the canvas or of a panel is reassignable; a held key that drives the pointer is shown
 * as reference only, because it is part of the accessibility contract of the component that owns it.
 *
 * An action without a combo is a normal record, not a gap: the editor has far more actions than
 * combos, and the panel is where a user gives one a combo of their own. The actions the canvas
 * owns itself name no keys here at all - their defaults are read from `ui.block-diagram`, so a
 * change there arrives on its own instead of drifting apart from a copy.
 *
 * @type {ReadonlyArray<ActionRecord>}
 */
const ACTION_RECORDS = Object.freeze([
	// The walk between the regions ships with one and the same pair everywhere, because the F row
	// reaches the page on no platform: Chrome walks the panes of its own interface by F6 and Firefox
	// walks the frames of a page, while macOS takes Ctrl+F1...F8 for its own focus walk and answers
	// the top row as media keys until a person changes a system setting. Measured on a live macOS
	// keyboard, where the modifier is called Option: Alt+Shift+N and Alt+Shift+P do reach the page.
	record({ id: ACTION.NEXT_REGION, group: GROUP.NAVIGATION, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_NEXT_REGION', comboKeys: ['Alt', 'Shift', 'n'] }),
	record({ id: ACTION.PREV_REGION, group: GROUP.NAVIGATION, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_PREV_REGION', comboKeys: ['Alt', 'Shift', 'p'] }),

	// Backspace deletes the selection too, but it is a second spelling of the same gesture rather
	// than a second combo: an action holds one, and that one is Delete.
	record({ id: ACTION.DELETE_BLOCK, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_DELETE_BLOCK', comboKeys: ['Delete'] }),
	record({ id: ACTION.AUTO_LAYOUT, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_AUTO_LAYOUT', comboKeys: ['Mod', 'Shift', 'a'] }),
	record({ id: CANVAS_ACTION_ID.ZOOM_IN, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_ZOOM_IN' }),
	record({ id: CANVAS_ACTION_ID.ZOOM_OUT, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_ZOOM_OUT' }),
	record({ id: CANVAS_ACTION_ID.FIT_TO_VIEW, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_FIT_TO_VIEW' }),
	record({ id: CANVAS_ACTION_ID.TOGGLE_MAP, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_CANVAS_MAP' }),
	// A held key that drives the pointer, not a press that runs a handler.
	record({ id: ACTION.PAN_CANVAS, group: GROUP.CANVAS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_PAN_CANVAS', comboKeys: ['Space'], isReassignable: false }),

	record({ id: CANVAS_ACTION_ID.UNDO, group: GROUP.HISTORY, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_UNDO' }),
	record({ id: CANVAS_ACTION_ID.REDO, group: GROUP.HISTORY, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_REDO' }),
	record({ id: CANVAS_ACTION_ID.COPY, group: GROUP.HISTORY, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_COPY' }),
	record({ id: CANVAS_ACTION_ID.PASTE, group: GROUP.HISTORY, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_PASTE' }),

	record({ id: ACTION.TOGGLE_CATALOG, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_CATALOG', comboKeys: ['Mod', 'b'] }),
	// Reference only, like the panning of the canvas: arrows inside a composite widget are part of
	// its accessibility contract, not a combo anyone may move elsewhere. Enter gets no record here at
	// all - RESERVED_CONFIRM_COMBO already keeps it out of every action's reach.
	record({ id: ACTION.NAVIGATE_CATALOG, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_NAVIGATE_CATALOG', isReassignable: false }),
	record({ id: ACTION.CLOSE_NODE_SETTINGS, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_CLOSE_NODE_SETTINGS' }),
	record({ id: ACTION.TOGGLE_NODE_DATA, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_NODE_DATA' }),
	record({ id: ACTION.TOGGLE_NOTES_MODE, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_NOTES_MODE', comboKeys: ['Mod', 'Shift', 'e'] }),
	record({ id: ACTION.TOGGLE_DEBUG_BAR, group: GROUP.PANELS, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_DEBUG_BAR', comboKeys: ['Mod', 'Shift', 'd'] }),

	record({ id: ACTION.PUBLISH_TEMPLATE, group: GROUP.TEMPLATE, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_PUBLISH_TEMPLATE' }),
	record({ id: ACTION.OPEN_TEMPLATE_SETTINGS, group: GROUP.TEMPLATE, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_OPEN_TEMPLATE_SETTINGS' }),
	record({ id: ACTION.OPEN_VERSION_HISTORY, group: GROUP.TEMPLATE, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_OPEN_VERSION_HISTORY' }),
	record({ id: ACTION.OPEN_STORAGE_LIST, group: GROUP.TEMPLATE, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_OPEN_STORAGE_LIST' }),
	record({ id: ACTION.BACK_TO_TEMPLATE_LIST, group: GROUP.TEMPLATE, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_BACK_TO_TEMPLATE_LIST' }),

	record({ id: CANVAS_ACTION_ID.TOGGLE_SEARCH, group: GROUP.SEARCH, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_TOGGLE_SEARCH' }),
	record({ id: CANVAS_ACTION_ID.NEXT_SEARCH_RESULT, group: GROUP.SEARCH, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_NEXT_SEARCH_RESULT' }),
	record({ id: CANVAS_ACTION_ID.PREV_SEARCH_RESULT, group: GROUP.SEARCH, labelKey: 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_PREV_SEARCH_RESULT' }),
]);

/**
 * @param {ActionRecord} entry
 * @param {Map<string, string | null>} canvasDefaults
 * @param {boolean} isMac
 * @returns {string | null}
 */
function resolveDefaultCombo(entry, canvasDefaults, isMac)
{
	if (canvasDefaults.has(entry.id))
	{
		return canvasDefaults.get(entry.id);
	}

	const comboKeys = Type.isFunction(entry.comboKeys) ? entry.comboKeys(isMac) : entry.comboKeys;

	return comboKeys.length > 0 ? normalizeCombo(comboKeys, isMac) : null;
}

/**
 * The catalog with its combos resolved for a platform: the same `mod` is Ctrl on one and Cmd on
 * another, so the canonical form of a combo cannot be written down once for both.
 *
 * @param {boolean} [isMac]
 * @returns {ReadonlyArray<EditorAction>}
 */
export function getEditorActionCatalog(isMac = Browser.isMac())
{
	const canvasDefaults = getCanvasActionDefaults(isMac);

	return Object.freeze(ACTION_RECORDS.map((entry) => Object.freeze({
		id: entry.id,
		group: entry.group,
		labelKey: entry.labelKey,
		defaultCombo: resolveDefaultCombo(entry, canvasDefaults, isMac),
		isReassignable: entry.isReassignable,
	})));
}

/**
 * Canonical combo per action id, null for a reassignable action that ships without one. The null is
 * what makes such an action known to the registry, and being known is the whole condition for an
 * override to reach it - most of the catalog gets its first combo exactly this way.
 *
 * A non-reassignable action is here only while it holds a combo: its keys are taken all the same,
 * and the validator has to answer that they are before the panel offers one of them to another
 * action. Without a combo it has nothing to say to the registry - the panel reads it from the
 * catalog as a reference row and never resolves it through bindings.
 *
 * @param {boolean} [isMac]
 * @returns {Map<string, string | null>}
 */
export function getEditorActionDefaults(isMac = Browser.isMac())
{
	const defaults = new Map();

	getEditorActionCatalog(isMac).forEach((editorAction) => {
		if (editorAction.defaultCombo !== null || editorAction.isReassignable)
		{
			defaults.set(editorAction.id, editorAction.defaultCombo);
		}
	});

	return defaults;
}
