import { FocusMonitor } from 'ui.a11y';
import { useBlockDiagram } from 'ui.block-diagram';
import { ref, toValue, useTemplateRef, watch } from 'ui.vue3';
import { storeToRefs } from 'ui.vue3.pinia';

import {
	CatalogLayout,
	useCatalogStore,
} from '../../../../entities/catalog';

type HoverCatalogLayoutSetup = {
	isExpandedCatalog: boolean,
	isSearchResultsExpanded: boolean,
	isShowSearchResults: boolean,
	onCatalogTransitionEnd: (event: TransitionEvent) => void,
	onMouseOver: () => void,
	onMouseLeave: () => void,
	onFocusOut: (event: FocusEvent) => void,
};

const CATALOG_WIDTH_PROPERTY = 'width';

// @vue/component
export const HoverCatalogLayout = {
	name: 'HoverCatalogLayout',
	components: {
		CatalogLayout,
	},
	setup(): HoverCatalogLayoutSetup
	{
		const catalogStore = useCatalogStore();
		const { isExpandedCatalog, isFixedCatalog, isShowSearchResults } = storeToRefs(catalogStore);
		const { isSelectionActive } = useBlockDiagram();
		const isSearchResultsExpanded = ref(false);
		const layout = useTemplateRef('layout');

		// Not display data: the pointer only decides which of the two handlers folds the panel.
		let isPointerInside = false;

		function syncSearchResultsExpanded(values: Array<boolean>, oldValues: Array<boolean> = []): void
		{
			const [expanded, fixed, showSearchResults] = values;
			const [wasExpanded] = oldValues;

			if (!expanded || !showSearchResults)
			{
				isSearchResultsExpanded.value = false;

				return;
			}

			isSearchResultsExpanded.value = fixed || wasExpanded === true || wasExpanded === undefined;
		}

		watch(
			[isExpandedCatalog, isFixedCatalog, isShowSearchResults],
			syncSearchResultsExpanded,
			{ immediate: true },
		);

		function panelElement(): ?HTMLElement
		{
			return toValue(layout)?.$el ?? null;
		}

		function contains(node: ?EventTarget): boolean
		{
			return node instanceof Node && panelElement()?.contains(node) === true;
		}

		/**
		 * A panel unfolded by the keyboard has to hold while it is being worked in. Only a keyboard
		 * focus holds it: a card and the header of a group are focusable programmatically, so a click
		 * leaves the focus standing in the panel with nothing but the pointer behind it, and a panel
		 * held by that focus would never fold again.
		 */
		function isHeldByKeyboard(): boolean
		{
			return contains(document.activeElement)
				&& FocusMonitor.Instance.getLastInputModality() !== 'pointer'
			;
		}

		function onMouseOver(): void
		{
			isPointerInside = true;
			if (toValue(isSelectionActive))
			{
				return;
			}
			catalogStore.expandCatalog();
		}

		function onMouseLeave(): void
		{
			isPointerInside = false;
			if (isHeldByKeyboard())
			{
				return;
			}

			catalogStore.collapseCatalog();
		}

		// The other way round: the keyboard leaves a panel the pointer left long ago, and folding it is
		// what the departure of the pointer was refused for. `relatedTarget` names where the focus goes
		// next - reading `activeElement` would miss a focus that fell to the body.
		function onFocusOut(event: FocusEvent): void
		{
			if (isPointerInside || contains(event.relatedTarget))
			{
				return;
			}

			catalogStore.collapseCatalog();
		}

		function onCatalogTransitionEnd(event: TransitionEvent): void
		{
			if (event.propertyName !== CATALOG_WIDTH_PROPERTY)
			{
				return;
			}

			if (toValue(isExpandedCatalog) && toValue(isShowSearchResults))
			{
				isSearchResultsExpanded.value = true;
			}
		}

		return {
			isExpandedCatalog,
			isSearchResultsExpanded,
			isShowSearchResults,
			onCatalogTransitionEnd,
			onMouseOver,
			onMouseLeave,
			onFocusOut,
		};
	},
	template: `
		<CatalogLayout
			ref="layout"
			:hasSearchResults="isShowSearchResults"
			:expanded="isExpandedCatalog"
			:searchResultsExpanded="isSearchResultsExpanded"
			@catalog-transition-end="onCatalogTransitionEnd"
			@mouseover="onMouseOver"
			@mouseleave="onMouseLeave"
			@focusout="onFocusOut"
		>
			<template #header>
				<slot name="header"/>
			</template>

			<template #search>
				<slot name="search"/>
			</template>

			<template #content>
				<slot name="content"/>
			</template>

			<template #search-results>
				<slot name="search-results"/>
			</template>
		</CatalogLayout>
	`,
};
