import { Event } from 'main.core';
import { FocusKeys, FocusNavigator, FocusZone } from 'ui.a11y';
import { nextTick, onMounted, onUnmounted, toValue, watch } from 'ui.vue3';

import { useCatalogStore } from '../../../entities/catalog';
import { focusProgrammatically } from '../../../shared/utils';

/**
 * The three views of the panel. Only one of them is on screen at a time - an open group covers the
 * list of groups with an opaque panel of its own - so the roving focus is rebuilt for each, and the
 * markup of every view names itself by `data-catalog-level`.
 */
export const CATALOG_LEVEL = {
	GROUPS: 'groups',
	GROUP_ITEMS: 'group-items',
	SEARCH_RESULTS: 'search-results',
};

// Keys the collapsed panel unfolds by. Home and End are in: they are bound to the zone as well, and
// a press the panel answers with nothing would leave the person unable to reach it at all.
const NAVIGATION_KEYS = new Set(['ArrowUp', 'ArrowDown', 'Home', 'End']);

// A level drawn as an opaque panel over the one below it - the content of an open group. Its markup
// stands inside the row of that group, so the container of the level below holds it.
const LEVEL_OVERLAY_SELECTOR = '[data-catalog-level-overlay]';

/**
 * Whether the element belongs to the level the zone is built for, and not to a panel drawn over it.
 * An open group leaves by a transition of 0.3s and stands in the markup until it is over, while the
 * list of groups under it is the visible level again from the first frame - and a vnode Vue has
 * unmounted is patched no more, so the panel on its way out cannot be told to step aside. Without
 * this, an arrow pressed within those 0.3s would take the focus into the group just left and onto
 * `<body>` once it is removed.
 */
function isOfOwnLevel(container: HTMLElement, element: HTMLElement): boolean
{
	const overlay = element.closest(LEVEL_OVERLAY_SELECTOR);

	return overlay === null || !container.contains(overlay);
}

/**
 * The container of the level on screen. `GROUP_ITEMS` is the one level drawn in an overlay, and for
 * the 0.3s a group leaves by the panel holds two of them: a query over the panel would answer with
 * the container of the group just left whenever the newly open one stands below it in the list, and
 * the focus would go into a panel about to be removed. So that level is looked up in the overlay of
 * the group that is open now - `openGroupId`, the group `level` was computed from.
 */
export function getCatalogLevelContainer(
	panel: ?HTMLElement,
	level: string,
	openGroupId: ?string = null,
): ?HTMLElement
{
	if (level !== CATALOG_LEVEL.GROUP_ITEMS)
	{
		return panel?.querySelector(`[data-catalog-level="${level}"]`) ?? null;
	}

	const overlay = openGroupId === null
		? null
		: panel?.querySelector(`[data-catalog-level-overlay="${CSS.escape(openGroupId)}"]`)
	;

	return overlay?.querySelector(`[data-catalog-level="${level}"]`) ?? null;
}

// The group `level` is computed from: the level of its content is looked up in the overlay of that
// group alone, and the zone of the level is rebuilt when the group changes.
function openGroupIdOf(catalogStore: { currentGroup: ?{ id: string } }): ?string
{
	return catalogStore.currentGroup?.id ?? null;
}

/**
 * A fresh zone defaults its "current" element to the first of the level, not to the real DOM focus
 * `closeOpenedGroup()` just set - so only answer during `rebuildZone()`'s own `zone.activate()`
 * (`activating`); a focus later walking in from outside is already handled correctly by the zone
 * itself, and answering there too would just make it re-focus an already-focused element.
 */
function resolveFocusInStrategy(
	container: HTMLElement,
	activating: { current: boolean },
): (previousFocusedElement: Element) => HTMLElement | null
{
	return (): HTMLElement | null => {
		if (!activating.current)
		{
			return null;
		}

		const active = FocusNavigator.getActiveElement();

		if (active !== null && container.contains(active) && isOfOwnLevel(container, active))
		{
			return active;
		}

		return FocusNavigator.getFirst(container, { tabbableOnly: false, preventScroll: true });
	};
}

export function focusFirstOfCatalogLevel(
	panel: ?HTMLElement,
	level: string,
	openGroupId: ?string = null,
): boolean
{
	const container = getCatalogLevelContainer(panel, level, openGroupId);
	if (container === null)
	{
		return false;
	}

	// `tabbableOnly: false`, as in the zone itself: every element of a level carries `tabindex="-1"`
	// and the one tabindex the roving focus hands out is the zone's own, so a level whose zone is not
	// built yet - the panel has just unfolded - would otherwise answer with nothing at all.
	return focusProgrammatically(
		FocusNavigator.getFirst(container, { tabbableOnly: false, preventScroll: true }),
	);
}

/**
 * Roving focus over the visible level of the catalog (WAI-ARIA composite). The zone owns the
 * vertical arrows, Home and End - it keeps the `tabindex` of the level itself, remembers where the
 * focus stood and calls `preventDefault()`, so the page under the panel does not scroll. Entering a
 * group and leaving it are not focus moves but a redraw of the panel, so those keys stay with the
 * widget.
 */
export function useCatalogKeyboardNavigation(options): void
{
	const { panelRef, isExpanded, level } = options;
	const catalogStore = useCatalogStore();

	let zone = null;

	function getPanel(): ?HTMLElement
	{
		return toValue(panelRef)?.$el ?? null;
	}

	function destroyZone(): void
	{
		zone?.deactivate();
		zone = null;
	}

	// A collapsed panel shows icons without their captions, so it gets no zone: the first press
	// unfolds it instead of moving a focus nobody can read.
	function rebuildZone(): void
	{
		destroyZone();

		if (!toValue(isExpanded))
		{
			return;
		}

		const container = getCatalogLevelContainer(getPanel(), toValue(level), openGroupIdOf(catalogStore));
		if (container === null)
		{
			return;
		}

		const activating = { current: true };
		zone = new FocusZone(container, {
			bindKeys: FocusKeys.ArrowVertical | FocusKeys.HomeAndEnd,
			focusOutBehavior: 'stop',
			preventScroll: true,
			focusableElementFilter: (element: HTMLElement): boolean => isOfOwnLevel(container, element),
			focusInStrategy: resolveFocusInStrategy(container, activating),
		});
		zone.activate();
		activating.current = false;
	}

	// The same unconditional unfolding Ctrl/Cmd+B does: a catalog that refused to open for the
	// keyboard would be unreachable by it altogether.
	function expandForKeyboard(): boolean
	{
		if (toValue(isExpanded))
		{
			return false;
		}

		catalogStore.setExpandedCatalog(true);
		void nextTick(() => {
			rebuildZone();
			focusFirstOfCatalogLevel(getPanel(), toValue(level), openGroupIdOf(catalogStore));
		});

		return true;
	}

	// The burger button is the collapsed panel's own affordance and works without expanding it: a
	// focus landing there is not a keyboard reaching for content it cannot see, whether a person
	// tabbed to it or the collapse itself just put the focus there (`followCatalogWithFocus()`) -
	// expanding on this landing would undo the very collapse that caused it.
	function onPanelFocusIn(event: FocusEvent): void
	{
		if (event.target instanceof HTMLElement && event.target.closest('.editor-chart-burger-btn') !== null)
		{
			return;
		}

		expandForKeyboard();
	}

	function onPanelKeyDown(event: KeyboardEvent): void
	{
		if (!NAVIGATION_KEYS.has(event.key))
		{
			return;
		}

		if (expandForKeyboard())
		{
			event.preventDefault();
		}
	}

	function bindPanel(): void
	{
		const panel = getPanel();
		if (panel === null)
		{
			return;
		}

		Event.bind(panel, 'focusin', onPanelFocusIn);
		Event.bind(panel, 'keydown', onPanelKeyDown);
	}

	function unbindPanel(): void
	{
		const panel = getPanel();
		if (panel === null)
		{
			return;
		}

		Event.unbind(panel, 'focusin', onPanelFocusIn);
		Event.unbind(panel, 'keydown', onPanelKeyDown);
	}

	// The zone counts the elements of the level by the DOM, and the level changes by a redraw: the
	// open group and the list it covers both stand in the markup for a frame of the transition. The
	// open group is watched along with the level, since a zone bound to the container of another
	// group is as stale as one bound to a level that is gone.
	watch([() => toValue(level), () => toValue(isExpanded), () => openGroupIdOf(catalogStore)], () => {
		void nextTick(rebuildZone);
	});

	onMounted(() => {
		bindPanel();
		void nextTick(rebuildZone);
	});

	onUnmounted(() => {
		unbindPanel();
		destroyZone();
	});
}
