import { Button as UiButton, AirButtonStyle } from 'ui.vue3.components.button';
import { Outline } from 'ui.icon-set.api.core';
import { useKeyboardShortcuts } from 'ui.block-diagram';

import { TEMPLATE_LIST_URL } from '../../../../shared/utils/url';
import { EDITOR_ACTION_ID } from '../../../hotkeys';

// @vue/component
export const LogoBackBtn = {
	name: 'LogoBackBtn',
	components: {
		UiButton,
	},
	props: {
		backUrl: {
			type: String,
			default: TEMPLATE_LIST_URL,
		},
	},
	setup(props): Object
	{
		useKeyboardShortcuts([
			{
				actionId: EDITOR_ACTION_ID.BACK_TO_TEMPLATE_LIST,
				// The button underneath is a plain link, so the shortcut takes the same one path: a
				// navigation, with none of the guards a button with a handler of its own would run.
				handler: () => {
					window.location.href = props.backUrl;
				},
			},
		]);

		return {
			AirButtonStyle,
			Outline,
		};
	},
	template: `
		<UiButton
			:leftIcon="Outline.HOME"
			:style="AirButtonStyle.PLAIN"
			:link="backUrl"
		/>
	`,
};
