import { BIcon } from 'ui.icon-set.api.vue';

import { useNodeSettingsStore } from '../../../../entities/node-settings';
import { useLoc } from '../../../../shared/composables';
import { PORT_TYPES } from '../../../../shared/constants';
import { createInputBaseSettings } from '../../lib/create-input-base-settings.ts';

import './style.css';

type AddSettingsItemSetup = {
	getMessage: () => string;
	actions: {
		rule: () => void;
	},
};

// @vue/component
export const AddSettingsItem = {
	name: 'AddSettingsItem',
	components: { BIcon },
	props:
	{
		itemType:
		{
			type: String,
			required: true,
		},
		iconName:
		{
			type: String,
			default: 'plus-m',
		},
	},
	emits: ['addItem'],
	setup(): AddSettingsItemSetup
	{
		const { getMessage } = useLoc();
		const store = useNodeSettingsStore();
		const actions = {
			rule: () => {
				const ruleId = store.addRule();
				store.addRulePort(ruleId, PORT_TYPES.input);
				// The button of the panel is a creation of an ordinary input as much as dropping a node or
				// a connection is, so the block joins it in the same action (ALG-02) and through the same
				// module the canvas paths use (BlockMediator.addComplexBlockPort).
				createInputBaseSettings(store.nodeSettings?.rules ?? null, ruleId, store.block?.activity ?? null);
				store.markPortAsDraft(ruleId);
				store.syncPortsWithDiagram();
			},
			relation: () => {
				const relationId = store.addRelation();
				store.addRelationPort(relationId, PORT_TYPES.inputRelation);
				store.markPortAsDraft(relationId);
				store.syncPortsWithDiagram();
			},
		};

		return {
			getMessage,
			actions,
		};
	},
	template: `
		<button
			type="button"
			class="editor-chart-node-settings-add-item-button"
			:data-test-id="$testId('complexNodeSettingsAdd', itemType)"
			@click="actions[this.itemType]()"
		>
			<BIcon
				class="editor-chart-node-settings-add-item-button__plus"
				:name="iconName"
				:size="18"
				color="currentColor"
				aria-hidden="true"
			/>
			<span>
				<slot />
			</span>
		</button>
	`,
};
