import { Browser, Loc, Type } from 'main.core';
import { getReservedCombos, normalizeCombo } from 'ui.block-diagram';
import { markRaw } from 'ui.vue3';
import { defineStore } from 'ui.vue3.pinia';

import { hotkeysApi, HOTKEYS_SETTINGS_VERSION } from '../api/hotkeys-api';
import { getEditorActionCatalog, getEditorActionDefaults, RESERVED_EDITOR_COMBOS } from '../model/action-catalog.ts';

const SAVE_ERROR_PHRASE = 'BIZPROCDESIGNER_EDITOR_HOTKEYS_ERROR_SAVE';

/**
 * The stored value (DTO-01) as it arrives from the server, turned into the set of overrides the
 * editor works with. Everything the catalog cannot vouch for is dropped, record by record: a
 * personal setting is the one place where a stale or hand-edited value must not keep the editor
 * from opening.
 *
 * @param {?Object} initHotkeys value of the user option, `{ version, bindings }`
 * @param {boolean} isMac
 * @returns {Object<string, string | null>} canonical combo per action id, null where the user took
 *   the combo away
 */
function sanitizeOverrides(initHotkeys, isMac)
{
	if (!Type.isPlainObject(initHotkeys) || initHotkeys.version !== HOTKEYS_SETTINGS_VERSION)
	{
		return {};
	}

	if (!Type.isPlainObject(initHotkeys.bindings))
	{
		return {};
	}

	const catalog = new Map(getEditorActionCatalog(isMac).map((action) => [action.id, action]));
	const reservedCombos = getReservedCombos(isMac);
	const overrides = {};

	Object.entries(initHotkeys.bindings).forEach(([actionId, combo]) => {
		const editorAction = catalog.get(actionId) ?? null;

		if (editorAction === null || !editorAction.isReassignable)
		{
			return;
		}

		if (Type.isNil(combo))
		{
			overrides[actionId] = null;

			return;
		}

		// Anything the normalization cannot make a combo of - a number, an empty string, a key that
		// does not exist - comes back as an empty string, and that is the whole test of validity.
		const normalized = Type.isStringFilled(combo) ? normalizeCombo(combo, isMac) : '';

		if (
			!Type.isStringFilled(normalized)
			|| reservedCombos.has(normalized)
			|| RESERVED_EDITOR_COMBOS.includes(normalized)
		)
		{
			return;
		}

		overrides[actionId] = normalized;
	});

	return overrides;
}

/**
 * The bindings as the registry will resolve them (ALG-01), kept here as the read model of the
 * settings panel: the registry answers about one action at a time and holds no reactive state, so
 * a panel row comparing its combo against the default has nothing else to read.
 *
 * An action the catalog declares with null ships without a combo: it belongs to the defaults as a
 * known action, but holds no binding until a user gives it one.
 *
 * @param {Map<string, string | null>} defaults
 * @param {Object<string, string | null>} overrides
 * @returns {Map<string, string>}
 */
function mergeOverrides(defaults, overrides)
{
	const bindings = new Map();

	defaults.forEach((combo, actionId) => {
		if (!Type.isNil(combo))
		{
			bindings.set(actionId, combo);
		}
	});

	Object.entries(overrides).forEach(([actionId, combo]) => {
		if (!defaults.has(actionId))
		{
			return;
		}

		if (Type.isNil(combo))
		{
			bindings.delete(actionId);

			return;
		}

		bindings.set(actionId, combo);
	});

	return bindings;
}

/**
 * Owns the personal combos of the editor. The saved set and the draft are kept apart on purpose:
 * discarding the unsaved changes is a reset of the draft, while "changed by the user" on a row is
 * the effective combo differing from the default of the catalog - neither question can be answered
 * by a single merged set.
 *
 * This store is the only caller of `applyBindings()`: the registry is rebuilt when the set of
 * overrides changes, never while it is read.
 */
export const useHotkeysStore = defineStore('bizprocdesigner-editor-hotkeys', {
	state: () => ({
		isMac: Browser.isMac(),
		// markRaw: the registry is a class with private fields, and a reactive proxy over it would
		// throw on the first read of one.
		registry: null,
		savedOverrides: {},
		draftOverrides: {},
		isSaving: false,
		// The refusal is a fact of its own, apart from the text that describes it: a phrase missing
		// from the portal must not turn "the combo will not survive a reload" into silence.
		hasSaveError: false,
		errorMessage: null,
		lastSaveId: 0,
	}),
	getters:
	{
		defaultCombos: (state) => getEditorActionDefaults(state.isMac),
		/**
		 * The draft over the saved set, minus every entry that ended up restating the catalog. That
		 * subtraction is what a reset is made of: a row given its default back leaves no record
		 * behind, instead of freezing today's default into the personal settings of a user.
		 */
		effectiveOverrides()
		{
			const merged = { ...this.savedOverrides, ...this.draftOverrides };
			const overrides = {};

			Object.entries(merged).forEach(([actionId, combo]) => {
				if ((this.defaultCombos.get(actionId) ?? null) !== (combo ?? null))
				{
					overrides[actionId] = combo;
				}
			});

			return overrides;
		},
		effectiveBindings()
		{
			return mergeOverrides(this.defaultCombos, this.effectiveOverrides);
		},
		hasOverrides()
		{
			return Object.keys(this.effectiveOverrides).length > 0;
		},
		/**
		 * `?? null` alone cannot tell "no override" (key absent) from "override explicitly cleared"
		 * (key present, value null) apart - both would read as null and a real change between the two
		 * would go unnoticed, leaving Save disabled for a row that visibly changed. Presence is checked
		 * on both sides before the values themselves are compared.
		 */
		hasUnsavedChanges()
		{
			const effective = this.effectiveOverrides;
			const actionIds = new Set([...Object.keys(this.savedOverrides), ...Object.keys(effective)]);

			return [...actionIds].some((actionId) => {
				const hadOverride = Object.hasOwn(this.savedOverrides, actionId);
				const hasOverride = Object.hasOwn(effective, actionId);

				if (hadOverride !== hasOverride)
				{
					return true;
				}

				return this.savedOverrides[actionId] !== effective[actionId];
			});
		},
	},
	actions:
	{
		/**
		 * The initial data of the editor reaches the store once, on mount, the way the publication
		 * right and the assistant options already do.
		 *
		 * @param {ActionRegistry} actionRegistry registry of the canvas the editor is mounted on
		 * @param {?Object} initHotkeys value of the user option, `{ version, bindings }`
		 */
		hydrate(actionRegistry, initHotkeys)
		{
			this.registry = markRaw(actionRegistry);
			this.savedOverrides = sanitizeOverrides(initHotkeys, this.isMac);
			this.draftOverrides = {};
			this.applyToRegistry();
		},
		/**
		 * @param {string} actionId
		 * @param {string | null} combo canonical combo, null takes the combo away from the action
		 */
		setDraftCombo(actionId, combo)
		{
			const draft = { ...this.draftOverrides, [actionId]: combo };

			// A combo belongs to at most one action - the invariant `ActionRegistry.applyBindings()`
			// itself enforces by rejecting the whole set otherwise. Vacating the previous owner (if any)
			// in the same edit keeps every caller of this action safe by construction: the capture UI
			// already screens a conflict through `validate()` before it gets here, but a caller with no
			// warning dialog of its own - resetting one row, resetting all of them - must not be able to
			// leave two actions claiming the same combo in the draft it saves.
			if (!Type.isNil(combo))
			{
				// A non-reassignable action keeps its keys whatever happens here: taking them away would
				// leave the accessibility contract of the component that owns them without its key.
				const reassignable = new Set(
					getEditorActionCatalog(this.isMac)
						.filter((editorAction) => editorAction.isReassignable)
						.map((editorAction) => editorAction.id),
				);

				for (const [otherActionId, otherCombo] of this.effectiveBindings)
				{
					if (otherActionId !== actionId && otherCombo === combo && reassignable.has(otherActionId))
					{
						draft[otherActionId] = null;
						break;
					}
				}
			}

			this.draftOverrides = draft;
			// The registry is the source `validate()` reads a conflict against (hotkeys-combo-capture.js):
			// a draft left unsynced would let a second reassignment within the same session read a
			// combo just given away as still occupied - or, worse, a combo just taken as still free.
			this.applyToRegistry();
		},
		/**
		 * Gives one action its catalog combo back. Written as a draft entry rather than as a deletion:
		 * the saved set may hold an override of its own, and only an entry can outweigh it before the
		 * user saves. The entry disappears from `effectiveOverrides` on its own, being equal to the
		 * default.
		 */
		resetDraftCombo(actionId)
		{
			this.setDraftCombo(actionId, this.defaultCombos.get(actionId) ?? null);
		},
		/**
		 * The same for every action a user has touched, saved ones included. Still a draft: the whole
		 * panel edits the draft, and nothing reaches the stored settings until `save()`.
		 *
		 * Touched is read off `savedOverrides` and `draftOverrides` directly, not off the filtered
		 * `effectiveOverrides`: an action a standalone reset already brought back to its default has no
		 * entry left there (that is the whole point of the subtraction), but its draft entry - the
		 * explicit "this one goes back to the default" - must survive being folded into the entry a
		 * "reset all" makes for it, not disappear and let the saved override under it show through again.
		 */
		resetAllDraftCombos()
		{
			const touchedActionIds = new Set([
				...Object.keys(this.savedOverrides),
				...Object.keys(this.draftOverrides),
			]);
			const draft = {};

			touchedActionIds.forEach((actionId) => {
				draft[actionId] = this.defaultCombos.get(actionId) ?? null;
			});

			this.draftOverrides = draft;
			this.applyToRegistry();
		},
		/**
		 * A save already on its way to the server leaves nothing to discard: the draft is no longer an
		 * undoable edit but the very set being written. Rebuilding the registry here would raise the
		 * still-old `savedOverrides` over it and undo the reassignment in this tab until the answer
		 * arrives - `save()` settles the registry itself, on both the success and the refusal path.
		 *
		 * The refusal itself is dropped whatever the draft does with it. The store outlives the window,
		 * and a warning about an attempt the user has already closed the panel on would come back over
		 * a list holding nothing unsaved. A save in flight has no refusal to drop: `save()` clears both
		 * flags before the request leaves.
		 */
		discardDraft()
		{
			this.hasSaveError = false;
			this.errorMessage = null;

			if (this.isSaving)
			{
				return;
			}

			this.draftOverrides = {};
			this.applyToRegistry();
		},
		/**
		 * The whole set travels in one write. The registry is rebuilt before the request leaves, so
		 * the combo works in this tab without waiting for the answer; a refusal leaves it working
		 * and says so, because the user has to learn that the setting will not survive a reload.
		 *
		 * `savedOverrides` itself moves only once the request actually succeeds: moving it eagerly, the
		 * way the draft is folded into it here, would make `hasUnsavedChanges` read a refused write as
		 * clean - the row would look saved, Save would stay disabled, and the change would be unreachable
		 * again until something else in the draft changed to re-enable it.
		 */
		async save()
		{
			const overrides = this.effectiveOverrides;

			// `savedOverrides` keeps its old value until the request succeeds (see below), so the draft
			// has to carry an explicit entry for every action `savedOverrides` still mentions, not only
			// the ones `overrides` does - otherwise a stale saved entry outside the new set would show
			// back through the merge in `effectiveOverrides`/`effectiveBindings` for the length of the
			// request, undoing a reset the draft had already made.
			const touchedActionIds = new Set([...Object.keys(this.savedOverrides), ...Object.keys(overrides)]);
			const draft = {};

			touchedActionIds.forEach((actionId) => {
				draft[actionId] = Object.hasOwn(overrides, actionId)
					? overrides[actionId]
					: (this.defaultCombos.get(actionId) ?? null)
				;
			});

			this.draftOverrides = draft;
			this.applyToRegistry();

			const saveId = ++this.lastSaveId;
			this.isSaving = true;
			this.hasSaveError = false;
			this.errorMessage = null;
			try
			{
				await hotkeysApi.saveOverrides(overrides);

				if (this.lastSaveId === saveId)
				{
					this.savedOverrides = overrides;
					this.draftOverrides = {};
					// The set moved from the draft to the saved side, and the registry has to be told: a
					// panel closed while the request was in flight discarded the draft the registry stood
					// on, leaving the combos of this tab back at the defaults with nothing to bring them
					// back until a reload.
					this.applyToRegistry();
				}
			}
			catch
			{
				if (this.lastSaveId === saveId)
				{
					this.hasSaveError = true;
					this.errorMessage = Loc.getMessage(SAVE_ERROR_PHRASE) ?? '';
				}
			}
			finally
			{
				if (this.lastSaveId === saveId)
				{
					this.isSaving = false;
				}
			}
		},
		applyToRegistry()
		{
			if (this.registry === null)
			{
				return;
			}

			this.registry.applyBindings(this.defaultCombos, new Map(Object.entries(this.effectiveOverrides)));
		},
	},
});
