import { Type } from 'main.core';
import { LiveAnnouncer } from 'ui.a11y';
import { AlertDesign } from 'ui.system.alert';
import { Alert } from 'ui.system.alert.vue';

import { useLoc, type GetMessage } from '../../composables';
import { resolveBrokenLinksMessage } from '../../utils';

import './style.css';

/**
 * The areas a warning about the missing values may speak for (TPL-02). Declared once and used by
 * every place that shows one: the name of an area travels from there into this component and nowhere
 * else, so an unknown one is caught at the border instead of quietly naming nothing.
 *
 * The set is the union over all of them, and each uses the subset it lays out. The first three are
 * the sections of a panel; the last one is the form of a construction, which shows a warning of its
 * own over the markup the dialog sent (EditBaseSettings, EditExtendedAction).
 */
export const BROKEN_LINKS_SCOPES: { [string]: string } = Object.freeze({
	general: 'general',
	rules: 'rules',
	relations: 'relations',
	constructionForm: 'constructionForm',
});

/**
 * A value the warning names. The address is opaque here: the component only tells an addressed value
 * from an unaddressed one, and what the address means is known to the panel that built it.
 */
export type BrokenLinksNoticeItem = {
	link: string,
	target: ?mixed,
};

let listIdCounter = 0;

type BrokenLinksNoticeSetup = {
	getMessage: GetMessage,
	AlertDesign: typeof AlertDesign,
	listId: string,
};

// @vue/component
export const BrokenLinksNotice = {
	name: 'BrokenLinksNotice',
	components: {
		Alert,
	},
	props: {
		/** The values this warning names, in the order of the list of the server. */
		items: {
			type: Array,
			required: true,
		},
		/** The area of the panel this warning stands in. */
		scope: {
			type: String,
			required: true,
			validator: (scope: string): boolean => Object.values(BROKEN_LINKS_SCOPES).includes(scope),
		},
		/**
		 * Names the action of an addressed value twice over: as the hint of the mouse and as the
		 * accessible name of the button, where the value itself is appended to it.
		 */
		goToLabel: {
			type: String,
			required: true,
		},
		/**
		 * Whether this area speaks for the panel. One and the same trouble is written in one and the
		 * same phrase in every area, so announcing it once per area would repeat it (WCAG 4.1.3). Which
		 * area speaks is decided by the panel: the areas and the order they are laid out in are its own.
		 *
		 * Read at the moment the warning appears and not at the moment the right to speak arrives: an
		 * area already shown that is granted the right later stays silent (see the watcher of `isShown`).
		 */
		shouldAnnounce: {
			type: Boolean,
			default: false,
		},
		/** The base of the ids the panel marks its elements with (DTO-01). */
		testIdBase: {
			type: String,
			required: true,
		},
	},
	/**
	 * `dismiss` tells the panel the warning was closed. The closing is lifted by values landing where
	 * there were none (see the watcher of `items`), so a panel that wants the warning back on the next
	 * set of values has to empty the area itself; one that leaves the values in place keeps the warning
	 * closed for good.
	 */
	emits: ['itemClick', 'dismiss'],
	setup(): BrokenLinksNoticeSetup
	{
		const { getMessage } = useLoc();
		listIdCounter++;

		return {
			getMessage,
			AlertDesign,
			// The list the button of the warning expands, named for aria-controls.
			listId: `editor-chart-broken-links-notice-list-${listIdCounter}`,
		};
	},
	data(): Object
	{
		return {
			// The list of values is folded until asked for: the warning names the trouble, the list names
			// the places.
			isListShown: false,
			// A warning the user has closed stays closed for the values it names: it is values landing
			// where there were none that ask the question anew (see the watcher of `items`).
			isDismissed: false,
		};
	},
	computed:
	{
		isShown(): boolean
		{
			return this.items.length > 0 && !this.isDismissed;
		},
		alertText(): string
		{
			return resolveBrokenLinksMessage();
		},
		// The button is a toggle, so it says what the next press will do: a caption that stays put
		// while the list opens tells the user nothing about the way back.
		toggleListText(): string
		{
			if (this.isListShown)
			{
				// The wording of the way back is new. Where it has not arrived, the expanded button would
				// be left with no caption and no accessible name at all, and the list with nothing to fold
				// it back: the caption of the folded state stands in, naming the same toggle.
				const collapseText = this.getMessage('BIZPROCDESIGNER_EDITOR_MESSAGE_COLLAPSE_LINKS');
				if (Type.isStringFilled(collapseText))
				{
					return collapseText;
				}
			}

			return this.getMessage('BIZPROCDESIGNER_EDITOR_MESSAGE_SHOW_LINKS') ?? '';
		},
	},
	watch:
	{
		/**
		 * A warning is closed for the values it names, so values landing where there were none ask the
		 * question anew. Both panels keep one and the same instance across nodes, and in both the
		 * closing is lifted, because both empty the area before the values of the next node land: the
		 * panel of simple nodes in its handler of the closing, the one of complex nodes by the list the
		 * store nulls on a switch of the node. Without it the closing of one node would silence every
		 * node after it.
		 */
		items(items: Array<BrokenLinksNoticeItem>, previousItems: Array<BrokenLinksNoticeItem>): void
		{
			if (items.length > 0 && previousItems.length === 0)
			{
				this.isDismissed = false;
			}
		},
		/**
		 * The warning arrives while the panel is already open, so it is spoken of when it lands. Spoken
		 * of is the landing itself and not the passing of the right to speak: a closing hands that right
		 * over to the neighbouring area, and announcing it would repeat aloud the very warning the user
		 * has just closed.
		 *
		 * The announcer of `ui.a11y` keeps a live region of its own outside the panel: a region rendered
		 * together with the text it holds is not announced at all, and an area that is both always laid
		 * out and always filled is not known to the panels.
		 */
		isShown:
		{
			immediate: true,
			handler(isShown: boolean): void
			{
				if (isShown && this.shouldAnnounce)
				{
					LiveAnnouncer.announce(this.alertText);
				}
			},
		},
	},
	methods:
	{
		// The id of an element of this warning: the base of the panel, the part, the area (DTO-01).
		scopeTestId(part: string): string
		{
			return this.$testId(`${this.testIdBase}-${part}`, this.scope);
		},
		// The button keeps its place while the list is open, so the list can be folded back and the
		// focus of the press is not taken down with the button that carried it.
		toggleList(): void
		{
			this.isListShown = !this.isListShown;
		},
		dismiss(): void
		{
			// The close button goes away with the warning it closes, and a focus left on it would land
			// on <body>. The block of the warning stays in the section and takes it instead - only when
			// the focus is inside the warning, because taking it from a user working elsewhere is never
			// right (rescueFocus).
			if (this.$el?.contains?.(document.activeElement))
			{
				this.$el.focus({ preventScroll: true });
			}

			this.isDismissed = true;
			this.$emit('dismiss');
		},
	},
	/**
	 * The block of the warning stands in the DOM for an empty list as well: only its spacing follows
	 * the filling, and it is what receives the focus when the warning is closed (dismiss).
	 */
	template: `
		<div
			class="editor-chart-broken-links-notice"
			:class="{ '--filled': isShown }"
			:data-testid="scopeTestId('block')"
			tabindex="-1"
		>
			<Alert
				v-if="isShown"
				:design="AlertDesign.tintedWarning"
				hasCloseButton
				:data-testid="scopeTestId('alert')"
				@closeButtonClick="dismiss"
			>
				<span :data-testid="scopeTestId('alert-text')">{{ alertText }}</span>
				<button
					type="button"
					class="editor-chart-broken-links-notice__show-more"
					:aria-expanded="isListShown ? 'true' : 'false'"
					:aria-controls="isListShown ? listId : null"
					:data-testid="scopeTestId('show-more')"
					@click="toggleList"
				>{{ toggleListText }}</button>
				<ul
					v-if="isListShown"
					:id="listId"
					class="editor-chart-broken-links-notice__list"
					:data-testid="scopeTestId('list')"
				>
					<li v-for="item in items" :key="item.link">
						<button
							v-if="item.target"
							type="button"
							class="editor-chart-broken-links-notice__item --clickable"
							:title="goToLabel"
							:aria-label="goToLabel + ': ' + item.link"
							:data-testid="scopeTestId('item')"
							@click="$emit('itemClick', item)"
						>{{ item.link }}</button>
						<div
							v-else
							class="editor-chart-broken-links-notice__item"
							:data-testid="scopeTestId('item-text')"
						>{{ item.link }}</div>
					</li>
				</ul>
			</Alert>
		</div>
	`,
};
