import { useCanvasFocus, useKeyboardShortcuts } from 'ui.block-diagram';

import { EDITOR_REGION_ID, moveToAdjacentRegion, registerRegion, unregisterRegion } from '../../../../shared/a11y';
import { useFeature, useLoc } from '../../../../shared/composables';
import { FocusAnchor, setFocusAnchor } from '../../../../shared/utils/focus-rescue';
import { EDITOR_ACTION_ID } from '../../../hotkeys';
import { CATALOG_WIDTH_COLLAPSED, CATALOG_WIDTH_EXPANDED } from '../../constants/index.ts';

import './app-layout.css';

const SETTINGS_PANEL_CLASSNAMES = {
	base: 'editor-chart-app-layout__settings',
	withPreviewPanel: '--with-preview-panel',
};

const SETTINGS_DATA_INSPECTOR_PANEL_CLASSNAMES = {
	base: 'editor-chart-app-layout__settings-data-inspector',
	shifted: '--shifted',
};

const TOP_RIGHT_TOOLBAR_CLASSNAMES = {
	base: 'editor-chart-app-layout__top-right-toolbar',
	shifted: '--shifted',
	aboveInspectorOverlay: '--above-inspector-overlay',
};

const BOTTOM_RIGHT_TOOLBAR_CLASSNAMES = {
	base: 'editor-chart-app-layout__bottom-right-toolbar',
	shifted: '--shifted',
	margined: '--margined',
	aboveInspectorOverlay: '--above-inspector-overlay',
};

const DEBUG_BAR_TOOLBAR_CLASSNAMES = {
	base: 'editor-chart-app-layout__debug-bar-toolbar',
	shifted: '--shifted',
};

// The four regions the layout owns. The fifth - the header - comes into it as slot content, so it
// is named and registered at the point of use (`src/app.js`), not here.
const REGION_LABEL_MESSAGE_ID = {
	[EDITOR_REGION_ID.DIAGRAM]: 'BIZPROCDESIGNER_EDITOR_REGION_DIAGRAM_ARIA_LABEL',
	[EDITOR_REGION_ID.CATALOG]: 'BIZPROCDESIGNER_EDITOR_REGION_CATALOG_ARIA_LABEL',
	[EDITOR_REGION_ID.TOOLS_TOP]: 'BIZPROCDESIGNER_EDITOR_REGION_TOOLS_TOP_ARIA_LABEL',
	[EDITOR_REGION_ID.TOOLS_BOTTOM]: 'BIZPROCDESIGNER_EDITOR_REGION_TOOLS_BOTTOM_ARIA_LABEL',
};

type AppLayoutSetup = {
	getMessage: (messageId: string, replacements?: Object) => string,
	registerFocusScope: (element: HTMLElement | null) => void,
};

// @vue/component
export const AppLayout = {
	name: 'AppLayout',
	props: {
		showSettings: {
			type: Boolean,
			default: false,
		},
		isDataInspectorPanelShown: {
			type: Boolean,
			default: false,
		},
		isTableSettingsPanelShown: {
			type: Boolean,
			default: false,
		},
		isProcessDataPanelShown: {
			type: Boolean,
			default: false,
		},
		showPreviewPanel: {
			type: Boolean,
			default: false,
		},
		showDebugBar: {
			type: Boolean,
			default: false,
		},
		catalogExpanded: {
			type: Boolean,
			default: true,
		},
		mountWorkspacePanels: {
			type: Boolean,
			default: true,
		},
	},
	setup(): AppLayoutSetup
	{
		const { getMessage } = useLoc();
		const { registerFocusScope } = useCanvasFocus();

		// A press that moved nothing belongs to the page, so both records opt out of the default
		// suppression and the press is claimed only once the move has happened.
		function moveToRegion(step: 1 | -1, event: KeyboardEvent): void
		{
			if (moveToAdjacentRegion(step))
			{
				event.preventDefault();
			}
		}

		// The regions belong to the layout, so the walk between them is registered here and not at the
		// point of use: the canvas state the records reach is available to any component of the app.
		useKeyboardShortcuts([
			{
				actionId: EDITOR_ACTION_ID.NEXT_REGION,
				handler: (event: KeyboardEvent) => moveToRegion(1, event),
				preventDefault: false,
			},
			{
				actionId: EDITOR_ACTION_ID.PREV_REGION,
				handler: (event: KeyboardEvent) => moveToRegion(-1, event),
				preventDefault: false,
			},
		]);

		return { getMessage, registerFocusScope };
	},
	computed: {
		// The inspector scrim makes the diagram inert; the editor toolbars stay reachable.
		isInspectorOverlayShown(): boolean
		{
			return this.showSettings && (this.isDataInspectorPanelShown || this.isTableSettingsPanelShown);
		},
		topRightClassNames(): { [string]: boolean }
		{
			return {
				[TOP_RIGHT_TOOLBAR_CLASSNAMES.base]: true,
				[TOP_RIGHT_TOOLBAR_CLASSNAMES.shifted]: this.showSettings,
				[TOP_RIGHT_TOOLBAR_CLASSNAMES.aboveInspectorOverlay]: this.isInspectorOverlayShown,
			};
		},
		bottomRightClassNames(): { [string]: boolean }
		{
			return {
				[BOTTOM_RIGHT_TOOLBAR_CLASSNAMES.base]: true,
				[BOTTOM_RIGHT_TOOLBAR_CLASSNAMES.shifted]: this.showSettings,
				[BOTTOM_RIGHT_TOOLBAR_CLASSNAMES.margined]: this.showDebugBar,
				[BOTTOM_RIGHT_TOOLBAR_CLASSNAMES.aboveInspectorOverlay]: this.isInspectorOverlayShown,
			};
		},
		debugBarClassNames(): { [string]: boolean }
		{
			return {
				[DEBUG_BAR_TOOLBAR_CLASSNAMES.base]: true,
				[DEBUG_BAR_TOOLBAR_CLASSNAMES.shifted]: this.showSettings,
			};
		},
		settingsClassNames(): { [string]: boolean }
		{
			return {
				[SETTINGS_PANEL_CLASSNAMES.base]: true,
				[SETTINGS_PANEL_CLASSNAMES.withPreviewPanel]: this.showPreviewPanel,
			};
		},
		// The section receives the rescued focus when the settings content is replaced, and the header
		// of the panel goes down with that content, so the name cannot be a reference into it.
		settingsPanelLabel(): string
		{
			return this.getMessage('BIZPROCDESIGNER_EDITOR_SETTINGS_PANEL_ARIA_LABEL');
		},
		regionLabels(): { [string]: string }
		{
			const labels = {};

			Object.keys(REGION_LABEL_MESSAGE_ID).forEach((id) => {
				labels[id] = this.getMessage(REGION_LABEL_MESSAGE_ID[id]);
			});

			return labels;
		},
		settingsDataInspectorClassNames(): { [string]: boolean }
		{
			return {
				[SETTINGS_DATA_INSPECTOR_PANEL_CLASSNAMES.base]: true,
			};
		},
		debugBarStyle(): { [string]: string }
		{
			const SETTINGS_WIDTH = 470;
			const SIDE_MARGINS = 40;
			const SIDE_PADDINGS = 10;
			const catalogWidth = this.catalogExpanded ? CATALOG_WIDTH_EXPANDED : CATALOG_WIDTH_COLLAPSED;
			const settingsWidth = this.showSettings ? SETTINGS_WIDTH + 10 : 0;

			const maxWidth = `calc(100vw - ${catalogWidth}px - ${settingsWidth}px - ${SIDE_MARGINS}px - ${SIDE_PADDINGS}px)`;

			return {
				width: maxWidth,
			};
		},
		isDebugBarAvailable(): boolean
		{
			const { isFeatureAvailable } = useFeature();

			return isFeatureAvailable('debugBar');
		},
	},
	// The content of the layout is the work area of the editor: the canvas, the catalog, the toolbars
	// and the panels stand inside it, while the header and the popups drawn into `body` do not. The
	// canvas answers an Escape nobody claimed only inside it.
	mounted(): void
	{
		this.registerFocusScope(this.$refs.content);
	},
	unmounted(): void
	{
		this.registerFocusScope(null);
	},
	methods: {
		// A reference callback is the moment the region is mounted and the moment it is gone: Vue
		// hands the element over on mount and hands null back on unmount, so a region hidden by a
		// `v-if` leaves the walk instead of staying in it as a node off the document.
		setRegion(id: string, element: ?HTMLElement): void
		{
			if (element instanceof HTMLElement)
			{
				registerRegion(id, element, this.regionLabels[id]);
			}
			else
			{
				unregisterRegion(id);
			}
		},
		setDiagramRegion(element: ?HTMLElement): void
		{
			this.setRegion(EDITOR_REGION_ID.DIAGRAM, element);
		},
		setCatalogRegion(element: ?HTMLElement): void
		{
			this.setRegion(EDITOR_REGION_ID.CATALOG, element);
		},
		setToolsTopRegion(element: ?HTMLElement): void
		{
			this.setRegion(EDITOR_REGION_ID.TOOLS_TOP, element);
		},
		setToolsBottomRegion(element: ?HTMLElement): void
		{
			this.setRegion(EDITOR_REGION_ID.TOOLS_BOTTOM, element);
		},
		setSettingsAnchor(element: ?HTMLElement): void
		{
			setFocusAnchor(FocusAnchor.settingsPanel, element);
		},
		setDataInspectorAnchor(element: ?HTMLElement): void
		{
			setFocusAnchor(FocusAnchor.dataInspectorPanel, element);
		},
	},
	template: `
		<div
			class="editor-chart-app-layout"
			:data-test-id="$testId('editorLayout')"
		>
			<transition name="fade-skeleton">
				<slot name="skeleton" />
			</transition>

			<!-- A plain div and no ARIA of its own: it is here that the header stops being sectioning
				content, and the <header> inside the slot gets its own banner back. -->
			<div class="editor-chart-app-layout__header">
				<slot name="header"/>
			</div>
			<div ref="content" class="editor-chart-app-layout__content">
				<main
					:ref="setDiagramRegion"
					class="editor-chart-app-layout__diagram editor-chart-a11y-focus-ring"
					:aria-label="regionLabels.diagram"
				>
					<slot name="diagram"/>
				</main>

				<!-- After the diagram and never before it: the state of the canvas belongs to whoever asks
					for it first, so a layer placed above would leave the canvas without its own blocks. -->
				<section class="editor-chart-app-layout__notes-layer">
					<slot name="notes-layer"/>
				</section>

				<!-- The white plate of the catalog is painted by this section and not by the catalog
					itself, so it leaves with the workspace: a full-screen state of the editor would
					otherwise keep an empty plate standing over its own ground. -->
				<aside
					v-if="mountWorkspacePanels"
					:ref="setCatalogRegion"
					class="editor-chart-app-layout__catalog editor-chart-a11y-focus-ring"
					:aria-label="regionLabels.catalog"
				>
					<slot name="catalog"/>
				</aside>

				<!-- <aside> and not a named <section>: measured on the live editor, VoiceOver leaves a
					generic region out of the web rotor, so the toolbars would be unreachable by the
					landmark list even while the walk still stops at them. -->
				<aside
					:ref="setToolsTopRegion"
					class="editor-chart-a11y-focus-ring"
					:class="topRightClassNames"
					:aria-label="regionLabels.toolsTop"
				>
					<slot name="top-right-toolbar"/>
				</aside>

				<aside
					:ref="setToolsBottomRegion"
					class="editor-chart-a11y-focus-ring"
					:class="bottomRightClassNames"
					:aria-label="regionLabels.toolsBottom"
				>
					<slot name="bottom-right-toolbar"/>
				</aside>

				<section v-if="showDebugBar && isDebugBarAvailable" :class="debugBarClassNames" :style="debugBarStyle">
					<slot name="debug-bar-toolbar"/>
				</section>

				<section class="editor-chart-app-layout__top-middle-anchor">
					<slot name="top-middle-anchor"/>
				</section>

				<template v-if="mountWorkspacePanels">
				<transition
					name="fade-settings-panel"
					enter-active-class="fade-settings-panel-enter-active"
					leave-active-class="fade-settings-panel-leave-active"
				>
					<section
						v-if="showSettings"
						:ref="setSettingsAnchor"
						:class="settingsClassNames"
						:data-testid="$testId('bizprocdesigner-settings-panel')"
						:aria-label="settingsPanelLabel"
						tabindex="-1"
					>
						<slot name="settings"/>
					</section>
				</transition>

				<transition-group name="fade-inspector-panel">
					<template v-if="isInspectorOverlayShown && !isTableSettingsPanelShown">
						<section
							:ref="setDataInspectorAnchor"
							:class="settingsDataInspectorClassNames"
							:data-testid="$testId('bizprocdesigner-settings-data-inspector')"
							key="data-inspector-section"
						>
							<slot name="settings-data-inspector"/>
						</section>
						<div
							class="editor-chart-app-layout__settings-data-inspector-overlay"
							key="data-inspector-overlay"
						></div>
					</template>
				</transition-group>

				<transition-group name="fade-inspector-panel">
					<template v-if="isInspectorOverlayShown && isTableSettingsPanelShown">
						<section
							:class="settingsDataInspectorClassNames"
							key="table-settings-section"
						>
							<slot name="settings-table-settings"/>
						</section>
						<div
							class="editor-chart-app-layout__settings-data-inspector-overlay"
							key="table-settings-overlay"
						></div>
					</template>
				</transition-group>

				<!-- A window of its own, moved by its header and left open while the scheme is edited:
					it holds no place in the layout and dims nothing behind it. -->
				<slot v-if="isProcessDataPanelShown" name="settings-process-data"/>

				<transition name="fade-preview-panel">
					<section
						v-if="showPreviewPanel"
						class="editor-chart-app-layout__preview-panel"
					>
						<div class="editor-chart-app-layout__preview-panel-conatiner">
							<div
								id="preview-panel"
								class="editor-chart-app-layout__preview-panel-content"
							>
							</div>
						</div>
					</section>
				</transition>
				</template>
			</div>
		</div>
	`,
};
