import { Event, Loc, Type } from 'main.core';
import { ComboVerdict, formatComboCaption, isModifierToken, normalizeCombo } from 'ui.block-diagram';
import { AlertDesign } from 'ui.system.alert';
import { Alert } from 'ui.system.alert.vue';
import { TextSm } from 'ui.system.typography.vue';
import { AirButtonStyle, Button as UiButton, ButtonSize } from 'ui.vue3.components.button';
import { mapActions, mapState } from 'ui.vue3.pinia';

import { getEditorActionCatalog, RESERVED_CONFIRM_COMBO, useHotkeysStore } from '../../../../entities/hotkeys';

import './style.css';

// The press belongs to the recording and to nothing else: the canvas, the panel and the browser all
// listen to the same keys, and the capture phase is the only place before all of them.
const CAPTURE_LISTENER_OPTIONS = Object.freeze({ capture: true });

const ESCAPE_TOKEN = 'escape';
const TAB_TOKEN = 'tab';

const MODIFIER_EVENT_FLAGS = Object.freeze({
	ctrl: 'ctrlKey',
	alt: 'altKey',
	shift: 'shiftKey',
	meta: 'metaKey',
});

const COMBO_SEPARATOR = '+';

// Keys that type nothing, so a combination of one of them alone takes no character away from the
// person editing a name on the canvas or a query in the search field. Every other key - a letter, a
// digit, a punctuation mark - is one that types, and needs a modifier to stop being plain input.
const TYPELESS_TOKENS = Object.freeze([
	'escape',
	'tab',
	'enter',
	'backspace',
	'delete',
	'insert',
	'space',
	'arrowleft',
	'arrowright',
	'arrowup',
	'arrowdown',
]);

const FUNCTION_KEY_PATTERN = /^f([1-9]|1[0-2])$/;

// Shift is not one of them: it types a character of its own - an uppercase letter, the symbol above
// the digit - so it takes a key out of plain input no more than the bare key does. The field of the
// search panel draws the same bound (`isCombinationPress`, search-input.js), so what may be assigned
// here is what works there.
const TYPING_STOPPING_MODIFIERS = Object.freeze(['ctrl', 'alt', 'meta']);

/**
 * Whether a combination may be recorded as it is. A key that types a character stays plain input
 * until a modifier that stops the typing is held with it.
 *
 * @param {string} combo canonical combo
 * @returns {boolean}
 */
function isTypeableBareKey(combo)
{
	const tokens = combo.split(COMBO_SEPARATOR);

	if (tokens.some((token) => TYPING_STOPPING_MODIFIERS.includes(token)))
	{
		return false;
	}

	const mainKey = tokens[tokens.length - 1];

	return !TYPELESS_TOKENS.includes(mainKey) && !FUNCTION_KEY_PATTERN.test(mainKey);
}

/**
 * Records one combination for one action.
 *
 * Two lines of defence stand behind the recording, and neither replaces the other: the press is
 * taken away from the page in the capture phase, so no layer under the panel sees it, and the
 * registry is suspended, so a press that leaks all the same resolves to no action. The suspension
 * is lifted by the unmount alone - the panel ends a recording by dropping this component, whatever
 * the outcome was.
 *
 * A conflict is answered here rather than by the row: the answer is one operation over the draft -
 * the combo is taken from its previous owner and given to the new one - and a row that owns half of
 * it would leave the other half to chance.
 */
// @vue/component
export const HotkeysComboCapture = {
	name: 'HotkeysComboCapture',
	components: {
		Alert,
		TextSm,
		UiButton,
	},
	props: {
		actionId: {
			type: String,
			required: true,
		},
		actionLabel: {
			type: String,
			required: true,
		},
	},
	emits: ['close'],
	setup(): Object
	{
		return {
			AirButtonStyle,
			AlertDesign,
			ButtonSize,
		};
	},
	data(): Object
	{
		return {
			conflictCombo: null,
			conflictOccupantId: null,
			noticeText: '',
		};
	},
	computed: {
		...mapState(useHotkeysStore, ['isMac', 'effectiveBindings', 'registry']),
		conflictOccupant(): ?Object
		{
			if (this.conflictOccupantId === null)
			{
				return null;
			}

			return getEditorActionCatalog(this.isMac)
				.find((editorAction) => editorAction.id === this.conflictOccupantId) ?? null
			;
		},
		hintText(): string
		{
			return this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_HINT', { '#ACTION#': this.actionLabel });
		},
		conflictText(): string
		{
			if (this.conflictOccupant === null)
			{
				return '';
			}

			return this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_CONFLICT', {
				'#COMBO#': formatComboCaption(this.conflictCombo),
				'#ACTION#': this.loc(this.conflictOccupant.labelKey),
			});
		},
	},
	mounted(): void
	{
		this.registry?.suspend();
		Event.bind(document, 'keydown', this.handleKeyDown, CAPTURE_LISTENER_OPTIONS);
	},
	unmounted(): void
	{
		Event.unbind(document, 'keydown', this.handleKeyDown, CAPTURE_LISTENER_OPTIONS);
		this.registry?.resume();
	},
	methods: {
		...mapActions(useHotkeysStore, ['setDraftCombo']),
		loc(phraseCode: string, replacements: ?Object = null): string
		{
			return Loc.getMessage(phraseCode, replacements) ?? '';
		},
		handleKeyDown(event: KeyboardEvent): void
		{
			const token = this.tokenOf(event);

			// Tab is how the buttons of this block are reached from the keyboard, and the block is the
			// one place of the panel a press cannot be taken from: it is left to the browser whole, in
			// both states, and never becomes a recorded combination.
			if (token === TAB_TOKEN)
			{
				return;
			}

			event.preventDefault();
			event.stopPropagation();

			// Escape stands above the conflict: the window keeps it off its own close (closeByEsc:
			// false) exactly so that it answers here, whichever of the two states is shown.
			if (token === ESCAPE_TOKEN)
			{
				if (this.conflictCombo === null)
				{
					this.$emit('close');
				}
				else
				{
					this.cancelReassign();
				}

				return;
			}

			// The question about the previous owner of the combo is still open: until it is answered,
			// a press would record over the very combination it is about.
			if (this.conflictCombo !== null)
			{
				return;
			}

			// A modifier alone is half a combination: the recording waits for the key it modifies.
			if (token === '' || isModifierToken(token))
			{
				return;
			}

			this.applyCombo(this.comboOf(event, token));
		},
		// The physical code, as the input layer of the canvas reads it: a recorded combination has to
		// answer the same press that will later run the action.
		tokenOf(event: KeyboardEvent): string
		{
			return normalizeCombo([Type.isStringFilled(event.code) ? event.code : event.key], this.isMac);
		},
		comboOf(event: KeyboardEvent, token: string): string
		{
			const modifiers = Object.entries(MODIFIER_EVENT_FLAGS)
				.filter(([, flag]) => event[flag] === true)
				.map(([modifier]) => modifier)
			;

			return normalizeCombo([...modifiers, token], this.isMac);
		},
		applyCombo(combo: string): void
		{
			this.noticeText = '';

			if (isTypeableBareKey(combo))
			{
				this.noticeText = this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_NEEDS_MODIFIER', {
					'#COMBO#': formatComboCaption(combo),
				});

				return;
			}

			if (combo === RESERVED_CONFIRM_COMBO)
			{
				this.noticeText = this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_SYSTEM_OCCUPIED', {
					'#COMBO#': formatComboCaption(combo),
					'#ACTION#': this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_ACTION_CONFIRM_INPUT'),
				});

				return;
			}

			const verdict = this.registry.validate(combo, this.actionId);

			if (verdict === ComboVerdict.FREE)
			{
				this.setDraftCombo(this.actionId, combo);
				this.$emit('close');

				return;
			}

			if (verdict === ComboVerdict.RESERVED)
			{
				this.noticeText = this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_RESERVED', {
					'#COMBO#': formatComboCaption(combo),
				});

				return;
			}

			this.reportOccupied(combo, this.occupantOf(combo));
		},
		/**
		 * A combination held by an action nobody may rebind is a dead end: the panel says so and keeps
		 * recording, instead of offering a reassignment it would have to refuse.
		 */
		reportOccupied(combo: string, occupant: ?Object): void
		{
			if (occupant?.isReassignable !== true)
			{
				this.noticeText = this.loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_SYSTEM_OCCUPIED', {
					'#COMBO#': formatComboCaption(combo),
					'#ACTION#': occupant === null ? '' : this.loc(occupant.labelKey),
				});

				return;
			}

			this.conflictCombo = combo;
			this.conflictOccupantId = occupant.id;
		},
		/**
		 * Which action holds a combo is read from the bindings of the store and not from the registry:
		 * a suspended registry answers no press, and the recording runs it suspended on purpose.
		 */
		occupantOf(combo: string): ?Object
		{
			const catalog = getEditorActionCatalog(this.isMac);

			for (const [actionId, boundCombo] of this.effectiveBindings)
			{
				if (boundCombo === combo)
				{
					return catalog.find((editorAction) => editorAction.id === actionId) ?? null;
				}
			}

			return null;
		},
		confirmReassign(): void
		{
			this.setDraftCombo(this.conflictOccupantId, null);
			this.setDraftCombo(this.actionId, this.conflictCombo);
			this.$emit('close');
		},
		// Cancelling the reassignment returns to the recording: the answer is about one combination,
		// not about the intention to give the action a combination at all.
		cancelReassign(): void
		{
			this.conflictCombo = null;
			this.conflictOccupantId = null;
		},
		cancel(): void
		{
			this.$emit('close');
		},
	},
	template: `
		<div class="bizprocdesigner-hotkeys-capture" data-testid="bizprocdesigner-editor-hotkeys-capture">
			<Alert
				v-if="conflictCombo !== null"
				:design="AlertDesign.tintedWarning"
				data-testid="bizprocdesigner-editor-hotkeys-capture-conflict"
			>
				<div class="bizprocdesigner-hotkeys-capture__conflict">
					<span class="bizprocdesigner-hotkeys-capture__conflict-text">{{ conflictText }}</span>
					<UiButton
						:text="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_REASSIGN')"
						:style="AirButtonStyle.FILLED"
						:size="ButtonSize.EXTRA_SMALL"
						:dataset="{ testid: 'bizprocdesigner-editor-hotkeys-capture-reassign' }"
						@click="confirmReassign"
					/>
					<UiButton
						:text="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_CANCEL')"
						:style="AirButtonStyle.PLAIN"
						:size="ButtonSize.EXTRA_SMALL"
						:dataset="{ testid: 'bizprocdesigner-editor-hotkeys-capture-conflict-cancel' }"
						@click="cancelReassign"
					/>
				</div>
			</Alert>
			<template v-else>
				<TextSm class="bizprocdesigner-hotkeys-capture__hint">{{ hintText }}</TextSm>
				<TextSm
					v-if="noticeText !== ''"
					class="bizprocdesigner-hotkeys-capture__notice"
					data-testid="bizprocdesigner-editor-hotkeys-capture-notice"
				>{{ noticeText }}</TextSm>
				<div class="bizprocdesigner-hotkeys-capture__cancel">
					<UiButton
						:text="loc('BIZPROCDESIGNER_EDITOR_HOTKEYS_CAPTURE_CANCEL')"
						:style="AirButtonStyle.PLAIN"
						:size="ButtonSize.EXTRA_SMALL"
						:dataset="{ testid: 'bizprocdesigner-editor-hotkeys-capture-cancel' }"
						@click="cancel"
					/>
				</div>
			</template>
		</div>
	`,
};
