import { EventEmitter } from 'main.core.events';
import { Button as UiButton, AirButtonStyle, ButtonSize } from 'ui.vue3.components.button';
import { Popup } from 'ui.vue3.components.popup';
import { mapActions, mapState } from 'ui.vue3.pinia';

import { EVENT_NAMES, generateNextOutputPortId, useNodeSettingsStore } from '../../../../entities/node-settings';
import { useLoc } from '../../../../shared/composables';
import { PORT_TYPES } from '../../../../shared/constants';
import { type Port } from '../../../../shared/types';

import './style.css';

const OUTPUT_LABELS = {
	rule: 'E',
	relation: 'NE',
};

// @vue/component
export const EditOutputExpression = {
	name: 'EditOutputExpression',
	components: { UiButton, Popup },
	props:
	{
		/** @type OutputConstruction */
		construction:
		{
			type: Object,
			required: true,
		},
		/**
		 * @type Port | PortlessRule
		 * Rule of the row this output belongs to. Without it the output works on the single rule the
		 * panel shows: only the all-rules mode has no single one, and there every row names its own.
		 */
		rulePort:
		{
			type: [Object, null],
			default: null,
		},
		/**
		 * The scroll subscription and local relation outputs wait until the rule is reached.
		 */
		isLive:
		{
			type: Boolean,
			default: true,
		},
	},
	setup(): { getMessage: () => string; AirButtonStyle: typeof AirButtonStyle; ButtonSize: typeof ButtonSize; }
	{
		const { getMessage } = useLoc();

		return { getMessage, AirButtonStyle, ButtonSize };
	},
	data(): { isPopupShown: boolean; relationOutputPorts: Array<Port>; }
	{
		return {
			isPopupShown: false,
			relationOutputPorts: [],
		};
	},
	computed:
	{
		...mapState(useNodeSettingsStore, ['nodeSettings', 'ports', 'currentRule', 'availableOutputPorts', 'canCreateOutputForRule']),
		/** Rule this output works on: the one of its own row, or the single rule the panel shows. */
		targetRulePort(): Object | null
		{
			return this.rulePort ?? this.currentRule;
		},
		allOutputPorts(): Array<Port>
		{
			return this.portType === PORT_TYPES.outputRelation ? this.relationOutputPorts : this.availableOutputPorts;
		},
		canAddOutput(): boolean
		{
			return this.portType === PORT_TYPES.outputRelation || this.canCreateOutputForRule(this.targetRulePort);
		},
		selectedPort:
		{
			get(): string
			{
				const { portId, title } = this.construction.expression;

				return {
					title,
					portId,
				};
			},
			set(output: { portId: string, title: string }): void
			{
				const { portId, title } = output;
				this.changeRuleExpression(this.construction, {
					portId,
					title,
				});
			},
		},
		notSelectedMessage(): string
		{
			return this.getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_EXPRESSION_ITEM_NOT_SELECTED');
		},
		popupOptions(): Object
		{
			return {
				id: `edit-output-expression-popup-${this.construction.id}`,
				bindElement: this.$refs.nodeSettingsRuleOutputDropdown,
				minHeight: 100,
				maxHeight: 200,
				padding: 0,
				width: 200,
				focusTrap: {
					initialFocus: () => this.$refs.outputPopup?.querySelector('[tabindex="0"], button') ?? null,
					preventScroll: true,
				},
			};
		},
		// The id of an output has one generator. The dropdown keeps its own copy of the ports (portId
		// instead of id), so the generator gets the very list the local numbering was counted off.
		portId(): string
		{
			return generateNextOutputPortId(
				this.allOutputPorts.map((port: Port) => ({ ...port, id: port.portId })),
			);
		},
		portTitle(): string
		{
			const lastPort = this.filteredPorts[this.filteredPorts.length - 1];
			const label = this.portType === PORT_TYPES.output
				? OUTPUT_LABELS.rule
				: OUTPUT_LABELS.relation;
			const num = (lastPort?.title.split(label)[1]) ?? 0;

			return `${label}${Number(num) + 1}`;
		},
		portType(): string
		{
			return this.targetRulePort?.type === PORT_TYPES.inputRelation
				? PORT_TYPES.outputRelation
				: PORT_TYPES.output;
		},
		filteredPorts(): Array<Port>
		{
			return this.targetRulePort?.type === PORT_TYPES.inputRelation
				? this.allOutputPorts.filter((port) => port.type === PORT_TYPES.outputRelation)
				: this.allOutputPorts.filter((port) => port.type === PORT_TYPES.output);
		},
		/** Id of the caption the read-only action field is named by; the construction keeps it unique. */
		actionCaptionId(): string
		{
			return `editor-chart-node-settings-output-action-caption-${this.construction.id}`;
		},
	},
	watch:
	{
		isLive:
		{
			immediate: true,
			handler(isLive: boolean): void
			{
				if (isLive)
				{
					this.setUpOutputPorts();
				}
			},
		},
	},
	unmounted(): void
	{
		// The subscription exists only once the editor has been set up (see setUpOutputPorts); the
		// immediate isLive watcher may have done that before created() would have run.
		if (this.closePopupOnScroll)
		{
			EventEmitter.unsubscribe(EVENT_NAMES.SCROLL_EVENT, this.closePopupOnScroll);
		}
	},
	methods: {
		...mapActions(useNodeSettingsStore, ['changeRuleExpression', 'createOutputForRules']),
		/**
		 * Subscribe once the rule is reached; relation outputs keep their local creation flow.
		 */
		setUpOutputPorts(): void
		{
			if (this.closePopupOnScroll)
			{
				return;
			}

			// The dropdown of the outputs hangs outside the scrolled flow, so it closes on a scroll of the
			// panel. A subscription and not a prop: the state of the scroll as a prop re-renders every
			// editor of every rule twice per scroll event.
			this.closePopupOnScroll = () => {
				this.isPopupShown = false;
			};
			EventEmitter.subscribe(EVENT_NAMES.SCROLL_EVENT, this.closePopupOnScroll);
			if (this.portType !== PORT_TYPES.outputRelation)
			{
				return;
			}
			this.relationOutputPorts = this.ports.reduce((acc, port) => {
				if (port.type === PORT_TYPES.output || port.type === PORT_TYPES.outputRelation)
				{
					acc.push({
						portId: port.id,
						title: port.title,
						type: port.type,
					});
				}

				return acc;
			}, []) ?? [];
			if (this.filteredPorts.length === 0)
			{
				this.addNewPort();
			}
		},
		onDropdownClick(): void
		{
			// The click that reaches the dropdown is the one making the section live, so the ports may
			// be a tick away; asked for directly, the popup opens filled on the very first click.
			this.setUpOutputPorts();
			this.isPopupShown = true;
		},
		selectPort(port: Port): void
		{
			this.selectedPort = port;
			this.closePopup();
		},
		addNewPort(): void
		{
			this.relationOutputPorts.push({
				portId: this.portId,
				title: this.portTitle,
				type: this.portType,
			});
		},
		deletePort(portId: string): void
		{
			if (this.portType === PORT_TYPES.outputRelation)
			{
				this.relationOutputPorts = this.relationOutputPorts.filter((port) => port.portId !== portId);
			}

			if (portId === this.selectedPort.portId)
			{
				this.selectedPort = {
					portId: null,
					title: null,
				};
			}
		},
		async tryToScrollBottom(): void
		{
			await this.$nextTick();
			const dropDownContent = this.$refs.nodeSettingsRuleOutputDropdownContent;
			const { scrollHeight, clientHeight } = dropDownContent;
			if (scrollHeight > clientHeight)
			{
				dropDownContent.scrollTop = scrollHeight - clientHeight;
			}
		},
		onAddButtonClick(): void
		{
			if (this.portType === PORT_TYPES.outputRelation)
			{
				this.addNewPort();
				this.tryToScrollBottom();

				return;
			}

			if (this.createOutputForRules(this.construction, this.targetRulePort))
			{
				this.closePopup();
			}
		},
		async closePopup(): Promise<void>
		{
			this.isPopupShown = false;
			await this.$nextTick();
			this.$refs.nodeSettingsRuleOutputDropdown.focus();
		},
	},
	template: `
		<div class="editor-chart-node-settings-edit-output-expression-form">
			<div class="editor-chart-node-settings-edit-output-expression-form__item">
				<!-- The caption of the field is its programmatic name as well: the field is read-only and
				always says the same thing, so a label of its own would repeat the caption word for word -->
				<span
					:id="actionCaptionId"
					class="editor-chart-node-settings-edit-output-expression-form__label"
				>
					{{ getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_ACTION_EXPRESSION_NAME') }}
				</span>
				<div class="ui-ctl ui-ctl-textbox">
					<input
						type="text"
						class="ui-ctl-element"
						readonly
						:aria-labelledby="actionCaptionId"
						:value="getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_ACTION_OUTPUT_TITLE')"
					/>
				</div>
			</div>
			<div class="editor-chart-node-settings-edit-output-expression-form__item">
				<span class="editor-chart-node-settings-edit-output-expression-form__label">
					{{ getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_EXPRESSION_VALUE') }}
				</span>
				<div
					class="ui-ctl ui-ctl-after-icon ui-ctl-dropdown editor-chart-node-settings-edit-output-expression-form__dropdown"
					ref="nodeSettingsRuleOutputDropdown"
					role="button"
					tabindex="0"
					:aria-label="getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_EXPRESSION_VALUE')"
					:aria-expanded="isPopupShown"
					data-testid="bizprocdesigner-output-selector"
					@click="onDropdownClick"
					@keydown.enter.self.prevent="onDropdownClick"
					@keydown.space.self.prevent="onDropdownClick"
				>
					<div class="ui-ctl-after ui-ctl-icon-angle"></div>
					<div
						class="ui-ctl-element"
						ref="nodeSettingsRuleOutputDropdownValue"
					>
						{{ selectedPort.title ?? notSelectedMessage }}
					</div>
					<Popup
						v-if="isPopupShown"
						:options="popupOptions"
						@close="isPopupShown = false"
					>
						<div
							ref="outputPopup"
							class="editor-chart-node-settings-edit-output-expression-form__dropdown_popup"
						>
							<div
								class="editor-chart-node-settings-edit-output-expression-form__dropdown_popup-content"
								ref="nodeSettingsRuleOutputDropdownContent"
							>
								<div
									v-for="outputPort in filteredPorts"
									class="editor-chart-node-settings-edit-output-expression-form__dropdown_popup-item"
									role="button"
									tabindex="0"
									@click.stop="selectPort(outputPort)"
									@keydown.enter.self.prevent="selectPort(outputPort)"
									@keydown.space.self.prevent="selectPort(outputPort)"
								>
									<span>{{ outputPort.title }}</span>
									<button
										v-if="portType === 'outputRelation' || selectedPort.portId === outputPort.portId"
										class="ui-btn ui-btn-xss --style-outline-no-accent ui-btn-no-caps --air"
										@click.stop="deletePort(outputPort.portId)"
									>
										{{ getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_ACTION_OUTPUT_REMOVE') }}
									</button>
								</div>
							</div>
							<div v-if="canAddOutput" class="editor-chart-node-settings-edit-output-expression-form__dropdown_popup-footer">
								<div
									class="editor-chart-node-settings-edit-output-expression-form__dropdown_popup-footer-content"
									data-testid="bizprocdesigner-output-create"
									@click.stop
								>
									<UiButton
										:text="getMessage('BIZPROCDESIGNER_EDITOR_NODE_SETTINGS_ACTION_OUTPUT_ADD')"
										:size="ButtonSize.EXTRA_SMALL"
										:style="AirButtonStyle.PLAIN_ACCENT"
										@click="onAddButtonClick"
									/>
								</div>
							</div>
						</div>
					</Popup>
				</div>
			</div>
		</div>
	`,
};
