import { FeatureCode } from 'bizprocdesigner.feature';

import { diagramStore } from '../../../entities/blocks/stores';
import { debugBarApi } from '../../../entities/debug-bar/api';
import { DEBUG_BAR_CONFIG } from '../../../entities/debug-bar/constants';
import { useTestRunStore } from '../../../entities/test-run';
import { useFeature } from '../../../shared/composables';
import { handleResponseError } from '../../../shared/utils';

type TestRunWatch = {
	startWatch: () => void;
	stopWatch: () => void;
};

// One watch per editor: every caller of the composable shares it.
let watchIntervalId = null;
let isRefreshing = false;
let watchGeneration = 0;

// A long journal is read over several ticks, so a tick never holds the status back for long
// and never chains requests without an end.
const MAX_TRACE_PAGES_PER_TICK = 4;
const TRACE_BATCH_BUDGET_MS = 1000;

export function canRestoreTestRun(): boolean
{
	return useFeature().isFeatureAvailable(FeatureCode.testRun) && diagramStore().canPublish;
}

function stopWatch(): void
{
	watchGeneration += 1;

	if (watchIntervalId === null)
	{
		return;
	}

	clearInterval(watchIntervalId);
	watchIntervalId = null;
}

function isWatchAlive(generation: number): boolean
{
	return generation === watchGeneration && !document.hidden;
}

export function useTestRunWatch(): TestRunWatch
{
	const testRunStore = useTestRunStore();

	function lastTraceId(): number
	{
		return Number(testRunStore.traces.at(-1)?.id ?? 0);
	}

	/**
	 * @return the cursor of the next page, or null when the session has nothing more to tell.
	 */
	async function loadTracesAfter(sessionId: number, afterId: number, generation: number): Promise<number | null>
	{
		const traces = await debugBarApi.loadTraces({ debugSessionId: sessionId, afterId }) ?? [];
		if (!isWatchAlive(generation))
		{
			return null;
		}

		const newestId = Number(traces.at(-1)?.id ?? 0);

		// the run may have ended or changed while the page was loading
		if (testRunStore.tracedSessionId !== sessionId || newestId <= afterId)
		{
			return null;
		}

		testRunStore.appendTraces(traces);

		return traces.length < DEBUG_BAR_CONFIG.DEFAULT_TRACES_PAGE_SIZE ? null : newestId;
	}

	/**
	 * The journal is read in portions, a finished session included: the tick that follows goes on
	 * from the cursor, and the watch stops only once the session has nothing more to tell.
	 *
	 * @return whether the session may still have traces this tick did not read.
	 */
	async function loadTraces(sessionId: number, generation: number): Promise<boolean>
	{
		let afterId = lastTraceId();
		const deadline = performance.now() + TRACE_BATCH_BUDGET_MS;

		try
		{
			for (let page = 0; afterId !== null; page++)
			{
				const isPortionOver = page > 0
					&& (page >= MAX_TRACE_PAGES_PER_TICK || performance.now() >= deadline)
				;

				if (isPortionOver || !isWatchAlive(generation) || testRunStore.tracedSessionId !== sessionId)
				{
					return true;
				}

				// eslint-disable-next-line no-await-in-loop
				afterId = await loadTracesAfter(sessionId, afterId, generation);
			}
		}
		catch (error)
		{
			handleResponseError(error);

			return false;
		}

		return !isWatchAlive(generation) || testRunStore.tracedSessionId !== sessionId;
	}

	async function refresh(withStatus: boolean = true): Promise<void>
	{
		const sessionId = testRunStore.tracedSessionId;
		if (sessionId === null)
		{
			stopWatch();

			return;
		}

		if (isRefreshing || document.hidden)
		{
			return;
		}

		const generation = watchGeneration;
		isRefreshing = true;
		let hasUnreadTraces = false;

		try
		{
			const isStatusContextCurrent = (): boolean => (
				isWatchAlive(generation)
				&& testRunStore.activeRun?.sessionId === sessionId
			);

			if (withStatus && testRunStore.activeRun !== null && isStatusContextCurrent())
			{
				await testRunStore.loadStatus(isStatusContextCurrent);
			}

			const currentSessionId = testRunStore.tracedSessionId;
			if (currentSessionId !== null && isWatchAlive(generation))
			{
				hasUnreadTraces = await loadTraces(currentSessionId, generation);
			}
		}
		finally
		{
			isRefreshing = false;
		}

		if (generation === watchGeneration && testRunStore.activeRun === null && !hasUnreadTraces)
		{
			stopWatch();
		}
	}

	function startWatch(): void
	{
		if (watchIntervalId !== null || testRunStore.tracedSessionId === null)
		{
			return;
		}

		void refresh(false);
		watchIntervalId = setInterval(refresh, DEBUG_BAR_CONFIG.REFRESH_INTERVAL);
	}

	return { startWatch, stopWatch };
}
