import { CHROME_TOP } from '../../constants';
import { useLaneResize } from '../../model/use-lane-resize';

import { type Block } from '../../../../shared/types';

import './lane-resize-handle.css';

type Setup = {
	startResize: (event: MouseEvent, pool: Block, boundaryIndex: number) => void,
};

/**
 * The grab strip of one inner boundary of a pool, and the line of where that boundary is heading.
 *
 * The strip is hidden from the screen reader: there is no keyboard way to the same change, and a
 * control that announces itself while answering the pointer alone promises what it cannot do. What
 * the gesture leaves behind is spoken instead, by the feature that writes it.
 */
// @vue/component
export const PoolLaneResizeHandle = {
	name: 'BizprocdesignerPoolLaneResizeHandle',
	props: {
		/** @type Block */
		pool: {
			type: Object,
			required: true,
		},
		/** The lane the boundary stands above: from 1 to the number of lanes minus one. */
		boundaryIndex: {
			type: Number,
			required: true,
		},
		/** Model pixels from the top of the body of the pool - the heights of the lanes above. */
		offsetTop: {
			type: Number,
			required: true,
		},
		/** Model y of the future boundary while this one is dragged, and null the rest of the time. */
		previewY: {
			type: Number,
			default: null,
		},
	},
	setup(): Setup
	{
		const { startResize } = useLaneResize();

		return { startResize };
	},
	computed: {
		// The boundary is named by the lane below it: the lane it belongs to keeps its id through a
		// rename and through the insert of a neighbour, while the number of the place does not.
		laneId(): string
		{
			return this.pool.node?.poolLanes?.[this.boundaryIndex]?.id ?? '';
		},
		handleStyle(): { [string]: string }
		{
			return { top: `${this.offsetTop}px` };
		},
		// The layer of the handles starts at the top of the body, and the handle itself at its own
		// offset: the line is placed against the handle, so both are taken off the model point.
		indicatorStyle(): ?{ [string]: string }
		{
			if (this.previewY === null)
			{
				return null;
			}

			const bodyTop = this.pool.position.y + CHROME_TOP;

			return { top: `${this.previewY - bodyTop - this.offsetTop}px` };
		},
	},
	methods: {
		handleMouseDown(event: MouseEvent): void
		{
			this.startResize(event, this.pool, this.boundaryIndex);
		},
	},
	template: `
		<div
			class="editor-chart-pool-lane-resize-handle"
			:style="handleStyle"
			:data-testid="$testId('bizprocdesigner-pool-lane-resize-handle', pool.id, laneId)"
			aria-hidden="true"
			@mousedown="handleMouseDown"
		>
			<div
				v-if="indicatorStyle"
				class="editor-chart-pool-lane-resize-handle__line"
				:style="indicatorStyle"
			></div>
		</div>
	`,
};
