import { Loc } from 'main.core';
import { Groupable, ResizableBlock } from 'ui.block-diagram';
import { type MenuItemOptions } from 'ui.vue3.components.menu';

import {
	BlockContainer,
	BLOCK_LAYOUT_SLOT_NAMES,
	FRAME_BG_COLORS,
	FRAME_BORDER_COLORS,
	FRAME_COLOR_NAMES,
	PoolLane,
	type PoolLaneTitleEditService,
	poolLaneTitleEditServices,
} from '../../../../entities/blocks';
import {
	DeleteBlockIconBtn,
	EditNodeTitle,
	UpdatePublishedStatusLabel,
} from '../../../../features/blocks';
import {
	LANE_HIGHLIGHT_DURATION,
	PoolLaneResizeHandle,
	canEditPoolLanes,
	laneHeights,
	minPoolHeight,
	useLaneDropTarget,
	useLaneHighlight,
	useLaneResize,
	usePoolLanes,
} from '../../../../features/pool-lanes';
import { BlockLayoutWidget } from '../block-layout/block-layout';

import { type Block } from '../../../../shared/types';

import { BlockMediator } from '../../lib';

import './block-pool.css';

type Props = {
	block: Block,
};

type Setup = {
	blockLayoutSlotNames: { [string]: string },
	blockMediator: BlockMediator,
	backgroundColor: string,
	borderColor: string,
	minWidth: number,
	highlightedLane: ?{ blockId: string, laneId: string },
	dropLaneHighlight: (blockId: string) => void,
	dropTargetLane: ?{ blockId: string, laneId: string, index: number },
	renameLane: (pool: Block, laneIndex: number, title: string) => Promise<void>,
	previewY: ?number,
	resizedBoundary: ?{ blockId: string, boundaryIndex: number },
};

type LaneBoundary = {
	index: number,
	offsetTop: number,
};

// One grey surface for every pool: unlike the backdrop, a pool offers no colour palette of its own.
const POOL_BACKGROUND_COLOR = FRAME_BG_COLORS[FRAME_COLOR_NAMES.GREY];
const POOL_BORDER_COLOR = FRAME_BORDER_COLORS[FRAME_COLOR_NAMES.GREY];

// The floor of the resize across: kept above the 200px min-width of the block container, or a pool
// dragged narrower would keep rendering at 200px while the model holds the smaller width. The floor
// of the height depends on the number of lanes and belongs to the pool-lanes feature.
const POOL_MIN_WIDTH = 352;

const TITLE_ARIA_LABEL_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_TITLE_ARIA_LABEL';

// @vue/component
export const BlockPool = {
	name: 'BlockPool',
	components: {
		Groupable,
		ResizableBlock,
		BlockContainer,
		BlockLayoutWidget,
		DeleteBlockIconBtn,
		EditNodeTitle,
		PoolLane,
		PoolLaneResizeHandle,
		UpdatePublishedStatusLabel,
	},
	props: {
		/** @type Block */
		block: {
			type: Object,
			required: true,
		},
	},
	setup(props: Props): Setup
	{
		const { highlightedLane, dropLaneHighlight } = useLaneHighlight();
		const { dropTargetLane } = useLaneDropTarget();
		const { renameLane } = usePoolLanes();
		const { previewY, resizedBoundary } = useLaneResize();

		return {
			blockLayoutSlotNames: BLOCK_LAYOUT_SLOT_NAMES,
			blockMediator: new BlockMediator(),
			backgroundColor: POOL_BACKGROUND_COLOR,
			borderColor: POOL_BORDER_COLOR,
			minWidth: POOL_MIN_WIDTH,
			highlightedLane,
			dropLaneHighlight,
			dropTargetLane,
			renameLane,
			previewY,
			resizedBoundary,
		};
	},
	computed: {
		contextMenuItems(): Array<MenuItemOptions>
		{
			return this.blockMediator.getPoolBlockMenuOptions(this.block);
		},
		// a phrase that failed to load comes back as null, and the title prop takes a string
		titleAriaLabel(): string
		{
			return Loc.getMessage(TITLE_ARIA_LABEL_MESSAGE_ID) ?? '';
		},
		// a pool saved before the lanes existed comes back without them
		poolLanes(): Array<Object>
		{
			return this.block.node?.poolLanes ?? [];
		},
		// one menu per lane, addressed by its place in the pool: a lane knows where it sits, a pool
		// does not know which of its lanes was clicked
		laneMenuItems(): Array<Array<MenuItemOptions>>
		{
			return this.poolLanes.map((lane, index) => {
				return this.blockMediator.getPoolLaneMenuOptions(this.block, index);
			});
		},
		// The heights the lanes are drawn by, reconciled with the height of the block: a height saved
		// before a resize of the pool is not the picture on the screen.
		laneHeights(): Array<number>
		{
			return laneHeights(this.block);
		},
		/**
		 * The inner boundaries, each with the heights of the lanes above it: one less than the lanes,
		 * since the bottom edge of the last one is the edge of the pool itself.
		 */
		laneBoundaries(): Array<LaneBoundary>
		{
			let offsetTop = 0;

			return this.laneHeights.slice(0, -1).map((height, index) => {
				offsetTop += height;

				return { index: index + 1, offsetTop };
			});
		},
		// The rule itself is asked, not the items of the menu: those empty out for reasons of their
		// own - at the ceiling of the lanes the items that add are simply not offered.
		canResizeLanes(): boolean
		{
			return canEditPoolLanes();
		},
		// read by the resize gesture as it starts, so a pool that gained a lane cannot be squeezed
		// down to the floor of the pool it used to be
		minHeight(): number
		{
			return minPoolHeight(this.poolLanes.length);
		},
		// One mark lives at a time, and it belongs to the pool that got the lane, not to every pool.
		highlightedLaneId(): ?string
		{
			return this.highlightedLane?.blockId === this.block.id ? this.highlightedLane.laneId : null;
		},
		// One drag at a time, and the lane it aims at belongs to one pool.
		dropTargetLaneId(): ?string
		{
			return this.dropTargetLane?.blockId === this.block.id ? this.dropTargetLane.laneId : null;
		},
	},
	watch: {
		// A lane that leaves the pool - an undone insert, above all - takes the component off the scene
		// while the pool itself stays, so the record of its mode is dropped here: `beforeUnmount` of the
		// pool reaches only the lanes it still holds at that moment.
		poolLanes(lanes: Array<Object>, previous: Array<Object>): void
		{
			const kept = new Set(lanes.map((lane) => lane.id));

			previous.forEach((lane) => {
				if (!kept.has(lane.id))
				{
					poolLaneTitleEditServices.delete(this.block.id, lane.id);
				}
			});
		},
	},
	beforeUnmount(): void
	{
		this.dropLaneHighlight(this.block.id);
		this.poolLanes.forEach((lane) => poolLaneTitleEditServices.delete(this.block.id, lane.id));
	},
	methods: {
		/**
		 * Every lane but the last is drawn by its own number, and the last one stretches.
		 *
		 * The service zones of a pool are stated as constants while its header is drawn by its content,
		 * so a title in two lines raises the real top zone above `CHROME_TOP`. Numbers on every lane
		 * would then push the content past the bottom edge; the stretching last lane takes the actual
		 * remainder instead - the same rule by which the model leaves the difference to it.
		 */
		laneStyle(index: number): { [string]: string }
		{
			const isLast = index === this.laneHeights.length - 1;
			const box = isLast
				? { flex: '1 1 auto' }
				: { flex: '0 0 auto', height: `${this.laneHeights[index]}px` }
			;

			return {
				// The duration of the mark is owned by the feature; the stylesheet of the lane reads it here.
				'--editor-chart-pool-lane-highlight-duration': `${LANE_HIGHLIGHT_DURATION}ms`,
				...box,
			};
		},
		// One line at a time on the canvas, and it belongs to the boundary being dragged: every other
		// handle is given nothing to draw.
		boundaryPreviewY(boundaryIndex: number): ?number
		{
			const isResized = this.resizedBoundary?.blockId === this.block.id
				&& this.resizedBoundary.boundaryIndex === boundaryIndex;

			return isResized ? this.previewY : null;
		},
		// The mode is held outside the lane: the caption of the lane and a menu item switch the same one.
		laneEditService(laneId: string): PoolLaneTitleEditService
		{
			return poolLaneTitleEditServices.get(this.block.id, laneId);
		},
		isLaneEditing(laneId: string): boolean
		{
			return this.laneEditService(laneId).isEdit.value;
		},
		// The name of a lane is edited by a double click on it, so the ban cannot be left to the
		// context menu the lock already trims.
		onLaneEditRequest(laneId: string): void
		{
			if (!canEditPoolLanes() || !this.poolLanes.some((lane) => lane.id === laneId))
			{
				return;
			}

			this.laneEditService(laneId).startEdit();
		},
		async onLaneConfirm(laneId: string, title: string): Promise<void>
		{
			const index = this.poolLanes.findIndex((lane) => lane.id === laneId);
			if (index === -1)
			{
				return;
			}

			this.laneEditService(laneId).confirm();

			await this.renameLane(this.block, index, title);
		},
	},
	template: `
		<Groupable :block="block">
			<ResizableBlock
				:block="block"
				:minWidth="minWidth"
				:minHeight="minHeight"
			>
				<template #default="{ isHighlighted, isResize, isDragged, isDisabled }">
					<BlockContainer
						class="editor-chart-block-pool"
						:data-testid="$testId('bizprocdesigner-block-pool', block.id)"
						:highlighted="(isHighlighted || isResize) && !isDragged"
						:disabled="isDisabled"
						:backgroundColor="backgroundColor"
						:borderColor="borderColor"
						:contextMenuItems="contextMenuItems"
						@mouseup="blockMediator.handleMouseUp($event, block)"
						@mousedown="blockMediator.handleMouseDown($event)"
					>
						<BlockLayoutWidget
							:block="block"
							:moreMenuItems="contextMenuItems"
							:dragged="isDragged"
							:resized="isResize"
							:disabled="isDisabled"
						>
							<template #[blockLayoutSlotNames.TOP_MENU]>
								<DeleteBlockIconBtn
									:blockId="block.id"
									:disabled="isDisabled"
								/>
							</template>

							<template #[blockLayoutSlotNames.HEADER]>
								<EditNodeTitle
									:block="block"
									:ariaLabel="titleAriaLabel"
								/>
							</template>

							<template #[blockLayoutSlotNames.DEFAULT]>
								<PoolLane
									v-for="(lane, index) in poolLanes"
									:key="lane.id"
									:blockId="block.id"
									:lane="lane"
									:index="index"
									:menuItems="laneMenuItems[index]"
									:highlighted="lane.id === highlightedLaneId"
									:dropTarget="lane.id === dropTargetLaneId"
									:editing="isLaneEditing(lane.id)"
									:style="laneStyle(index)"
									@editRequest="onLaneEditRequest(lane.id)"
									@confirm="onLaneConfirm(lane.id, $event)"
									@cancel="laneEditService(lane.id).cancel()"
								/>
								<div
									v-if="canResizeLanes"
									class="editor-chart-block-pool__lane-handles"
								>
									<PoolLaneResizeHandle
										v-for="boundary in laneBoundaries"
										:key="boundary.index"
										:pool="block"
										:boundaryIndex="boundary.index"
										:offsetTop="boundary.offsetTop"
										:previewY="boundaryPreviewY(boundary.index)"
									/>
								</div>
							</template>

							<template #[blockLayoutSlotNames.STATUS]>
								<UpdatePublishedStatusLabel :block="block"/>
							</template>
						</BlockLayoutWidget>
					</BlockContainer>
				</template>
			</ResizableBlock>
		</Groupable>
	`,
};
