import { Loc, Type } from 'main.core';
import { computed, ref, type ComputedRef, type Ref } from 'ui.vue3';

import { editorAPI, type EditorUser } from '../api';

export type EditorUserMap = { [userId: string]: EditorUser };

/**
 * The employees the editor has already asked the portal about. The markers of the notes and the
 * preview of one speak of the same people, so the answer is kept here once and read by both. The map
 * is of the module, so it lives as long as the page: one page mounts one editor, and another template
 * is opened by loading the page anew.
 *
 * Asking is what is remembered, not answering: the markers of a schema are redrawn on every move of
 * the camera, and an employee already asked about is not asked about again by any of them.
 */
const users: Ref<EditorUserMap> = ref({});
const asked: Set<number> = new Set();

/**
 * Asked about and left without an answer - a request that failed, an employee the provider says
 * nothing about. They stay unasked until the list of the notes is read anew: a face missing for the
 * whole session is what an answer that never came used to cost, and asking on every redraw is what
 * the memory of the asking exists to avoid.
 */
const unanswered: Set<number> = new Set();

async function ensureUsers(userIds: number[]): Promise<void>
{
	const unknown = [...new Set(userIds)].filter((userId: mixed) => (
		Type.isNumber(userId) && userId > 0 && !asked.has(userId)
	));

	if (unknown.length === 0)
	{
		return;
	}

	unknown.forEach((userId: number) => asked.add(userId));

	try
	{
		const loaded = await editorAPI.fetchUsers(unknown);

		users.value = { ...users.value, ...loaded };

		unknown
			.filter((userId: number) => !Object.hasOwn(loaded, String(userId)))
			.forEach((userId: number) => unanswered.add(userId))
		;
	}
	catch (error)
	{
		unknown.forEach((userId: number) => unanswered.add(userId));

		throw error;
	}
}

/**
 * Gives the employees nobody answered about another chance: the list of the notes has been read
 * anew, and with it the schema has as much of a new state as this map ever gets.
 */
export function forgetUnansweredEditorUsers(): void
{
	unanswered.forEach((userId: number) => asked.delete(userId));
	unanswered.clear();
}

/**
 * Forgets everyone met so far, and nothing but the tests calls it: a new run of the editor is a page
 * loaded anew, and the map of such a page is empty to begin with. The tests, which share the module
 * between cases, are the only ones needing it emptied by hand.
 */
export function resetEditorUsers(): void
{
	users.value = {};
	asked.clear();
	unanswered.clear();
}

export function useEditorUsers(): {
	users: Ref<EditorUserMap>,
	ensureUsers: (userIds: number[]) => Promise<void>,
	}
{
	return { users, ensureUsers };
}

/**
 * Whoever is signed in, from the same map. The photo beside a field being written in is theirs, and
 * it is read the way the photo of any other employee is: a portal that says nothing about them
 * leaves the field working and the silhouette in place of a face.
 */
export function useCurrentEditorUser(): {
	currentUserId: number,
	currentUser: ComputedRef<EditorUser | null>,
	loadCurrentUser: () => Promise<void>,
	}
{
	const userId = Number.parseInt(Loc.getMessage('USER_ID'), 10);
	const currentUserId = Number.isNaN(userId) ? 0 : userId;

	const currentUser = computed((): EditorUser | null => users.value[String(currentUserId)] ?? null);

	const loadCurrentUser = async (): Promise<void> => {
		if (currentUserId === 0)
		{
			return;
		}

		try
		{
			await ensureUsers([currentUserId]);
		}
		catch
		{
			// A note is written with or without the photo of the one writing it.
		}
	};

	return { currentUserId, currentUser, loadCurrentUser };
}
