import { Loc } from 'main.core';
import { LiveAnnouncer } from 'ui.a11y';
import { toValue } from 'ui.vue3';

import { getFallbackInsertPoint } from './get-fallback-insert-point.ts';

/**
 * Adds a node of the catalog to the canvas without a drag. The keyboard stays in the catalog, so the
 * node is announced instead of being pointed at: what moved is the camera and the scheme, not the
 * focus.
 *
 * `afterBlockAdded` is the place for whatever the drop of a node does to the block once the canvas
 * holds it: it runs before the block is saved, so both ways of adding a node save the same thing.
 */
export function useAddCatalogNode(options)
{
	const {
		diagramStore,
		blockDiagram,
		canvas,
		highlightedBlocks,
		afterBlockAdded = () => {},
	} = options;
	const { isDisabledBlockDiagram, addBlock } = blockDiagram;

	// The same admission the insertion of a fragment asks for: the state of the canvas as a whole and
	// not the ban on writing alone.
	function canAdd()
	{
		return !toValue(isDisabledBlockDiagram) && diagramStore.isWriteLocked !== true;
	}

	/**
	 * The history step is not taken here: `ADD_BLOCK` is one of the hooks the canvas makes a snapshot
	 * by, and the wrapper of the canvas does not redefine that set - a snapshot taken here would be
	 * the second one, and undoing a single insertion would take two presses.
	 */
	function addCatalogNode(block)
	{
		if (!canAdd())
		{
			return false;
		}

		// The declaration of a container travels with the drag and stops at the canvas, which strips it
		// at the drop (`onDrop` in ui.block-diagram): the model keeps no such field, and the draft is
		// saved from the block as it stands here.
		const { isBackdrop, ...blockToAdd } = block;
		const addedBlock = { ...blockToAdd, position: getFallbackInsertPoint(diagramStore.blocks ?? []) };

		addBlock(addedBlock);
		afterBlockAdded(addedBlock);
		// The side effect of a node dropped on the canvas: the mark of the edit and an immediate save
		// instead of the deferred one.
		void diagramStore.updateBlockPublishStatus(addedBlock);
		highlightedBlocks.replace([addedBlock.id]);
		canvas.goToBlock(addedBlock);
		LiveAnnouncer.announce(
			Loc.getMessage('BIZPROCDESIGNER_EDITOR_CATALOG_NODE_ADDED_ARIA', {
				'#TITLE#': addedBlock.node?.title ?? '',
			}) ?? '',
			'polite',
		);

		return true;
	}

	return { addCatalogNode };
}
