import { computed, onMounted, onUnmounted, ref, watch, type ComputedRef, type Ref } from 'ui.vue3';
import { MessageBox } from 'ui.dialogs.messagebox';
import { Loc } from 'main.core';
import { DebugBarActiveRun } from '../debug-bar-active-run/debug-bar-active-run';
import { DebugBarLayout } from '../debug-bar-layout/debug-bar-layout';
import { useDebugSessions, useDebugTraces, DebugSessionsList } from '../../../../features/debug-bar';
import { useTestRunStore } from '../../../test-run';
import { DEBUG_BAR_LABELS } from '../../constants';
import { type DebugTraceSchema } from '../../types';

import '../debug-bar-variables.css';
import './style.css';

type PanelSessionState = {
	selectedSessionId: Ref<number | null>;
	isFirstLoad: Ref<boolean>;
	traces: Ref<DebugTraceSchema[]>;
	hasMoreTraces: Ref<boolean>;
	loadTraces: (sessionId: number) => Promise<void>;
	loadSessions: () => Promise<void>;
};

type WatchedRunSession = {
	watchedSessionId: ComputedRef<number | null>;
	shownTraces: ComputedRef<DebugTraceSchema[]>;
	hasMoreShownTraces: ComputedRef<boolean>;
};

// While a test run is active, the panel shows its session with the traces already read by the run watch.
function useWatchedRunSession(panel: PanelSessionState): WatchedRunSession
{
	const { selectedSessionId, isFirstLoad, traces, hasMoreTraces, loadTraces, loadSessions } = panel;
	const testRunStore = useTestRunStore();
	const watchedSessionId = computed((): number | null => testRunStore.activeRun?.sessionId ?? null);

	watch(watchedSessionId, (sessionId: number | null, previousSessionId: number | null): void => {
		if (sessionId !== null)
		{
			isFirstLoad.value = false;
			selectedSessionId.value = sessionId;

			return;
		}

		// the run has ended and its traces left the store, so the panel reads the journal itself
		if (selectedSessionId.value === previousSessionId)
		{
			void loadTraces(previousSessionId);
		}
	}, { immediate: true });

	watch(watchedSessionId, (sessionId: number | null): void => {
		if (sessionId !== null)
		{
			void loadSessions();
		}
	});

	const isWatchedSessionShown = computed((): boolean => {
		return watchedSessionId.value !== null && selectedSessionId.value === watchedSessionId.value;
	});

	return {
		watchedSessionId,
		shownTraces: computed(() => (isWatchedSessionShown.value ? testRunStore.traces : traces.value)),
		hasMoreShownTraces: computed(() => !isWatchedSessionShown.value && hasMoreTraces.value),
	};
}

export const DebugBarPanel = {
	name: 'DebugBarPanel',
	components: {
		DebugBarActiveRun,
		DebugBarLayout,
		DebugSessionsList,
	},
	emits: ['close'],
	setup(props, { emit })
	{
		const { sessions, loadSessions, deleteAllSessions } = useDebugSessions();
		const {
			traces,
			isLoadingTraces,
			isLoadingMoreTraces,
			hasMoreTraces,
			loadTraces,
			loadMoreTraces,
			clearTraces,
		} = useDebugTraces();
		const selectedSessionId = ref(null);
		const isFirstLoad = ref(true);
		const isMaximized = ref(false);
		const runSession = useWatchedRunSession({
			selectedSessionId, isFirstLoad, traces, hasMoreTraces, loadTraces, loadSessions,
		});

		function selectSession(sessionId: number): void
		{
			if (selectedSessionId.value === sessionId)
			{
				selectedSessionId.value = null;
				clearTraces();
			}
			else
			{
				selectedSessionId.value = sessionId;
				if (sessionId !== runSession.watchedSessionId.value)
				{
					loadTraces(sessionId);
				}
			}
		}

		async function loadSessionsWithAutoExpand(): Promise<void>
		{
			await loadSessions();

			if (isFirstLoad.value && sessions.value.length > 0)
			{
				isFirstLoad.value = false;
				// the list is kept oldest first, so the newest session is the last of it
				const latestSession = sessions.value.at(-1);
				selectedSessionId.value = latestSession.id;
				await loadTraces(latestSession.id);
			}
		}

		function closePanel(): void
		{
			emit('close');
		}

		function handleMaximize(): void
		{
			isMaximized.value = !isMaximized.value;
		}

		async function handleClear(): Promise<void>
		{
			MessageBox.confirm(
				Loc.getMessage(DEBUG_BAR_LABELS.CLEAR_CONFIRM_MESSAGE),
				Loc.getMessage(DEBUG_BAR_LABELS.CLEAR_CONFIRM_TITLE),
				async (messageBox) => {
					messageBox.close();

					const success = await deleteAllSessions();

					if (success)
					{
						clearTraces();
						selectedSessionId.value = null;
						await loadSessions();
					}
				},
				Loc.getMessage(DEBUG_BAR_LABELS.CLEAR_BUTTON),
				(messageBox) => {
					messageBox.close();
				},
				Loc.getMessage(DEBUG_BAR_LABELS.CANCEL_BUTTON),
			);
		}

		let refreshInterval = null;

		onMounted(() => {
			loadSessionsWithAutoExpand();

			refreshInterval = setInterval(() => {
				loadSessions();
			}, 5000);
		});

		onUnmounted(() => {
			if (refreshInterval)
			{
				clearInterval(refreshInterval);
			}
		});

		return {
			sessions,
			selectedSessionId,
			traces: runSession.shownTraces,
			isLoadingTraces,
			isLoadingMoreTraces,
			hasMoreTraces: runSession.hasMoreShownTraces,
			isMaximized,
			selectSession,
			loadMoreTraces,
			closePanel,
			handleMaximize,
			handleClear,
		};
	},
	template: `
		<DebugBarLayout
			:is-maximized="isMaximized"
			@close="closePanel"
			@maximize="handleMaximize"
			@clear="handleClear"
		>
			<DebugBarActiveRun/>
			<DebugSessionsList
				:sessions="sessions"
				:selected-session-id="selectedSessionId"
				:traces="traces"
				:is-loading-traces="isLoadingTraces"
				:has-more-traces="hasMoreTraces"
				:is-loading-more-traces="isLoadingMoreTraces"
				@select-session="selectSession"
				@load-more-traces="loadMoreTraces"
			/>
		</DebugBarLayout>
	`,
};
