import { useLoc, type GetMessage } from '../../../../shared/composables';
import { type CatalogMenuGroup } from '../../types';

import './catalog-group-list.css';

const CATALOG_GROUP_LIST_CLASS_NAMES = {
	base: 'editor-chart-catalog-group-list',
	withoutScroll: '--withoutScroll',
};

// @vue/component
export const CatalogGroupList = {
	name: 'CatalogGroupList',
	props: {
		/** @type Array<CatalogMenuGroup> */
		groups: {
			type: Array,
			default: () => ([]),
		},
		/** @type CatalogMenuGroup | null */
		currentGroup: {
			type: Object,
			default: null,
		},
	},
	setup(): { getMessage: GetMessage }
	{
		return useLoc();
	},
	computed: {
		catalogGroupListClassNames(): { [string]: boolean }
		{
			return {
				[CATALOG_GROUP_LIST_CLASS_NAMES.base]: true,
				[CATALOG_GROUP_LIST_CLASS_NAMES.withoutScroll]: this.currentGroup !== null,
			};
		},
	},
	methods: {
		// An open group covers the list with an opaque panel of its own, so the groups under it are
		// taken out of the focus order and out of the screen reader. Its own row stays live: the
		// content of the open group is drawn inside it, and its header is what tells the screen
		// reader the group is expanded and takes the press that collapses it again.
		isGroupCovered(group: CatalogMenuGroup): boolean
		{
			return this.currentGroup !== null && this.currentGroup.id !== group.id;
		},
	},
	template: `
		<ul
			:class="catalogGroupListClassNames"
			data-catalog-level="groups"
			role="group"
			:aria-label="getMessage('BIZPROCDESIGNER_EDITOR_CATALOG_GROUPS_ARIA')"
		>
			<li
				v-for="group in groups"
				:key="group.id"
				:inert="isGroupCovered(group)"
				class="editor-chart-catalog-group-list__group"
			>
				<slot
					:group="group"
					name="group"
				/>
			</li>
		</ul>
	`,
};
