import { Dom, Loc } from 'main.core';
import { TagSelector, type Item } from 'ui.entity-selector';
import { markRaw } from 'ui.vue3';

import {
	type TestRunDocument,
	type TestRunDocumentPayload,
	type TestRunDocumentSource,
	type TestRunField,
} from '../../../entities/test-run';
import { TEST_RUN_ERROR_ID, TestRunForm } from './test-run-form';

const SOURCE_CREATE: TestRunDocumentSource = 'create';
const SOURCE_SELECT: TestRunDocumentSource = 'select';
const SOURCE_NONE: TestRunDocumentSource = 'none';
const SELECTOR_CONTEXT = 'bizprocdesigner-test-run-document';
const TITLE_ID = 'bizprocdesigner-test-run-document-title';
const SELECT_WARNING_ID = 'bizprocdesigner-test-run-document-select-warning';

export const DOCUMENT_FIELD_SCOPE = 'document-';

function isSelectAvailable(runDocument: TestRunDocument): boolean
{
	return runDocument.canSelect && Boolean(runDocument.selector?.entityId);
}

function initialSource(runDocument: TestRunDocument): TestRunDocumentSource
{
	if (runDocument.source !== SOURCE_SELECT || isSelectAvailable(runDocument))
	{
		return runDocument.source;
	}

	return runDocument.canCreate ? SOURCE_CREATE : SOURCE_NONE;
}

// @vue/component
export const DocumentSourceControl = {
	name: 'DocumentSourceControl',
	components: { TestRunForm },
	props: {
		document: {
			type: Object,
			required: true,
		},
		documentType: {
			type: Array,
			required: true,
		},
		invalidFieldNames: {
			type: Array,
			default: (): string[] => [],
		},
		isSelectionInvalid: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['change', 'rendered'],
	data(): { source: TestRunDocumentSource, selector: TagSelector | null }
	{
		return {
			source: initialSource(this.document),
			selector: null,
		};
	},
	computed: {
		createFields(): TestRunField[]
		{
			return this.document.createFields ?? [];
		},
		selectorEntityId(): string
		{
			return this.document.selector?.entityId ?? '';
		},
		isShown(): boolean
		{
			return this.source !== SOURCE_NONE;
		},
		isSelectAvailable(): boolean
		{
			return isSelectAvailable(this.document);
		},
		hasChoice(): boolean
		{
			return this.document.canCreate && this.isSelectAvailable;
		},
		isCreate(): boolean
		{
			return this.source === SOURCE_CREATE;
		},
		isSelect(): boolean
		{
			return this.source === SOURCE_SELECT;
		},
		hasCreateFields(): boolean
		{
			return this.document.canCreate && this.createFields.length > 0;
		},
		selectorDescribedBy(): string
		{
			return this.isSelectionInvalid ? `${SELECT_WARNING_ID} ${TEST_RUN_ERROR_ID}` : SELECT_WARNING_ID;
		},
		sourceOptions(): Array<{ value: TestRunDocumentSource, title: string }>
		{
			return [
				{ value: SOURCE_CREATE, title: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_SOURCE_CREATE') },
				{ value: SOURCE_SELECT, title: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_SOURCE_SELECT') },
			];
		},
	},
	watch: {
		source(): void
		{
			this.$emit('change');
		},
		selectorDescribedBy(): void
		{
			this.describeAddButton();
		},
	},
	mounted(): void
	{
		if (this.isShown && this.isSelectAvailable)
		{
			this.selector = markRaw(this.createSelector());
			this.selector.renderTo(this.$refs.selector);
			this.describeAddButton();
		}
	},
	beforeUnmount(): void
	{
		this.selector?.getDialog()?.destroy();
	},
	methods: {
		loc(phraseCode: string): string
		{
			return Loc.getMessage(phraseCode) ?? '';
		},
		createSelector(): TagSelector
		{
			const emitChange = (): void => this.$emit('change');

			return new TagSelector({
				multiple: false,
				placeholder: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_TITLE'),
				dialogOptions: {
					context: SELECTOR_CONTEXT,
					entities: [{ id: this.selectorEntityId, dynamicLoad: true, dynamicSearch: true }],
					events: {
						'Item:onSelect': emitChange,
						'Item:onDeselect': emitChange,
					},
				},
			});
		},
		describeAddButton(): void
		{
			Dom.attr(this.selector?.getAddButtonLink(), {
				'aria-invalid': this.isSelectionInvalid ? 'true' : null,
				'aria-describedby': this.selectorDescribedBy,
			});
		},
		selectDocument(documentId: string): boolean
		{
			if (!this.selector)
			{
				return false;
			}

			this.source = SOURCE_SELECT;
			this.selector.getDialog().addItem({
				id: documentId,
				entityId: this.selectorEntityId,
				title: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_TITLE'),
				tabs: [],
				saveable: false,
			}).select(true);

			return true;
		},
		getSelector(): TagSelector | null
		{
			return this.selector;
		},
		getSelectedDocumentId(): string | number | null
		{
			const [item]: Item[] = this.selector?.getDialog().getSelectedItems() ?? [];

			return item ? item.getId() : null;
		},
		collectDocument(): TestRunDocumentPayload | null
		{
			if (this.isCreate)
			{
				return { source: SOURCE_CREATE, fields: this.$refs.createForm?.collectValues() ?? {} };
			}

			if (this.isSelect)
			{
				return { source: SOURCE_SELECT, documentId: this.getSelectedDocumentId() };
			}

			return null;
		},
		focusFirstInvalidField(): boolean
		{
			if (this.isSelect && this.isSelectionInvalid && this.selector)
			{
				this.selector.getAddButtonLink().focus();

				return true;
			}

			return this.isCreate && (this.$refs.createForm?.focusFirstInvalidField() ?? false);
		},
	},
	template: `
		<div
			v-if="isShown"
			class="bizprocdesigner-test-run__document"
			data-testid="bizprocdesigner-editor-test-run-document"
			role="group"
			aria-labelledby="${TITLE_ID}"
		>
			<div id="${TITLE_ID}" class="bizprocdesigner-test-run__title">
				{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_TITLE') }}
			</div>
			<div
				v-if="hasChoice"
				class="bizprocdesigner-test-run__document-sources"
				role="radiogroup"
				aria-labelledby="${TITLE_ID}"
			>
				<label
					v-for="option in sourceOptions"
					:key="option.value"
					class="bizprocdesigner-test-run__document-source"
				>
					<input
						v-model="source"
						type="radio"
						name="bizprocdesigner-test-run-document-source"
						:value="option.value"
						:data-testid="'bizprocdesigner-editor-test-run-document-source-' + option.value"
					>
					{{ option.title }}
				</label>
			</div>
			<div v-if="hasCreateFields" v-show="isCreate" data-testid="bizprocdesigner-editor-test-run-document-create">
				<TestRunForm
					ref="createForm"
					:fields="createFields"
					:document-type="documentType"
					:invalid-field-names="invalidFieldNames"
					scope="${DOCUMENT_FIELD_SCOPE}"
					collapses-optional-fields
					@change="$emit('change')"
					@rendered="$emit('rendered')"
				/>
			</div>
			<div
				v-if="isSelectAvailable"
				v-show="isSelect"
				class="bizprocdesigner-test-run__document-select"
				data-testid="bizprocdesigner-editor-test-run-document-select"
			>
				<div
					ref="selector"
					class="bizprocdesigner-test-run__document-selector"
					:class="{ '--invalid': isSelectionInvalid }"
					data-testid="bizprocdesigner-editor-test-run-document-selector"
					role="group"
					aria-labelledby="${TITLE_ID}"
				></div>
				<div id="${SELECT_WARNING_ID}" class="bizprocdesigner-test-run__description">
					{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_SELECT_WARNING') }}
				</div>
			</div>
		</div>
	`,
};
