import { toRaw } from 'ui.vue3';
import { defineStore } from 'ui.vue3.pinia';

import { type ApiError } from '../../../shared/api';
import { getErrorCode, getErrorCustomData, handleResponseError } from '../../../shared/utils';
import { diagramStore as useDiagramStore } from '../../blocks/stores/diagram';
import { DEBUG_BAR_CONFIG, DEBUG_TRACE_TYPES } from '../../debug-bar/constants';
import { type DebugTraceSchema } from '../../debug-bar/types';
import { testRunApi, TestRunErrorCode } from '../api';
import { TEST_RUN_NODE_STATES, type TestRunNodeState } from '../constants';
import { NodeStateDisplay, type NodeStateChange } from '../lib/node-state-display';
import { type ActiveRun, type RunForm, type StartedRun, type StartTestRunPayload } from '../types';

const NODE_STATE_BY_TRACE_KEY = Object.freeze({
	'CBPWorkflow::executeActivity': TEST_RUN_NODE_STATES.RUNNING,
	'CBPWorkflow::closeActivity': TEST_RUN_NODE_STATES.PASSED,
});

// The journal shows the tail of the run, four pages of the panel; node states are kept for the whole run.
const MAX_KEPT_TRACES = DEBUG_BAR_CONFIG.DEFAULT_TRACES_PAGE_SIZE * 4;

type TestRunState = {
	activeRun: ActiveRun | null;
	form: RunForm | null;
	isStarting: boolean;
	dialogBlockId: string | null;
	traces: DebugTraceSchema[];
	nodeStates: { [blockId: string]: TestRunNodeState };
	displayedNodeStates: { [blockId: string]: TestRunNodeState };
	startedSessionId: number | null;
	finishedSessionId: number | null;
	statusGeneration: number;
};

const DIALOG_HANDLED_CODES: string[] = Object.values(TestRunErrorCode);

/**
 * A refusal the dialog answers itself travels on to the caller; every other one is told by a toast and
 * the caller is left with nothing but an empty answer.
 */
function reportOrRethrow(error: ApiError): void
{
	if (DIALOG_HANDLED_CODES.includes(getErrorCode(error)))
	{
		throw error;
	}

	handleResponseError(error);
}

function nodeStateOf(trace: DebugTraceSchema): TestRunNodeState | null
{
	if (trace.type === DEBUG_TRACE_TYPES.ERROR)
	{
		return TEST_RUN_NODE_STATES.ERROR;
	}

	if (trace.type === DEBUG_TRACE_TYPES.LOG)
	{
		return NODE_STATE_BY_TRACE_KEY[trace.key] ?? null;
	}

	return null;
}

/**
 * An activity that reported an error closes normally right after, and a run of the node anew starts with
 * running: only a new run clears the error, its own close never does.
 */
function isKeptOverError(nodeState: TestRunNodeState, currentState: TestRunNodeState | void): boolean
{
	return currentState === TEST_RUN_NODE_STATES.ERROR && nodeState === TEST_RUN_NODE_STATES.PASSED;
}

const nodeStateDisplays: WeakMap<Object, NodeStateDisplay> = new WeakMap();

function nodeStateDisplayOf(store: Object, onChange: (states: Object) => void): NodeStateDisplay
{
	if (!nodeStateDisplays.has(store))
	{
		nodeStateDisplays.set(store, new NodeStateDisplay(onChange));
	}

	return nodeStateDisplays.get(store);
}

function currentTemplateId(): number
{
	return useDiagramStore().templateId;
}

/**
 * The root of the template and the inner nodes of a complex node run too, but have no block of their own
 * to mark: a slot of the animation queue spent on them plays nothing. A diagram not loaded yet marks
 * nothing anyway, so it keeps every change.
 */
function shownOnCanvas(changes: NodeStateChange[]): NodeStateChange[]
{
	const blockIds = new Set(useDiagramStore().blocks.map((block) => block.id));

	return blockIds.size === 0 ? changes : changes.filter(({ blockId }) => blockIds.has(blockId));
}

export const useTestRunStore = defineStore('bizprocdesigner-editor-test-run', {
	state: (): TestRunState => ({
		activeRun: null,
		form: null,
		isStarting: false,
		dialogBlockId: null,
		traces: [],
		nodeStates: {},
		displayedNodeStates: {},
		startedSessionId: null,
		finishedSessionId: null,
		statusGeneration: 0,
	}),
	getters: {
		isDialogOpen(state): boolean
		{
			return state.dialogBlockId !== null;
		},

		tracedSessionId(state): number | null
		{
			return state.activeRun?.sessionId ?? state.finishedSessionId;
		},
	},
	actions: {
		appendTraces(traces: DebugTraceSchema[]): void
		{
			const nodeStates = { ...this.nodeStates };
			const changes: NodeStateChange[] = [];
			traces.forEach((trace: DebugTraceSchema) => {
				const blockId = trace.context?.name ?? null;
				const nodeState = nodeStateOf(trace);
				if (blockId === null || nodeState === null || isKeptOverError(nodeState, nodeStates[blockId]))
				{
					return;
				}

				nodeStates[blockId] = nodeState;
				changes.push({ blockId, state: nodeState });
			});

			this.nodeStates = nodeStates;
			this.traces = [...this.traces, ...traces].slice(-MAX_KEPT_TRACES);

			const isStartedHere = this.startedSessionId !== null && this.tracedSessionId === this.startedSessionId;
			this.nodeStateDisplay().apply(shownOnCanvas(changes), isStartedHere);
		},

		clearTraces(): void
		{
			this.traces = [];
			this.nodeStates = {};
			this.nodeStateDisplay().reset();
		},

		nodeStateDisplay(): NodeStateDisplay
		{
			// installed into an app, pinia calls each action on a new proxy of the store
			return nodeStateDisplayOf(toRaw(this), (states) => {
				this.displayedNodeStates = states;
			});
		},

		settleNodeStateDisplay(): void
		{
			this.nodeStateDisplay().settle();
		},

		/**
		 * The one entrance to the dialog of the run: the menu item names the node here and the dialog
		 * mounts on this state. Neither side imports the other, so the item works before the dialog
		 * exists and stays untouched when it appears.
		 */
		openDialog(blockId: string): void
		{
			if (blockId === this.dialogBlockId)
			{
				return;
			}

			this.dialogBlockId = blockId;
			this.form = null;
		},

		closeDialog(): void
		{
			this.dialogBlockId = null;
			this.form = null;
		},

		/**
		 * Only the status requested last may apply, and only while its context is still current:
		 * a start or a finish in between makes the answer stale.
		 */
		async loadStatus(isContextCurrent: () => boolean = () => true): Promise<void>
		{
			this.statusGeneration += 1;
			const generation = this.statusGeneration;
			const templateId = currentTemplateId();
			const isCurrent = (): boolean => (
				generation === this.statusGeneration
				&& templateId === currentTemplateId()
				&& isContextCurrent()
			);

			if (templateId <= 0 || !isCurrent())
			{
				return;
			}

			try
			{
				const { activeRun } = await testRunApi.status({ templateId });
				if (!isCurrent())
				{
					return;
				}

				const previousSessionId = this.activeRun?.sessionId ?? null;
				const previousTracedSessionId = this.tracedSessionId;

				this.activeRun = activeRun ?? null;

				const sessionId = this.activeRun?.sessionId ?? null;
				if (sessionId === null)
				{
					this.finishedSessionId = previousSessionId ?? this.finishedSessionId;
				}
				else if (sessionId !== previousTracedSessionId)
				{
					this.finishedSessionId = null;
					this.clearTraces();
				}
			}
			catch (error)
			{
				if (isCurrent())
				{
					handleResponseError(error);
				}
			}
		},

		/**
		 * The form is kept only for the node the dialog is still open on: the answer for a node it has left
		 * goes to the caller alone.
		 */
		async prepare(blockId: string): Promise<RunForm | null>
		{
			try
			{
				const { form } = await testRunApi.prepare({ templateId: currentTemplateId(), blockId });
				if (blockId === this.dialogBlockId)
				{
					this.form = form;
				}

				return form;
			}
			catch (error)
			{
				if (blockId === this.dialogBlockId)
				{
					this.form = null;
				}

				reportOrRethrow(error);

				return null;
			}
		},

		async start(payload: StartTestRunPayload): Promise<StartedRun | null>
		{
			this.statusGeneration += 1;
			this.isStarting = true;

			try
			{
				const startedRun = await testRunApi.start({ templateId: currentTemplateId(), ...payload });
				this.startedSessionId = startedRun?.sessionId ?? null;
				// The summary of the run is owned by the server: the answer of the start carries neither
				// the node nor the time of it, and a reload of the editor reads exactly this.
				await this.loadStatus();

				const isOverByStart = this.activeRun === null && this.startedSessionId !== null;
				if (isOverByStart && this.finishedSessionId !== this.startedSessionId)
				{
					this.clearTraces();
					this.finishedSessionId = this.startedSessionId;
				}

				return startedRun;
			}
			catch (error)
			{
				this.showFailedStartSession(error);
				reportOrRethrow(error);

				return null;
			}
			finally
			{
				this.isStarting = false;
			}
		},

		/** A start that failed keeps the trace of its error in its session, traced like a run over by its start. */
		showFailedStartSession(error: ApiError): void
		{
			const sessionId = getErrorCustomData(error)?.sessionId;
			if (getErrorCode(error) !== TestRunErrorCode.startFailed || !Number.isInteger(sessionId) || sessionId <= 0)
			{
				return;
			}

			this.clearTraces();
			this.startedSessionId = sessionId;
			this.finishedSessionId = sessionId;
		},

		async finish(expectedSessionId: number): Promise<boolean>
		{
			if (this.activeRun === null || this.activeRun.sessionId !== expectedSessionId)
			{
				return false;
			}

			this.statusGeneration += 1;

			try
			{
				await testRunApi.finish({ sessionId: expectedSessionId });
				this.statusGeneration += 1;
				if (this.activeRun?.sessionId === expectedSessionId)
				{
					this.activeRun = null;
					this.finishedSessionId = null;
					this.clearTraces();
				}

				return true;
			}
			catch (error)
			{
				handleResponseError(error);

				return false;
			}
		},
	},
});
