import { Dom } from 'main.core';
import { type BaseEvent } from 'main.core.events';
import { TagSelector, type TagItem } from 'ui.entity-selector';
import { markRaw } from 'ui.vue3';

const USER_ENTITY_ID = 'user';
const SELECTOR_CONTEXT = 'bizprocdesigner-test-run-user';

function getTagUserId(event: BaseEvent): number
{
	const { tag }: { tag: TagItem } = event.getData();

	return Number(tag.getId());
}

// @vue/component
export const TestRunUserField = {
	name: 'TestRunUserField',
	props: {
		/** @type TestRunField */
		field: {
			type: Object,
			required: true,
		},
		labelId: {
			type: String,
			default: '',
		},
		invalid: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['change'],
	data(): { selector: TagSelector | null, userIds: number[] }
	{
		return {
			selector: null,
			userIds: [],
		};
	},
	computed: {
		isMultiple(): boolean
		{
			return this.field.property.Multiple === true;
		},
		inputName(): string
		{
			return this.isMultiple ? `${this.field.name}[]` : this.field.name;
		},
	},
	watch: {
		invalid(): void
		{
			this.describeAddButton();
		},
	},
	mounted(): void
	{
		this.selector = markRaw(new TagSelector({
			multiple: this.isMultiple,
			dialogOptions: {
				context: SELECTOR_CONTEXT,
				entities: [{ id: USER_ENTITY_ID, options: { intranetUsersOnly: true } }],
			},
			events: {
				onTagAdd: (event: BaseEvent): void => {
					this.userIds = [...this.userIds, getTagUserId(event)];
					this.$emit('change');
				},
				onTagRemove: (event: BaseEvent): void => {
					const userId = getTagUserId(event);
					this.userIds = this.userIds.filter((id: number): boolean => id !== userId);
					this.$emit('change');
				},
			},
		}));
		this.selector.renderTo(this.$refs.selector);
		this.describeAddButton();
	},
	beforeUnmount(): void
	{
		this.selector?.getDialog()?.destroy();
	},
	methods: {
		describeAddButton(): void
		{
			Dom.attr(this.selector?.getAddButtonLink(), {
				'aria-labelledby': this.labelId || null,
				'aria-invalid': this.invalid ? 'true' : null,
			});
		},
	},
	template: `
		<div>
			<div ref="selector"></div>
			<input
				v-for="userId in userIds"
				:key="userId"
				type="hidden"
				:name="inputName"
				:value="'user_' + userId"
			>
		</div>
	`,
};
