import { Text2Xs } from 'ui.system.typography.vue';
import { Avatar } from 'ui.vue3.components.avatar';
import { defineComponent } from 'ui.vue3';

import { PIN_SIZE, PIN_TIP_X, PIN_TIP_Y } from '../../../../entities/notes';
import { useLoc } from '../../../../shared/composables';

import './note-marker.css';

const AVATAR_SIZE = 28;
const MARKER_TEST_ID = 'bizprocdesigner-note-marker';
const COUNT_TEST_ID = 'bizprocdesigner-note-marker-count';

/**
 * The geometry of the pin belongs to the note and not to the marker of one: the draft of a note being
 * written draws the same pin (note-composer). Whatever stands beside a marker keeps reading the box
 * from here rather than knowing the shape of a pin.
 */
export const MARKER_TIP_X = PIN_TIP_X;
export const MARKER_TIP_Y = PIN_TIP_Y;
export const MARKER_SIZE = PIN_SIZE;

/**
 * The marker of one note on the schema: a control of its own, so the keyboard reaches it in order,
 * sees where it is and opens the thread from it.
 */
export const NoteMarker = defineComponent({
	name: 'BizprocdesignerNoteMarker',
	components: { Avatar, Text2Xs },
	props: {
		note: {
			/** @type TemplateNote */
			type: Object,
			required: true,
		},
		author: {
			/** @type EditorUser */
			type: Object,
			default: null,
		},
		// somebody wrote into this note while it was closed here, and it has not been opened since
		hasUnseen: {
			type: Boolean,
			default: false,
		},
		x: {
			type: Number,
			required: true,
		},
		y: {
			type: Number,
			required: true,
		},
		isOpened: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['toggle', 'preview-start', 'preview-end'],
	setup(): Object
	{
		const { getMessage } = useLoc();

		return {
			getMessage,
		};
	},
	computed: {
		// A translation rather than left/top: the camera moves every marker of the layer at once, and a
		// translated marker costs the layer no reflow.
		markerStyle(): { transform: string }
		{
			return { transform: `translate(${this.x - MARKER_TIP_X}px, ${this.y - MARKER_TIP_Y}px)` };
		},
		messageCount(): string
		{
			return String(this.note.messageCount);
		},
		// The count says a note is a conversation and not a single remark, so one message shows none.
		hasReplies(): boolean
		{
			return this.note.messageCount > 1;
		},
		/**
		 * The face of the author: the photo, the initials of the name where there is no photo, and the
		 * faceless avatar of the design system where the portal said nothing about the employee at all
		 * - a hidden one, one from the extranet. The same three cases everywhere a note draws a face,
		 * and all three are drawn by the avatar itself.
		 */
		avatarOptions(): { size: number, title: string, picPath: string | null }
		{
			return {
				size: AVATAR_SIZE,
				title: this.author?.name ?? '',
				picPath: this.author?.avatarUrl ?? null,
			};
		},
		// The avatar is redrawn by its own class and not by Vue, so a photo that arrived later needs
		// the component built anew.
		avatarKey(): string
		{
			return `${this.note.authorId}:${this.author?.name ?? ''}:${this.author?.avatarUrl ?? ''}`;
		},
		countClasses(): { [string]: boolean }
		{
			return { '--unseen': this.hasUnseen };
		},
		/**
		 * The count belongs to the name as well: read out, the marker has to say how much of a
		 * discussion it stands for and not just that it is a note. What is unread is told by the same
		 * name (WCAG 1.4.1): on the screen it is the colour of the counter alone, and a colour is
		 * nothing a name carries by itself.
		 */
		accessibleName(): string
		{
			const messageId = this.hasUnseen
				? 'BIZPROCDESIGNER_EDITOR_NOTE_MARKER_ARIA_LABEL_UNSEEN'
				: 'BIZPROCDESIGNER_EDITOR_NOTE_MARKER_ARIA_LABEL'
			;

			return this.getMessage(messageId, { '#COUNT#': this.messageCount });
		},
		markerTestId(): string
		{
			return this.$testId(MARKER_TEST_ID, String(this.note.id));
		},
		// The count is asserted on its own: how much of a discussion a marker stands for is what a
		// reply and a deletion change about it, and the name of the marker holds the same number.
		countTestId(): string
		{
			return this.$testId(COUNT_TEST_ID, String(this.note.id));
		},
	},
	methods: {
		handleClick(): void
		{
			this.$emit('toggle');
		},
		/**
		 * The marker only says that the pointer came and went. How long it has to stay before the note
		 * is previewed, and which note is previewed at all, belongs to the layer: one card stands at a
		 * time, and a marker knows nothing of its neighbours.
		 */
		handlePointerEnter(): void
		{
			this.$emit('preview-start');
		},
		handlePointerLeave(): void
		{
			this.$emit('preview-end');
		},
	},
	template: `
		<button
			type="button"
			class="editor-chart-note-marker"
			:class="{ '--opened': isOpened }"
			:style="markerStyle"
			:aria-label="accessibleName"
			:aria-expanded="isOpened"
			aria-haspopup="dialog"
			:data-testid="markerTestId"
			@click="handleClick"
			@mouseenter="handlePointerEnter"
			@mouseleave="handlePointerLeave"
		>
			<span class="editor-chart-note-marker__pin">
				<Avatar
					:key="avatarKey"
					class="editor-chart-note-marker__photo"
					:options="avatarOptions"
				/>
				<Text2Xs
					v-if="hasReplies"
					class="editor-chart-note-marker__count"
					:class="countClasses"
					:data-testid="countTestId"
				>{{ messageCount }}</Text2Xs>
			</span>
		</button>
	`,
});
