import { ajax, Type } from 'main.core';

import { type BrokenLinkFormField } from './broken-link-field';

/**
 * Keys the legacy dialog prints for itself and not for the activity
 * (bizproc_activity_settings.php:192-208). The template of the process weighs the most of them: it
 * carries the expressions of every activity at once, so left among the fields it would come out the
 * owner of every reference there is.
 */
const SERVICE_FIELD_NAMES = new Set([
	'arWorkflowTemplate',
	'arWorkflowParameters',
	'arWorkflowVariables',
	'arWorkflowConstants',
	'sessid',
	'activity',
	'document_type',
	'id',
	'current_site_id',
	'activated',
]);

/**
 * Fields of the dialog an approach has nowhere to lead to: the title of the node is edited by the
 * panel and its row is hidden away, and the comment of the editor belongs to the panel as well.
 * A reference written in them ends at the card, not at a row nobody can see.
 */
const NON_ADDRESSABLE_FIELD_NAMES = new Set(['title', 'activity_editor_comment']);

/**
 * The control of a field code inside a form, matching both the scalar `name` and the Multiple
 * `name[]` shape. The single lookup of a field in the settings form: the autofill helpers, the
 * required-field UI of the action form and the readers below all go through it.
 */
export function locateField(form: ?HTMLFormElement, fieldCode: string): HTMLElement | null
{
	if (!form || !Type.isStringFilled(fieldCode))
	{
		return null;
	}

	const escaped = CSS.escape(fieldCode);

	return form.querySelector(`[name="${escaped}"]`)
		?? form.querySelector(`[name="${escaped}[]"]`)
		?? null;
}

/**
 * The outermost table row the control stands on within this form. The control of a field is wrapped
 * in tables of its own renderer, while the caption the person reads stands on the row of the dialog
 * table - the outermost of them. An activity that lays its fields out without table rows gets null:
 * there is no row to lead to.
 */
export function findOutermostFormRow(control: ?HTMLElement, form: ?HTMLElement): HTMLElement | null
{
	if (!control || !form)
	{
		return null;
	}

	let row = control.closest('tr');
	let outermostRow = null;
	while (row && form.contains(row))
	{
		outermostRow = row;
		row = row.parentElement?.closest('tr');
	}

	return outermostRow;
}

/**
 * The caption of a field: the first cell of its row. The colon the markup prints after the name is
 * not part of the name - the caption is read out loud when the approach reaches the field.
 */
function readRowCaption(row: HTMLElement): string
{
	const caption = row.cells?.[0]?.textContent ?? '';

	return caption.trim().replace(/:$/, '').trim();
}

/**
 * The fields of a form that came as ready HTML, as the panel reads them (TPL-01, ALG-03): the name
 * of the control, its value and the caption the person reads next to it. The values are taken with
 * the very snapshot the form is later submitted with, so what the references are looked for in is
 * what the server will receive.
 *
 * The fields keep the order of the form. A key of the dialog itself and a key there is no leading to
 * are left out, and so is a control whose form draws no row for it - every field that comes back
 * carries the row it was found on, which the readers of the form would otherwise look up a second time.
 *
 * `keepNonAddressableFields` keeps the title of the node and the comment of the editor in the set:
 * a panel drawing those two as rows of its own does have a place to lead a reference written in
 * them to. A form of a construction leaves the option alone.
 */
export function collectLegacyFormFields(
	form: ?HTMLFormElement,
	options: { keepNonAddressableFields?: boolean } = {},
): Array<BrokenLinkFormField>
{
	if (!form)
	{
		return [];
	}

	const data = ajax.prepareForm(form).data;
	if (!Type.isPlainObject(data))
	{
		return [];
	}

	const skipNonAddressable = options.keepNonAddressableFields !== true;
	const fields = [];
	for (const [name, value] of Object.entries(data))
	{
		if (SERVICE_FIELD_NAMES.has(name) || (skipNonAddressable && NON_ADDRESSABLE_FIELD_NAMES.has(name)))
		{
			continue;
		}

		const row = findOutermostFormRow(locateField(form, name), form);
		if (!row)
		{
			continue;
		}

		fields.push({ name, value, title: readRowCaption(row), row });
	}

	return fields;
}
