/**
 * The surface a thread of a note is drawn on: a dialog pinned to the marker of its note and
 * held whole inside the drawn area of the canvas (AC-014). The popup lives beside the markers, in the
 * same layer and the same coordinates, so the camera that moves a marker moves the popup with it.
 *
 * It knows nothing of the notes: what it is given is a point to open at and an area to stay within,
 * and what it gives back is the wish to be closed. The conversation itself belongs to `note-thread`,
 * and so does whatever stands in the head beside the closing: it arrives through the slots.
 *
 * Its styles live in `note-thread.css` together with the ones of the thread: the two are one control
 * split by what each of them is responsible for, and not two controls.
 */

import { Button as UiButton, AirButtonStyle, ButtonSize } from 'ui.vue3.components.button';
import { Outline } from 'ui.icon-set.api.vue';
import { Type } from 'main.core';
import { useCanvasFocus } from 'ui.block-diagram';
import { defineComponent, getCurrentInstance, nextTick } from 'ui.vue3';

import { PIN_SIZE, PIN_TIP_X, PIN_TIP_Y } from '../../../../entities/notes';

/** A point of the screen, counted from the corner of the drawn area of the canvas. */
export type ThreadPoint = {
	x: number,
	y: number,
};

export type ThreadBox = {
	width: number,
	height: number,
};

/** Where a window of a note stands beside its pin, and on which side of it. */
export type NoteWindowPlacement = {
	x: number,
	y: number,
	isFlippedX: boolean,
};

const ESCAPE_KEY = 'Escape';

/**
 * The focus of the canvas, and only once the canvas itself has built its state: whoever asks for it
 * first is who creates it, and asking ahead of the canvas would leave it with a state built without
 * its own options. A card standing without a canvas hands the focus to nobody.
 */
function useCanvasFocusIfBuilt(): { focusCanvas: () => boolean } | null
{
	const app = getCurrentInstance()?.appContext?.app;

	if (!app?.config?.globalProperties?.$blockDiagram)
	{
		return null;
	}

	return useCanvasFocus();
}

/**
 * Whatever held the focus when the card went up, and only if that was an element at all: a thread
 * opened by something other than a click on a marker - a link into the template, the pull of another
 * user - leaves the page itself holding the focus, and the page is nobody to give it back to.
 */
function readFocusedElement(): HTMLElement | null
{
	const active = document.activeElement;

	return Type.isDomNode(active) && active !== document.body ? active : null;
}

/** The gap between the pin of a note and whatever window stands beside it: the pin stays readable. */
export const ANCHOR_GAP = 12;

/** How close to the edge of the canvas a window of a note is allowed to stand. */
export const VIEWPORT_MARGIN = 8;

/**
 * The stretch of one axis a box of the given size may start at without leaving the drawn area. A box
 * larger than the area is left at the near edge of it: seeing the start of it is what is left.
 */
export function clampOnAxis(start: number, size: number, viewport: number): number
{
	const limit = Math.max(VIEWPORT_MARGIN, viewport - VIEWPORT_MARGIN - size);

	return Math.round(Math.min(Math.max(start, VIEWPORT_MARGIN), limit));
}

/**
 * Where a window of a note - the thread, the preview, the form of a draft - opens beside its pin.
 *
 * Always to the side of the pin and never under it: to the right while the whole of the window fits
 * there, to the left otherwise. A window over or below the pin would cover the very place of the
 * schema it speaks of.
 *
 * Up and down it is the band at the top of the window - the head of a card, the line of a field -
 * that stands level with the pin, so the two read as one object. The edge of the canvas is the only
 * thing that moves the window off that line, and then it moves it as little as it takes to keep the
 * window whole.
 */
export function resolveNoteWindowPlacement(
	anchor: ThreadPoint,
	size: ThreadBox,
	viewport: ThreadBox,
	headHeight: number,
): NoteWindowPlacement
{
	const pinLeft = anchor.x - PIN_TIP_X;
	const pinTop = anchor.y - PIN_TIP_Y;
	const forward = pinLeft + PIN_SIZE + ANCHOR_GAP;
	const backward = pinLeft - ANCHOR_GAP - size.width;
	const fitsForward = (forward + size.width) <= (viewport.width - VIEWPORT_MARGIN);
	const fitsBackward = backward >= VIEWPORT_MARGIN;
	const isFlippedX = !fitsForward && fitsBackward;

	return {
		x: clampOnAxis(isFlippedX ? backward : forward, size.width, viewport.width),
		y: clampOnAxis(pinTop + ((PIN_SIZE - headHeight) / 2), size.height, viewport.height),
		isFlippedX,
	};
}

/**
 * Whether the marker of the note still stands within the drawn area. A thread whose marker was moved
 * out of it by the camera has nothing left to be pinned to and is closed rather than left hanging
 * over the schema on its own (AC-014a).
 */
export function isAnchorVisible(anchor: ThreadPoint, viewport: ThreadBox): boolean
{
	return anchor.x >= 0
		&& anchor.x <= viewport.width
		&& anchor.y >= 0
		&& anchor.y <= viewport.height
	;
}

export const NoteThreadPopup = defineComponent({
	name: 'BizprocdesignerNoteThreadPopup',
	components: { UiButton },
	props: {
		// the point of the marker the thread was opened from, in the coordinates of the canvas layer
		anchorX: {
			type: Number,
			required: true,
		},
		anchorY: {
			type: Number,
			required: true,
		},
		viewportWidth: {
			type: Number,
			required: true,
		},
		viewportHeight: {
			type: Number,
			required: true,
		},
		ariaLabel: {
			type: String,
			default: '',
		},
		// the accessible name of the closing, which carries an icon and no text to be named by
		closeLabel: {
			type: String,
			default: '',
		},
		testId: {
			type: String,
			default: '',
		},
		closeTestId: {
			type: String,
			default: '',
		},
	},
	emits: ['close'],
	setup(): Object
	{
		return {
			buttonSize: ButtonSize.SMALL,
			closeButtonStyle: AirButtonStyle.PLAIN_NO_ACCENT,
			closeIcon: Outline.CROSS_M,
			canvasFocus: useCanvasFocusIfBuilt(),
		};
	},
	data(): Object
	{
		return {
			width: 0,
			height: 0,
			// the head stands level with the pin, so its height is a part of the placement
			headHeight: 0,
			// The side is chosen by the size of the popup, and the size is only known once it is in the
			// document. It is therefore drawn once without being shown, and never in the wrong place.
			isMeasured: false,
		};
	},
	computed: {
		placement(): NoteWindowPlacement
		{
			return resolveNoteWindowPlacement(
				{ x: this.anchorX, y: this.anchorY },
				{ width: this.width, height: this.height },
				{ width: this.viewportWidth, height: this.viewportHeight },
				this.headHeight,
			);
		},
		// A translation rather than left/top, as the markers of the layer above the same canvas.
		popupStyle(): { transform: string, visibility?: string }
		{
			const style = { transform: `translate(${this.placement.x}px, ${this.placement.y}px)` };

			return this.isMeasured ? style : { ...style, visibility: 'hidden' };
		},
		// The dataset key is lower-case on purpose: `testid` renders as data-testid, the attribute
		// page.getByTestId() looks for, while a camel-cased `testId` would render data-test-id.
		closeButtonDataset(): { testid: string }
		{
			return { testid: this.closeTestId };
		},
	},
	created(): void
	{
		// Off data() on purpose: neither the observer nor the element that had the focus is rendered,
		// and a reactive proxy over a DOM node would be the only thing this component adds to it.
		this.sizeObserver = null;
		this.opener = null;
	},
	mounted(): void
	{
		this.opener = readFocusedElement();
		this.nameCloseButton();
		this.measure();
		this.observeSize();
		void this.focusPopup();
	},
	beforeUnmount(): void
	{
		this.sizeObserver?.disconnect();
		this.sizeObserver = null;
		this.restoreFocus();
	},
	methods: {
		/**
		 * The dialog takes the focus in, so the keyboard reaches the conversation and the field of the
		 * reply by going on from here instead of walking through the rest of the markers first.
		 *
		 * The side of the popup is only known once it has been measured, so until then it stands
		 * hidden - and a hidden element takes no focus. The wait is for that hiding to be lifted.
		 */
		async focusPopup(): Promise<void>
		{
			await nextTick();

			this.$refs.popup?.focus({ preventScroll: true });
		},
		/**
		 * The size the popup takes with the conversation it holds. It changes with the thread itself -
		 * a message arrives, an edit opens a field - and every change may turn the popup to the other
		 * side of its marker.
		 */
		measure(): void
		{
			const popup = this.$refs.popup ?? null;
			if (popup === null)
			{
				return;
			}

			const box = popup.getBoundingClientRect();
			if (box.width !== this.width || box.height !== this.height)
			{
				this.width = box.width;
				this.height = box.height;
			}

			const head = this.$refs.head?.getBoundingClientRect().height ?? 0;
			if (head !== this.headHeight)
			{
				this.headHeight = head;
			}

			this.isMeasured = true;
		},
		observeSize(): void
		{
			if (!Type.isFunction(ResizeObserver) || !Type.isDomNode(this.$refs.popup))
			{
				return;
			}

			this.sizeObserver = new ResizeObserver(() => this.measure());
			this.sizeObserver.observe(this.$refs.popup);
		},
		/** The card takes the focus itself while what held it inside is leaving the document. */
		focusSelf(): void
		{
			this.$refs.popup?.focus({ preventScroll: true });
		},
		/**
		 * The focus goes back to whatever opened the thread - its marker - and only when it is leaving
		 * the popup along with it. A thread closed by opening another one has already handed the focus
		 * to the marker of that one.
		 *
		 * A note that is gone - completed, or left without its last message - has no marker to go back
		 * to, and the focus would stay on the page itself (WCAG 2.4.3). The canvas takes it then: that
		 * is where the editor keeps the focus whenever a tool of it closes.
		 */
		restoreFocus(): void
		{
			const active = document.activeElement;
			const isFocusInside = this.$refs.popup?.contains(active) === true;

			if (isFocusInside && this.opener !== null && document.contains(this.opener))
			{
				this.opener.focus({ preventScroll: true });
			}
			else if (isFocusInside || active === null || active === document.body)
			{
				this.canvasFocus?.focusCanvas();
			}

			this.opener = null;
			void this.ensureFocusKept();
		},
		/**
		 * The marker the focus was just handed to may be leaving the document in the same round as
		 * the card itself - a discussion that is over takes the note and its marker away together -
		 * and the focus would fall to the page once that round is done. Where it ended up is only
		 * known after it, and the canvas takes what nothing else kept (WCAG 2.4.3).
		 */
		async ensureFocusKept(): Promise<void>
		{
			await nextTick();

			const active = document.activeElement;

			if (active === null || active === document.body)
			{
				this.canvasFocus?.focusCanvas();
			}
		},
		/**
		 * UiButton builds its native button imperatively, so an attribute bound in the template never
		 * reaches it: the placeholder it is bound to leaves the document as soon as the real button is
		 * in it. An icon-only button has no text to be named by, so the name is written onto the
		 * element itself, the way the menu button of this editor does it.
		 */
		nameCloseButton(): void
		{
			this.$refs.close?.button?.setProps({ 'aria-label': this.closeLabel });
		},
		/**
		 * The keys of the thread stop at the thread: Escape closes it instead of leaving the mode of
		 * the notes, and the shortcuts of the canvas do not fire over a message being written.
		 */
		handleKeydown(event: KeyboardEvent): void
		{
			if (event.key === ESCAPE_KEY)
			{
				this.$emit('close');
			}
		},
	},
	template: `
		<div
			class="editor-chart-note-thread"
			:style="popupStyle"
			ref="popup"
			role="dialog"
			tabindex="-1"
			:aria-label="ariaLabel"
			:data-testid="testId"
			@keydown.stop="handleKeydown"
		>
			<div class="editor-chart-note-thread__head" ref="head">
				<slot name="head"/>
				<div class="editor-chart-note-thread__actions">
					<slot name="actions"/>
					<UiButton
						ref="close"
						:leftIcon="closeIcon"
						:size="buttonSize"
						:style="closeButtonStyle"
						:dataset="closeButtonDataset"
						@click="$emit('close')"
					/>
				</div>
			</div>
			<slot/>
		</div>
	`,
});
