import { Dom } from 'main.core';
import { hint } from 'ui.vue3.directives.hint';
import { markRaw } from 'ui.vue3';
import { useBlockDiagram } from 'ui.block-diagram';

import './block-header.css';

const BLOCK_HEADER_CLASS_NAMES = {
	base: 'editor-chart-block-header',
	deactivated: '--deactivated',
};

// @vue/component
export const BlockHeader = {
	name: 'block-header',
	directives: {
		hint,
	},
	setup(): Object
	{
		const { zoom, transformX, transformY } = useBlockDiagram();

		return {
			zoom,
			transformX,
			transformY,
		};
	},
	props: {
		block: {
			type: Object,
			required: true,
		},
		subIconExternal: {
			type: Boolean,
			default: false,
		},
		title: {
			type: String,
			default: '',
		},
		deactivated: {
			type: Boolean,
			default: false,
		},
	},
	data(): Object
	{
		return {
			isTitleOverflowing: false,
			resizeObserver: null,
			popupInstance: null,
		};
	},
	computed: {
		displayTitle(): string
		{
			return this.title || this.block.node?.title || '';
		},
		hintOptions(): Object
		{
			return {
				text: this.displayTitle,
				popupOptions: {
					offsetTop: 10,
					width: 340,
					background: 'var(--ui-color-accent-soft-element-blue)',
					className: 'editor-chart-tooltip-content',
					events: {
						onShow: (event) => {
							this.popupInstance = markRaw(event.getTarget());
							this.adjustPopupScale();
						},
						onClose: () => {
							this.popupInstance = null;
						},
					},
				},
			};
		},
		blockHeaderClassNames(): { [string]: boolean }
		{
			return {
				[BLOCK_HEADER_CLASS_NAMES.base]: true,
				[BLOCK_HEADER_CLASS_NAMES.deactivated]: this.deactivated,
			};
		},
		shouldShowTooltip(): boolean
		{
			return this.isTitleOverflowing;
		},
	},
	watch: {
		zoom: 'closePopup',
		transformX: 'closePopup',
		transformY: 'closePopup',
		displayTitle(): void
		{
			this.$nextTick(() => this.updateTitleOverflow());
		},
	},
	mounted(): void
	{
		this.updateTitleOverflow();

		if (typeof ResizeObserver === 'function')
		{
			this.resizeObserver = new ResizeObserver(() => this.updateTitleOverflow());
			this.resizeObserver.observe(this.$refs.title);
		}
	},
	updated(): void
	{
		this.updateTitleOverflow();
	},
	beforeUnmount(): void
	{
		this.closePopup();
		this.resizeObserver?.disconnect();
		this.resizeObserver = null;
	},
	methods: {
		adjustPopupScale(): void
		{
			const container = this.popupInstance?.getPopupContainer();
			if (!container || !this.zoom)
			{
				return;
			}

			Dom.style(container, 'transformOrigin', 'center bottom');
			Dom.style(container, 'transform', `scale(${this.zoom})`);
		},
		closePopup(): void
		{
			this.popupInstance?.close();
			this.popupInstance = null;
		},
		updateTitleOverflow(): void
		{
			const titleElement = this.$refs.title;
			if (!titleElement)
			{
				return;
			}

			const isHorizontallyOverflowing = titleElement.scrollWidth - titleElement.clientWidth > 1;
			const isVerticallyOverflowing = titleElement.scrollHeight - titleElement.clientHeight > 1;
			const isTitleOverflowing = isHorizontallyOverflowing || isVerticallyOverflowing;
			if (isTitleOverflowing !== this.isTitleOverflowing)
			{
				this.isTitleOverflowing = isTitleOverflowing;
			}
		},
	},
	template: `
		<div :class="blockHeaderClassNames">
			<div class="editor-chart-block-header__icon-wrapper">
				<slot name="icon"/>
			</div>

			<template v-if="$slots.subIcon">
				<span class="editor-chart-block-header__divider" aria-hidden="true"></span>
				<div :class="[
					  'editor-chart-block-header__icon-wrapper',
					  'editor-chart-block-header__icon-wrapper--sub',
					  { 'editor-chart-block-header__icon-wrapper--sub-external': subIconExternal }
					]">
					<slot name="subIcon"/>
				</div>
			</template>

			<div class="editor-chart-block-header__text">
				<p
					class="editor-chart-block-header__title"
					ref="title"
				>
					<span v-if="shouldShowTooltip" v-hint="hintOptions">{{ displayTitle }}</span>
					<span v-else>{{ displayTitle }}</span>
				</p>
				<div v-if="$slots.status" class="editor-chart-block-header__status">
					<slot name="status"/>
				</div>
			</div>
		</div>
	`,
};
