import { BIcon } from 'ui.icon-set.api.vue';

import './empty-state-icon.css';

// The icon frame of the mockup, 170x170
const ICON_SIZE = 170;
// The same frame as the mockup draws it inside a settings panel, where the icon shares the room
// with the text of the state.
export const EMPTY_STATE_ICON_PANEL_SIZE = 140;
const ICON_COLOR = 'var(--designer-bp-empty-state-icon-gradient)';

/**
 * The gradient-filled icon that opens every empty state of the editor: the loading skeleton,
 * the missing template and the rest. The icon itself is chosen by the state, the fill is not.
 *
 * The fill is handed down through CSS variables, so the contract is wider than the two props.
 * Defaults for all four are in design-tokens.css:
 *  - `--designer-bp-empty-state-icon-from` / `-to` - the two ends of the shared gradient;
 *  - `--designer-bp-empty-state-icon-strength` - how much of them is mixed into the surface;
 *  - `--designer-bp-empty-state-icon-surface` - what they are mixed with, the canvas by default.
 * A state on a surface of its own - a white panel, a washed plate - MUST override the surface on
 * its container, otherwise the icon is tinted for the canvas and lies a tone off what it is on.
 */
// @vue/component
export const EmptyStateIcon = {
	name: 'EmptyStateIcon',
	components: {
		BIcon,
	},
	props: {
		name: {
			type: String,
			required: true,
		},
		size: {
			type: Number,
			default: ICON_SIZE,
		},
	},
	setup(): Object
	{
		return {
			ICON_COLOR,
		};
	},
	template: `
		<BIcon
			class="bizprocdesigner-empty-state-icon"
			:name="name"
			:size="size"
			:color="ICON_COLOR"
			aria-hidden="true"
		/>
	`,
};
