import { Runtime } from 'main.core';
import { FeatureCode } from 'bizprocdesigner.feature';
import { useFeature } from '../composables/feature';

/**
 * The lazy loader of the field framework of `bizproc`, one per page. Answers with the namespace the
 * extension resolves to - `FieldManager`, `FieldRegistry`, `RenderMode`, `EventName` - or with `null`
 * when the feature is off, when the load broke and when the answer carried no framework.
 *
 * The extension is named by a string and never imported: an import would put `bizproc.fields` into
 * the `rel` of the built config of the editor, and the framework would arrive on every page load
 * while the feature is off.
 *
 * A refusal is remembered the way the catalog of system values remembers one (`system-values-cache`):
 * `Runtime.loadExtension` keeps the rejected promise of an extension until the page is reloaded and
 * repeats the request on its own while that still makes sense, so a refusal that reached us is final
 * and asking again would only break again, without a request.
 */

const FIELDS_EXTENSION = 'bizproc.fields';

let framework = null;
let hasFailed = false;
let pendingLoad = null;

export async function ensureFieldsFramework()
{
	if (!useFeature().isFeatureAvailable(FeatureCode.fieldsFramework))
	{
		return null;
	}

	if (framework !== null)
	{
		return framework;
	}

	if (hasFailed)
	{
		return null;
	}

	if (pendingLoad === null)
	{
		pendingLoad = Runtime.loadExtension(FIELDS_EXTENSION)
			.then((exports) => {
				if (!isFrameworkNamespace(exports))
				{
					hasFailed = true;
					console.error(
						`fieldsFramework: the ${FIELDS_EXTENSION} extension answered without the exports of the framework`,
						exports,
					);

					return null;
				}

				framework = exports;

				return exports;
			})
			.catch((error) => {
				hasFailed = true;
				console.error(`fieldsFramework: failed to load the ${FIELDS_EXTENSION} extension`, error);

				return null;
			})
			.finally(() => {
				pendingLoad = null;
			})
		;
	}

	return pendingLoad;
}

/**
 * An answer of the server without the record of the extension is not rejected by the core: the promise
 * is resolved through the `window` namespace, and a stranger object without the exports of the
 * framework arrives here (`main.core`, `process-extensions.ts`). Such an answer is no framework - the
 * render slice reads `RenderMode`, `FieldManager` and `EventName` of it (`settings-controls-render`),
 * and its framework branch would break on them instead of falling back to the legacy render.
 */
function isFrameworkNamespace(exports)
{
	return Boolean(exports?.FieldManager && exports?.RenderMode && exports?.EventName);
}

/**
 * The framework for a caller that cannot wait for a load: `null` until some asynchronous caller has
 * brought it in. The feature is not asked here - nothing but the load above ever fills the state, and
 * it answers with the feature off.
 */
export function getLoadedFieldsFramework()
{
	return framework;
}

/**
 * Takes the page back to the state of a page where nothing has been loaded yet.
 *
 * The unit set of the editor is one page and one bundle, so a file that brings the framework in hands
 * it to every file after it - the form of a test run reads the loaded framework synchronously and asks
 * no flag - and a refusal remembered by one file answers for the rest. A file that needs either state
 * says so by taking the page back, before its own load and after it.
 */
export function resetFieldsFramework()
{
	framework = null;
	hasFailed = false;
	pendingLoad = null;
}
