import { Dom, Event } from 'main.core';

/**
 * Makes a part of the page read-only, including the controls that do not belong to this extension: the
 * legacy forms of the activities and the controls the server describes are rendered by other modules
 * and do not read any flag of the editor. What they show stays readable and scrollable, and nothing in
 * it reacts to a pointer or to an editing key; text fields become readonly, the rest of the form
 * controls disabled. Controls added later - a form rendered after the surface was locked, a row added
 * by the script of a form - are locked as they appear.
 */

export const READ_ONLY_SURFACE_CLASS = '--read-only-surface';

const TEXT_FIELD_SELECTOR = 'textarea, input:not([type]), input[type="text"], input[type="search"], input[type="number"], '
	+ 'input[type="email"], input[type="url"], input[type="tel"], input[type="password"], input[type="date"], '
	+ 'input[type="datetime-local"], input[type="time"]';
const OTHER_CONTROL_SELECTOR = 'select, button, input[type="checkbox"], input[type="radio"], input[type="file"], '
	+ 'input[type="button"], input[type="submit"], input[type="image"], input[type="reset"], input[type="range"], '
	+ 'input[type="color"]';

const POINTER_EVENTS = ['pointerdown', 'mousedown', 'mouseup', 'click', 'dblclick', 'contextmenu', 'dragstart', 'drop'];
const EDIT_EVENTS = ['beforeinput', 'paste', 'cut'];

// Keys that move around or read what is there: the rest either types or activates a control.
const NAVIGATION_KEYS = new Set([
	'Tab', 'Escape', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'PageUp', 'PageDown', 'Home', 'End',
	'Shift', 'Control', 'Alt', 'Meta',
]);
const READING_SHORTCUTS = new Set(['c', 'a']);

// Caught on the way down, before any control of the form sees the event.
const CAPTURE = { capture: true };

const releases = new WeakMap();

function refuse(event: Event): void
{
	event.preventDefault();
	event.stopPropagation();
}

function refuseEditingKey(event: KeyboardEvent): void
{
	const isReadingShortcut = (event.ctrlKey || event.metaKey) && READING_SHORTCUTS.has(event.key.toLowerCase());
	if (!NAVIGATION_KEYS.has(event.key) && !isReadingShortcut)
	{
		refuse(event);
	}
}

function lockControls(root: HTMLElement): void
{
	root.querySelectorAll(TEXT_FIELD_SELECTOR).forEach((field) => {
		Dom.attr(field, 'readonly', 'readonly');
	});
	root.querySelectorAll(OTHER_CONTROL_SELECTOR).forEach((control) => {
		Dom.attr(control, 'disabled', 'disabled');
	});
	root.querySelectorAll('[contenteditable]:not([contenteditable="false"])').forEach((element) => {
		Dom.attr(element, 'contenteditable', 'false');
	});
}

/**
 * Locks the surface and returns the release. Locking a surface already locked keeps the first lock;
 * the release does not give back the controls the lock touched: a surface is unlocked only when its
 * content is rendered anew, and a new render brings new controls.
 */
export function lockReadOnlySurface(surface: HTMLElement): () => void
{
	const existing = releases.get(surface);
	if (existing)
	{
		return existing;
	}

	lockControls(surface);
	const observer = new MutationObserver(() => lockControls(surface));
	observer.observe(surface, { childList: true, subtree: true });

	[...POINTER_EVENTS, ...EDIT_EVENTS].forEach((type) => Event.bind(surface, type, refuse, CAPTURE));
	Event.bind(surface, 'keydown', refuseEditingKey, CAPTURE);
	Dom.addClass(surface, READ_ONLY_SURFACE_CLASS);

	const release = (): void => {
		observer.disconnect();
		[...POINTER_EVENTS, ...EDIT_EVENTS].forEach((type) => Event.unbind(surface, type, refuse, CAPTURE));
		Event.unbind(surface, 'keydown', refuseEditingKey, CAPTURE);
		Dom.removeClass(surface, READ_ONLY_SURFACE_CLASS);
		releases.delete(surface);
	};
	releases.set(surface, release);

	return release;
}

export function releaseReadOnlySurface(surface: HTMLElement): void
{
	releases.get(surface)?.();
}
