import { PULL } from 'pull.client';
import type { Block, Connection } from '../../../shared/types';

// draftRevision is zero when the arrived draft is no longer the freshest one of the template:
// the server has nothing to confirm for it.
//
// name and description come only from the write that stored them, so a sender that wrote neither leaves
// both keys out. An absent field is not an empty one and the tab leaves what it shows alone.
type AiDraftPushData = {
	templateId: number,
	draftId: number,
	draftRevision: number,
	blocks: Array<Block>,
	connections: Array<Connection>,
	name?: string,
	description?: string,
};

export function initAiUpdatePull(callback: (params: {
	blocks: Array<Block>,
	connections: Array<Connection>,
	templateId: number,
	draftId: number,
	draftRevision: number,
	name?: string,
	description?: string,
}) => void): void
{
	PULL.subscribe({
		moduleId: 'bizprocdesigner',
		command: 'bizprocdesigner_ai_draft_updated',
		callback: async (pushData: AiDraftPushData): Promise<void> => {
			callback(pushData);
		},
	});
}
