import { Dom } from 'main.core';

import { parseSegments } from './expression-parser';

/**
 * The warning of the legacy dialog and the list it folds away
 * (`bizprocdesigner/admin/bizproc_activity_settings.php:263-284`). The dialog prints the list as one
 * text with line breaks in it and gives no id to a line, so the markup is all there is to read.
 */
const LEGACY_ALERT_ID = 'bp_act_set_broken_link';
const LEGACY_ALERT_LIST_ID = 'bp_act_set_broken_link_detail';

/**
 * A reference the legacy warning named, with the address of the place it leads to - the reference
 * itself, or nothing where there is no leading to. The shape the warnings take their items in
 * (BrokenLinksNoticeItem), read here, where the markup is.
 */
export type LegacyBrokenLinkItem = {
	link: string,
	target: ?string,
};

/**
 * The references of the list, one per line. Read off the nodes of the list and not off its text: the
 * lines are separated by `<br>`, which the text of the node runs together into a single line.
 */
function readAlertLinks(alert: HTMLElement): Array<string>
{
	const list = alert.querySelector(`#${LEGACY_ALERT_LIST_ID}`);
	if (!list)
	{
		return [];
	}

	const lines = [''];
	for (const node of list.childNodes)
	{
		if (node.nodeName === 'BR')
		{
			lines.push('');
		}
		else
		{
			lines[lines.length - 1] += node.textContent ?? '';
		}
	}

	return lines.map((line: string) => line.trim()).filter((line: string) => line !== '');
}

/**
 * The address of a line, as opaque to the reader as the one of a panel (TPL-02): the reference
 * itself, and nothing where there is no leading to. A broken node the analyzer reported as a ready
 * sentence names no field of the form and stays plain text.
 */
function resolveTarget(link: string): ?string
{
	return parseSegments(link).some((segment: Object) => segment.kind === 'ref') ? link : null;
}

/**
 * The references named by the warning the dialog sent, taken off it: the old warning goes away and
 * the one of the panel takes its place, where the very same references are pressable.
 *
 * The list is read out of this form alone - a panel holds several of them at once - and before the
 * removal, because the markup is the only source there is.
 */
export function takeLegacyBrokenLinkItems(form: ?HTMLElement): Array<LegacyBrokenLinkItem>
{
	const alert = form?.querySelector?.(`#${LEGACY_ALERT_ID}`);
	if (!alert)
	{
		return [];
	}

	const items = readAlertLinks(alert).map((link: string) => ({ link, target: resolveTarget(link) }));
	Dom.remove(alert);

	return items;
}
