import { ref, type Ref } from 'ui.vue3';

export class PoolLaneTitleEditService
{
	#isEdit: Ref<boolean> = ref(false);

	get isEdit(): Ref<boolean>
	{
		return this.#isEdit;
	}

	startEdit(): void
	{
		this.#isEdit.value = true;
	}

	confirm(): void
	{
		this.#isEdit.value = false;
	}

	cancel(): void
	{
		this.#isEdit.value = false;
	}
}

// The block belongs in the key: lane ids repeat from pool to pool by design, so a key made of the
// lane alone would open the field in every pool that happens to hold a lane with the same id.
function serviceKey(blockId: string, laneId: string): string
{
	return `${blockId}\u0000${laneId}`;
}

// Both ids come from the server, so they are data, not known names: on a plain object an id like
// `__proto__` or `constructor` would answer with an inherited value instead of a service, and `??=`
// would never create one.
const poolLaneTitleEditServicesMap: { [string]: PoolLaneTitleEditService } = Object.create(null);

export const poolLaneTitleEditServices = {
	get(blockId: string, laneId: string): PoolLaneTitleEditService
	{
		const key = serviceKey(blockId, laneId);
		poolLaneTitleEditServicesMap[key] ??= new PoolLaneTitleEditService();

		return poolLaneTitleEditServicesMap[key];
	},
	delete(blockId: string, laneId: string): void
	{
		delete poolLaneTitleEditServicesMap[serviceKey(blockId, laneId)];
	},
};
