import { Type } from 'main.core';
import { LiveAnnouncer, type AriaLivePoliteness } from 'ui.a11y';

function speak(message: string, politeness: AriaLivePoliteness): void
{
	if (!Type.isString(message) || message.trim() === '')
	{
		return;
	}

	LiveAnnouncer.announce(message, politeness);
}

/**
 * Everything the editor says goes through here, and it says it politely: the live region belongs to
 * `ui.a11y`, and the editor keeps none of its own.
 */
export function announce(message: string): void
{
	speak(message, 'polite');
}

// Interrupting the reader is the price of an error, and only of an error.
export function announceError(message: string): void
{
	speak(message, 'assertive');
}
