import { Loc } from 'main.core';
import { Outline } from 'ui.icon-set.api.vue';
import { Button } from 'ui.vue3.components.button';
import { ButtonSize, AirButtonStyle } from 'ui.buttons';

const ARIA_LABEL_MESSAGE = 'BIZPROCDESIGNER_EDITOR_TEXT_EDITOR_ATTACH_FILE_ARIA_LABEL';

// @vue/component
export const AttachButton = {
	name: 'AttachButton',
	components: {
		Button,
	},
	props: {
		fileService: {
			type: Object,
			required: true,
		},
	},
	setup(): Object
	{
		return {
			outlineIcons: Outline,
			buttonStyle: AirButtonStyle,
			buttonSize: ButtonSize,
		};
	},
	mounted(): void
	{
		// Button builds its native button imperatively, so an attribute bound in the template
		// never reaches it and the icon-only button would stay without an accessible name.
		// The menu keeps aria-expanded up to date once it opens, these values only seed the semantics.
		const attributes = {
			'aria-haspopup': 'menu',
			'aria-expanded': 'false',
		};

		const ariaLabel = Loc.getMessage(ARIA_LABEL_MESSAGE);
		if (ariaLabel)
		{
			attributes['aria-label'] = ariaLabel;
		}
		else
		{
			console.error(`AttachButton: the phrase ${ARIA_LABEL_MESSAGE} did not resolve, the button stays unnamed`);
		}

		this.$refs.attachButton?.button?.setProps(attributes);
	},
	methods: {
		onClick(): void
		{
			this.fileService.browse({
				bindElement: this.$refs.attachButton?.button?.button,
			});
		},
	},
	template: `
		<Button
			:leftIcon="outlineIcons.ATTACH"
			:style="buttonStyle.PLAIN"
			:size="buttonSize.SMALL"
			:dataset="{ testid: 'bizprocdesigner-text-editor-attach-button' }"
			ref="attachButton"
			@click="onClick"
		/>
	`,
};
