// The gap between the scheme and what lands next to it, plus the width standing for a node the canvas
// has not measured yet - the same default size the widget draws a selection box around.
const FALLBACK_INSERT_GAP = 200;
const DEFAULT_BLOCK_WIDTH = 150;

/**
 * Where an insertion nobody pointed at a place for lands: to the right of everything the scheme
 * already has, so it never falls on top of an existing node and there is nothing to ask about a free
 * place. One rule for both ways of putting a block on the canvas without the pointer - the insertion
 * of a fragment and the node added from the keyboard.
 *
 * @param {Array<Block>} blocksOnScheme Blocks the scheme holds now.
 * @returns {BlockPosition}
 */
export function getFallbackInsertPoint(blocksOnScheme)
{
	if (blocksOnScheme.length === 0)
	{
		return { x: 0, y: 0 };
	}

	const right = Math.max(...blocksOnScheme.map(
		(block) => block.position.x + (block.dimensions?.width ?? DEFAULT_BLOCK_WIDTH),
	));

	return {
		x: right + FALLBACK_INSERT_GAP,
		y: Math.min(...blocksOnScheme.map((block) => block.position.y)),
	};
}
