import { useLoc, type GetMessage } from '../../../../shared/composables';
import { BROKEN_LINKS_SCOPES, BrokenLinksNotice, type BrokenLinksNoticeItem } from '../../../../shared/ui';
import { takeLegacyBrokenLinkItems } from '../../../../shared/utils';

// The reader of the legacy markup lives in shared: the form of a simple node reads the very same
// warning, and an entity is not to know about a feature.
export { takeLegacyBrokenLinkItems };

/**
 * The base of the ids of this warning (DTO-01). Its own, apart from the base of the panel: the two
 * stand in one and the same panel at once, and a scenario tells them apart by nothing else.
 */
const TEST_ID_BASE = 'bizprocdesigner-construction-form-broken-links';

type ConstructionFormBrokenLinksSetup = {
	getMessage: GetMessage,
	scope: string,
	testIdBase: string,
};

// @vue/component
export const ConstructionFormBrokenLinks = {
	name: 'ConstructionFormBrokenLinks',
	components: {
		BrokenLinksNotice,
	},
	inject: {
		/**
		 * The approach to a field of the very form this warning stands in (TPL-01). Absent outside the
		 * panel - a form mounted on its own names the references and leads nowhere.
		 */
		leadToFieldInConstruction: { default: null },
	},
	props: {
		/** The construction whose form this warning stands in. */
		constructionId: {
			type: String,
			required: true,
		},
		/** @type Array<BrokenLinksNoticeItem> */
		items: {
			type: Array,
			required: true,
		},
	},
	setup(): ConstructionFormBrokenLinksSetup
	{
		const { getMessage } = useLoc();

		return {
			getMessage,
			scope: BROKEN_LINKS_SCOPES.constructionForm,
			testIdBase: TEST_ID_BASE,
		};
	},
	computed:
	{
		/**
		 * Names the action of an addressed reference twice over: as the hint of the mouse and as the
		 * accessible name of the button. The press does reach the field here, so the caption is the one
		 * of a field - the same phrase the panels name it by.
		 */
		goToFieldText(): string
		{
			return this.getMessage('BIZPROCDESIGNER_EDITOR_BROKEN_LINK_GO_TO_FIELD') ?? '';
		},
	},
	methods:
	{
		/**
		 * The person is already at the construction, so the approach starts where the one of the panel
		 * ends: at the request for a field. The mark, its length and the announcement stay with the
		 * panel - this warning only asks, and outside the panel there is nobody to ask.
		 */
		goToField(item: BrokenLinksNoticeItem): void
		{
			this.leadToFieldInConstruction?.(this.constructionId, item.link);
		},
	},
	/**
	 * `shouldAnnounce` is left at its default: the appearance is spoken of by one area per panel, and
	 * the references of this form are already named by the list the panel counts over the host node
	 * (TPL-02).
	 */
	template: `
		<BrokenLinksNotice
			:items="items"
			:scope="scope"
			:goToLabel="goToFieldText"
			:testIdBase="testIdBase"
			@itemClick="goToField"
		/>
	`,
};
