import { Loc, Type } from 'main.core';

const DEFAULT_TITLE_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_LANE_DEFAULT_TITLE';

/**
 * The caption of a lane: the name it carries once it has one, and the number of its place until then.
 * The number is the place and nothing else: a lane stays "Дорожка 3" whether or not the two above it
 * were given names of their own. Read both by the lane itself and by the announcements of the feature
 * that writes it, so the two never name the same lane differently.
 */
export function poolLaneTitle(lane: ?{ title?: string }, index: number): string
{
	if (Type.isStringFilled(lane?.title))
	{
		return lane.title;
	}

	// a phrase that failed to load comes back as null, and the caption takes a string
	return Loc.getMessage(DEFAULT_TITLE_MESSAGE_ID, { '#NUMBER#': String(index + 1) }) ?? '';
}
