import { Loc } from 'main.core';
import { Chip, ChipDesign, ChipSize } from 'ui.system.chip.vue';
import { useKeyboardShortcuts } from 'ui.block-diagram';

import { mapActions } from 'ui.vue3.pinia';

import { useNodeDataInspectorStore } from '../../../../shared/stores/node-data-inspector-store';
import { useAppStore } from '../../../../entities/app';
import { EDITOR_ACTION_ID } from '../../../../entities/hotkeys';

// @vue/component
export const ToggleInspectorControl = {
	name: 'ToggleInspectorControl',
	components: {
		Chip,
	},
	// The control is mounted only while the settings of a node are open (see the slot it fills in
	// app.js), so the shortcut it registers here is live exactly while it makes sense - showing the
	// data of a block nothing has open would have nothing to point at.
	setup(): Object
	{
		function toggleInspectorFromKeyboard(): void
		{
			useAppStore().toggleDataInspectorPanel();
			useNodeDataInspectorStore().resetGridView();
		}

		useKeyboardShortcuts([
			{
				actionId: EDITOR_ACTION_ID.TOGGLE_NODE_DATA,
				handler: toggleInspectorFromKeyboard,
			},
		]);

		return {};
	},
	computed: {
		text(): string
		{
			return Loc.getMessage('BIZPROCDESIGNER_EDITOR_NODE_DATA_INSPECTOR_TOGGLE_BUTTON_SHOW');
		},
		design(): string
		{
			return ChipDesign.OutlineAccent2;
		},
		ChipSize: (): typeof ChipSize => ChipSize,
	},
	methods: {
		...mapActions(useAppStore, ['toggleDataInspectorPanel']),
		...mapActions(useNodeDataInspectorStore, ['resetGridView']),
		toggleInspector(): void
		{
			this.toggleDataInspectorPanel();
			this.resetGridView();
		},
	},
	template: `
		<Chip
			class="editor-chart-data-inspector-toggle"
			:text="text"
			:size="ChipSize.Md"
			:design="design"
			@click="toggleInspector"
		/>
	`,
};
