import { Loc, Text } from 'main.core';
import { MessageBox } from 'ui.dialogs.messagebox';
import { UI } from 'ui.notification';
import { computed, ref } from 'ui.vue3';

import { formatActiveRunStartTime, useTestRunStore } from '../../../test-run';
import { focusProgrammatically, toSafeLinkUrl } from '../../../../shared/utils';

const LABELS = Object.freeze({
	ACTIVE_RUN_TITLE: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_TITLE',
	ACTIVE_RUN_DESCRIPTION: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_DESCRIPTION',
	BUTTON_FINISH: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_BUTTON_FINISH',
	BUTTON_CANCEL: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_BUTTON_CANCEL',
	DOCUMENT: 'BIZPROCDESIGNER_EDITOR_TEMPLATE_DOCUMENT',
	ACTIVE_RUN_CHANGED: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_CHANGED',
});

const NOTIFICATION_DELAY = 4000;

function loc(phraseCode: string, replacements: { [key: string]: string } = {}): string
{
	return Loc.getMessage(phraseCode, replacements) ?? '';
}

// @vue/component
export const DebugBarActiveRun = {
	name: 'DebugBarActiveRun',
	setup(): Object
	{
		const testRunStore = useTestRunStore();
		const root = ref(null);

		const activeRun = computed(() => testRunStore.activeRun);
		const startTime = computed((): string => formatActiveRunStartTime(testRunStore.activeRun));
		const documentLink = computed((): string => toSafeLinkUrl(testRunStore.activeRun?.documentUrl));

		async function finish(expectedSessionId: number): Promise<void>
		{
			if (testRunStore.activeRun?.sessionId !== expectedSessionId)
			{
				UI.Notification.Center.notify({
					content: Text.encode(loc(LABELS.ACTIVE_RUN_CHANGED)),
					autoHideDelay: NOTIFICATION_DELAY,
				});

				return;
			}

			// the row disappears with the run, so the focus stays in the container it was in
			const container = root.value?.parentElement ?? null;
			if (await testRunStore.finish(expectedSessionId))
			{
				focusProgrammatically(container);
			}
		}

		function handleFinish(): void
		{
			const expectedSessionId = testRunStore.activeRun?.sessionId ?? null;
			if (expectedSessionId === null)
			{
				return;
			}

			MessageBox.confirm(
				loc(LABELS.ACTIVE_RUN_DESCRIPTION, { '#TIME#': startTime.value }),
				loc(LABELS.ACTIVE_RUN_TITLE),
				async (messageBox) => {
					messageBox.close();
					await finish(expectedSessionId);
				},
				loc(LABELS.BUTTON_FINISH),
				(messageBox) => {
					messageBox.close();
				},
				loc(LABELS.BUTTON_CANCEL),
			);
		}

		return { root, activeRun, startTime, documentLink, labels: LABELS, loc, handleFinish };
	},
	template: `
		<div v-if="activeRun !== null" ref="root" class="debug-bar-active-run">
			<span class="debug-bar-active-run-title">{{ loc(labels.ACTIVE_RUN_TITLE) }}</span>
			<span class="debug-bar-active-run-time">{{ startTime }}</span>
			<a
				v-if="documentLink"
				class="debug-bar-active-run-document"
				:href="documentLink"
				target="_blank"
			>{{ loc(labels.DOCUMENT) }}</a>
			<button
				class="debug-bar-active-run-finish"
				type="button"
				data-testid="bizprocdesigner-editor-test-run-finish"
				@click="handleFinish"
			>{{ loc(labels.BUTTON_FINISH) }}</button>
		</div>
	`,
};
