import { BIcon, Outline } from 'ui.icon-set.api.vue';
import './catalog-group.css';
import '../catalog-focus-ring.css';
// eslint-disable-next-line no-unused-vars
import type { CatalogMenuGroup } from '../types';

// @vue/component
export const CatalogGroup = {
	name: 'CatalogGroup',
	components: {
		BIcon,
	},
	props: {
		/** @type CatalogMenuGroup */
		group: {
			type: Object,
			required: true,
		},
		showItems: {
			type: Boolean,
			default: false,
		},
	},
	emits: ['changeGroup'],
	setup(): { iconSet: { [string]: string } }
	{
		return { iconSet: Outline };
	},
	template: `
		<div class="editor-chart-catalog-group">
			<div
				:data-test-id="$testId('catalogGroup', group.id)"
				:data-group-id="group.id"
				class="editor-chart-catalog-group__header"
				role="button"
				tabindex="-1"
				:aria-expanded="showItems"
				@click="$emit('changeGroup', group)"
				@keydown.enter.stop.prevent="$emit('changeGroup', group)"
				@keydown.space.stop.prevent="$emit('changeGroup', group)"
				@keydown.right.stop.prevent="$emit('changeGroup', group)"
			>
				<div class="editor-chart-catalog-group__icon-wrapper">
					<slot name="icon"/>
				</div>

				<p class="editor-chart-catalog-group__title">{{ group.title }}</p>

				<BIcon
					:name="iconSet.ARROW_RIGHT_XS"
					:size="30"
					class="editor-chart-catalog-group__arrow"
				/>
			</div>

			<Transition name="catalog-items-transition">
				<!-- An overlay, not a nesting: the content covers the list of groups with an opaque
					panel of its own and slides away over 0.3s, standing in the markup until it is over
					while the list under it is the visible level again from the first frame. The marker
					is what keeps the roving focus of that list out of a group already left, and the
					group it names is what tells the level on screen from a level still going away. -->
				<div
					v-if="showItems"
					class="editor-chart-catalog-group__content"
					:data-catalog-level-overlay="group.id"
				>
					<div class="editor-chart-catalog-group__back-groups">
						<slot name="back"/>
					</div>

					<div
						v-if="group.items.length > 0"
						class="editor-chart-catalog-group__items"
						data-catalog-level="group-items"
						role="group"
						:aria-label="group.title"
					>
						<slot name="items"/>
					</div>

					<div
						v-else
						class="editor-chart-catalog-group__empty-label">
						<slot name="empty-label"/>
					</div>
				</div>
			</Transition>
		</div>
	`,
};
