import { Loc } from 'main.core';
import { BIcon, Outline } from 'ui.icon-set.api.vue';
import { AlertDesign } from 'ui.system.alert';
import { Alert } from 'ui.system.alert.vue';
import { TextSm } from 'ui.system.typography.vue';
import { mapState } from 'ui.vue3.pinia';

import { diagramStore as useDiagramStore } from '../../../../entities/blocks';

import './view-mode-bar.css';

export const VIEW_MODE_BAR_COLLAPSED_KEY = 'bizprocdesigner_editor_view_mode_bar_collapsed';

const ICON_SIZE = 16;

function loc(phraseCode: string, replacements: ?Object): string
{
	return Loc.getMessage(phraseCode, replacements) ?? '';
}

// Storage may be blocked (private mode); the bar then simply starts expanded.
function readCollapsed(): boolean
{
	try
	{
		return localStorage.getItem(VIEW_MODE_BAR_COLLAPSED_KEY) === '1';
	}
	catch
	{
		return false;
	}
}

function writeCollapsed(isCollapsed: boolean): void
{
	try
	{
		if (isCollapsed)
		{
			localStorage.setItem(VIEW_MODE_BAR_COLLAPSED_KEY, '1');
		}
		else
		{
			localStorage.removeItem(VIEW_MODE_BAR_COLLAPSED_KEY);
		}
	}
	catch
	{
		// storage unavailable: the choice lasts until reload
	}
}

// The view lasts as long as the page and leads nowhere: the only action of the bar is folding itself,
// a way from the view into editing does not exist.
// @vue/component
export const ViewModeBar = {
	name: 'ViewModeBar',
	components: {
		Alert,
		BIcon,
		TextSm,
	},
	setup(): Object
	{
		return {
			AlertDesign,
			Outline,
			ICON_SIZE,
		};
	},
	data(): Object
	{
		return {
			isCollapsed: readCollapsed(),
		};
	},
	computed: {
		...mapState(useDiagramStore, ['isViewMode', 'viewVersionLabel']),
		title(): string
		{
			return loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_BAR_TITLE');
		},
		hint(): string
		{
			return loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_BAR_HINT');
		},
		// A template without a reference version is named by nothing: an empty date would read as one.
		versionText(): string
		{
			return this.viewVersionLabel === null
				? ''
				: loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_VERSION_LABEL', { '#DATE#': this.viewVersionLabel })
			;
		},
		collapseText(): string
		{
			return loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_BAR_COLLAPSE');
		},
		collapsedText(): string
		{
			return loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_BAR_COLLAPSED');
		},
		expandText(): string
		{
			return loc('BIZPROCDESIGNER_EDITOR_VIEW_MODE_BAR_EXPAND');
		},
	},
	methods: {
		setCollapsed(isCollapsed: boolean): void
		{
			this.isCollapsed = isCollapsed;
			writeCollapsed(isCollapsed);

			// The pressed button is replaced by its counterpart, so the focus follows it.
			void this.$nextTick(() => {
				(isCollapsed ? this.$refs.expandButton : this.$refs.collapseButton)?.focus();
			});
		},
	},
	template: `
		<template v-if="isViewMode">
			<div
				v-if="isCollapsed"
				class="bizprocdesigner-editor-view-mode-bar__collapsed"
				data-testid="bizprocdesigner-editor-view-mode-bar-collapsed"
			>
				<button
					ref="expandButton"
					type="button"
					class="bizprocdesigner-editor-view-mode-bar__chip"
					aria-expanded="false"
					:aria-label="expandText"
					:title="expandText"
					data-testid="bizprocdesigner-editor-view-mode-bar-expand"
					@click="setCollapsed(false)"
				>
					<BIcon :name="Outline.OBSERVER" :size="ICON_SIZE"/>
					<TextSm>{{ collapsedText }}</TextSm>
					<BIcon :name="Outline.CHEVRON_DOWN_S" :size="ICON_SIZE"/>
				</button>
			</div>
			<Alert
				v-else
				:design="AlertDesign.tinted"
				data-testid="bizprocdesigner-editor-view-mode-bar"
			>
				<div class="bizprocdesigner-editor-view-mode-bar">
					<div class="bizprocdesigner-editor-view-mode-bar__text">
						<span data-testid="bizprocdesigner-editor-view-mode-bar-title">{{ title }}</span>
						<span
							v-if="versionText"
							data-testid="bizprocdesigner-editor-view-mode-bar-version"
						>{{ versionText }}</span>
						<span data-testid="bizprocdesigner-editor-view-mode-bar-hint">{{ hint }}</span>
					</div>
					<button
						ref="collapseButton"
						type="button"
						class="bizprocdesigner-editor-view-mode-bar__collapse"
						aria-expanded="true"
						:aria-label="collapseText"
						:title="collapseText"
						data-testid="bizprocdesigner-editor-view-mode-bar-collapse"
						@click="setCollapsed(true)"
					>
						<BIcon :name="Outline.CHEVRON_TOP_S" :size="ICON_SIZE"/>
					</button>
				</div>
			</Alert>
		</template>
	`,
};
