import { Type } from 'main.core';

import { CONSTRUCTION_TYPES } from '../../../entities/node-settings/constants';
import { findHeadRuleCard, findHeadRuleCardInsertIndex } from '../../../entities/node-settings/utils/rules-surface';
import { createUniqueId } from '../../../shared/utils';

// Property name the rules of a node live under, constant for the whole area: the panel writes them
// there through its own save, and a node whose panel was never opened carries them there as well
// (see NODE_SERVICE_PROPERTIES of the settings store, getActionAuxPortsFromActivity).
const RULES_PROPERTY = 'Rules';

// Node property naming the action the block of the general settings binds to. A node declaring none
// takes no block by default.
const BASE_SETTINGS_ACTION_PROPERTY = 'BaseSettingsAction';

function resolveBaseSettingsAction(activity)
{
	const actionId = activity?.Properties?.[BASE_SETTINGS_ACTION_PROPERTY];

	return Type.isStringFilled(actionId) ? actionId : null;
}

// Data of its own and nothing else: neither the properties of the node nor the ones of another block
// are read here, so every input carries an independent construction. Empty activity data is what
// opens the standard new form of the bound action with its own initial values.
function buildConstruction(actionId)
{
	return {
		id: createUniqueId(),
		type: CONSTRUCTION_TYPES.BASE_SETTINGS,
		expression: {
			actionId,
			rawActivityData: null,
			activityData: null,
		},
	};
}

// Port id naming no input at all: written into a plain object it replaces the prototype of the
// collection instead of storing a rule, so the whole call is refused rather than half-performed.
const PROTOTYPE_PORT_ID = '__proto__';

// The rules of an open panel are keyed by port id in a Map, the ones a closed node carries in its own
// activity in a plain object. Both are read and written through the two helpers below. A plain object
// answers for keys it never stored - `constructor`, `toString` - so only a key the collection owns is
// a rule of the node.
function getRule(rules, portId)
{
	if (rules instanceof Map)
	{
		return rules.get(portId) ?? null;
	}

	return Object.prototype.hasOwnProperty.call(rules, portId) ? (rules[portId] ?? null) : null;
}

function addRule(rules, portId)
{
	const rule = { portId, ruleCards: [] };
	if (rules instanceof Map)
	{
		rules.set(portId, rule);
	}
	else
	{
		rules[portId] = rule;
	}

	return rule;
}

function hasBaseSettings(rule)
{
	return (rule.ruleCards ?? []).some(
		(ruleCard) => (ruleCard.constructions ?? []).some(
			(construction) => construction?.type === CONSTRUCTION_TYPES.BASE_SETTINGS,
		),
	);
}

// Card the head blocks of an input live in, created when the input has none. It stays untitled: the
// head area renders it above the groups and never as a group of its own.
function resolveHeadRuleCard(rule)
{
	const headRuleCard = findHeadRuleCard(rule.ruleCards);
	if (headRuleCard)
	{
		return headRuleCard;
	}

	const position = findHeadRuleCardInsertIndex(rule.ruleCards);
	rule.ruleCards.splice(position, 0, { id: createUniqueId(), constructions: [], groupTitle: '' });

	return rule.ruleCards[position];
}

/**
 * Block of the general settings an ordinary input is created with: it goes to the head card of that
 * input alone and binds to the action the node declares in its own properties.
 * Returns the construction written, or null when nothing was - the node binds no action, the input
 * already carries a block, or the caller named no input at all. Nothing but the binding is read from
 * the node, so two inputs never share data.
 *
 * @param {Map<string, Object> | Object | null} rules Rules collection keyed by input port id.
 * @param {string} portId Input the block belongs to.
 * @param {Object | null} activity Activity data of the node.
 * @returns {Object | null}
 */
export function createInputBaseSettings(rules, portId, activity)
{
	const actionId = resolveBaseSettingsAction(activity);
	if (actionId === null || !rules || !Type.isStringFilled(portId) || portId === PROTOTYPE_PORT_ID)
	{
		return null;
	}

	const rule = getRule(rules, portId) ?? addRule(rules, portId);
	if (hasBaseSettings(rule))
	{
		return null;
	}

	const construction = buildConstruction(actionId);
	resolveHeadRuleCard(rule).constructions.splice(0, 0, construction);

	return construction;
}

/**
 * The same block written into the rules the activity of the node keeps itself - the way a node whose
 * panel is closed carries them. Returns the construction written, or null when nothing was: the
 * caller then leaves the activity of the node alone.
 *
 * @param {Object | null} activity Activity data of the node.
 * @param {string} portId Input the block belongs to.
 * @returns {Object | null}
 */
export function createInputBaseSettingsInActivity(activity, portId)
{
	const properties = activity?.Properties;
	if (!Type.isPlainObject(properties))
	{
		return null;
	}

	const savedRules = properties[RULES_PROPERTY];
	if (savedRules !== undefined && !Type.isPlainObject(savedRules))
	{
		return null;
	}

	const rules = savedRules ?? {};
	const construction = createInputBaseSettings(rules, portId, activity);
	if (construction !== null)
	{
		properties[RULES_PROPERTY] = rules;
	}

	return construction;
}
