import { Loc, Text, Type } from 'main.core';
import { MessageBox } from 'ui.dialogs.messagebox';

import { type Block, type Connection, type Port } from '../../shared/types';

import { BUTTONS_FIELD_NAME } from './constants';
import {
	isTaskNodeBlock,
	portsLosingBranch,
	releasedButtonPorts,
	syncButtonPorts,
	wantedButtonPorts,
} from './ports';

type DiagramPorts = {
	connections: Array<Connection>,
	setPorts: (blockId: string, ports: Array<Port>) => void,
	deleteConnectionByBlockIdAndPortId: (blockId: string, portId: string) => void,
};

/** The title of a port is the title of its button; a legacy port without one is named as such. */
function buttonName(port: Port): string
{
	const title = Type.isStringFilled(port.title)
		? Text.encode(port.title)
		: Loc.getMessage('BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BUTTON_UNNAMED')
	;

	return `«${title}»`;
}

function branchLossMessage(ports: Array<Port>): string
{
	if (ports.length === 1)
	{
		return Loc.getMessage(
			'BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BRANCH_LOSS',
			{ '#BUTTON#': buttonName(ports[0]) },
		);
	}

	return Loc.getMessage(
		'BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BRANCH_LOSS_MANY',
		{ '#BUTTONS#': ports.map((port) => buttonName(port)).join(', ') },
	);
}

/**
 * The buttons the settings form is about to save. They live in one hidden field of the form, so the
 * ports follow the configuration that is really leaving for the server.
 */
function formButtons(formData: Object): mixed
{
	return formData?.[BUTTONS_FIELD_NAME];
}

/**
 * The buttons the node is saved with. Read before the save: it replaces the activity of the block, and
 * only the configuration that was there tells the answer that owned a slot from the one taking it over.
 */
export function savedButtonsOf(block: ?Block): mixed
{
	return block?.activity?.Properties?.[BUTTONS_FIELD_NAME];
}

/** The output ports the save takes away from the buttons that own them now. */
function releasedPorts(block: ?Block, savedButtons: mixed, formData: Object): Array<Port>
{
	return releasedButtonPorts(block, savedButtons, formButtons(formData));
}

/**
 * Saving a task node cuts the branch of every button the node no longer holds, so the author confirms
 * that first (AC-012). Anything else - another kind of activity, or a node whose buttons keep their
 * branches - is saved right away.
 */
export function askBeforeBranchLoss(
	diagram: DiagramPorts,
	block: ?Block,
	savedButtons: mixed,
	formData: Object,
	onConfirmed: () => void,
): void
{
	const losingPorts = isTaskNodeBlock(block)
		? portsLosingBranch(diagram, block, releasedPorts(block, savedButtons, formData))
		: []
	;

	if (losingPorts.length === 0)
	{
		onConfirmed();

		return;
	}

	MessageBox.confirm(
		branchLossMessage(losingPorts),
		Loc.getMessage('BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BRANCH_LOSS_TITLE'),
		(messageBox) => {
			messageBox.close();
			onConfirmed();
		},
		Loc.getMessage('BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BRANCH_LOSS_OK'),
		(messageBox) => {
			messageBox.close();
		},
		Loc.getMessage('BIZPROCDESIGNER_EDITOR_TASK_NODE_PORTS_BRANCH_LOSS_CANCEL'),
	);
}

/**
 * After the save the ports of the node follow the buttons it now holds (ALG-02). Called with the value
 * the save carried, so the ports of the block describe exactly the configuration the template keeps,
 * and with the buttons snapshot of {@link savedButtonsOf}, which the save has replaced by then.
 */
export function syncButtonPortsAfterSave(
	diagram: DiagramPorts,
	block: ?Block,
	savedButtons: mixed,
	formData: Object,
): void
{
	if (!isTaskNodeBlock(block))
	{
		return;
	}

	syncButtonPorts(
		diagram,
		block,
		wantedButtonPorts(formButtons(formData)),
		releasedPorts(block, savedButtons, formData),
	);
}
