import { Dom, Type } from 'main.core';
import { BitrixVue } from 'ui.vue3';

type CustomControlField = {
	property: { CustomType?: string },
	controlId: ?string,
};

type CustomControlRenderer = ((field: CustomControlField) => ?HTMLElement) | Object;

type PendingMount = { component: Object, field: CustomControlField, wrapper: HTMLElement };

function isVueComponent(renderer: ?CustomControlRenderer): boolean
{
	return (
		Type.isPlainObject(renderer)
		&& (
			Type.isFunction(renderer.render)
			|| Type.isFunction(renderer.setup)
			|| Type.isStringFilled(renderer.template)
		)
	);
}

/**
 * The `custom` fields of a node settings form. A renderer of the activity hands back either a function
 * that draws the control or a Vue component: the component gets a wrapper of its own to be mounted into
 * once the form is on screen, and the applications mounted that way are taken down with the form.
 */
export class CustomControlMounts
{
	#pending: Array<PendingMount> = [];
	#apps: Array<{ unmount: () => void }> = [];

	render(field: CustomControlField, customRenderers: ?{ [string]: CustomControlRenderer }): ?HTMLElement
	{
		const customType = field?.property?.CustomType;
		const renderer = (customRenderers && Object.hasOwn(customRenderers, customType))
			? customRenderers[customType]
			: null
		;
		if (isVueComponent(renderer))
		{
			const wrapper = Dom.create('div', {
				attrs: {
					class: 'vue-field-wrapper',
					'data-component-key': `${field.property.CustomType}_${field.controlId}`,
				},
			});
			this.#pending.push({ component: renderer, field, wrapper });

			return wrapper;
		}

		return Type.isFunction(renderer) ? renderer(field) : null;
	}

	mount(): void
	{
		this.#pending.splice(0).forEach(({ component, field, wrapper }: PendingMount) => {
			const app = BitrixVue.createApp(component, { field });
			app.mount(wrapper);
			this.#apps.push(app);
		});
	}

	unmount(): void
	{
		this.#pending = [];
		this.#apps.splice(0).forEach((app) => app.unmount());
	}
}
