import { Text } from 'main.core';

// An action the user has left without a combo hands in an empty caption. The key block is dropped
// with it: an empty one would render as a blank key beside the item.
//
// `shortcut` is a caption built from a combo - and a combo can be a personal setting a user typed
// into the settings panel, or (unlike the panel's own display, which never leaves Vue's escaped
// interpolation) a value read back from storage shared with other users (a common option written by
// whoever may set one). Both `text` and `shortcut` go through `Text.encode()` before they reach this
// raw HTML string, the same way every other menu item of the editor built outside Vue already does.
export function getContextMenuItemHtml(text: string, shortcut: string = ''): string
{
	const encodedShortcut = Text.encode(shortcut);
	const shortcutHtml = encodedShortcut === '' ? '' : `
		<span class="editor-chart-block-control-menu-item__action-code">
			<span class="editor-chart-block-control-menu-item__action-code_text">
				${encodedShortcut}
			</span>
		</span>
	`;

	return `
		<span class="editor-chart-block-control-menu-item">
			${Text.encode(text)}
			${shortcutHtml}
		</span>
	`;
}
