import { Loc } from 'main.core';
import { computed, toValue } from 'ui.vue3';
import { useContextMenu } from 'ui.block-diagram';
import { BIcon, Outline } from 'ui.icon-set.api.vue';
import { BLOCK_COLOR_NAMES } from '../../constants';
import { BX_FLAG_NO } from '../../../../shared/constants';
import {
	AGENT_HIGHLIGHT_ANIMATED_MODIFIER_CLASS,
	AGENT_HIGHLIGHT_MODIFIER_CLASS,
} from '../../../ai-assistant/constants';
import { useAgentHighlightStore } from '../../../ai-assistant/stores/agent-highlight-store';
import { AgentGlow } from '../../../ai-assistant/ui/agent-glow/agent-glow';
import { TEST_RUN_NODE_STATES, useTestRunStore } from '../../../test-run';
// eslint-disable-next-line no-unused-vars
import type { MenuItemOptions } from 'ui.vue3.components.menu';

import './block-container.css';

type TestRunStateMarker = {
	icon: string;
	label: string;
	modifier: string;
};

type BlockContainerSetup = {
	blockContainerClassNames: { [string]: boolean };
	blockContainerStyle: { [string]: string };
	testRunStateMarker: TestRunStateMarker | null;
};

const BLOCK_CONTAINER_CLASS_NAMES = {
	base: 'editor-chart-block-container',
	highlighted: '--highlighted',
	testRunRunning: '--test-run-running',
	deactivated: '--deactivated',
	hoverable: '--hoverable',
	aiHighlighted: AGENT_HIGHLIGHT_MODIFIER_CLASS,
	aiHighlightAnimated: AGENT_HIGHLIGHT_ANIMATED_MODIFIER_CLASS,
	[BLOCK_COLOR_NAMES.WHITE]: '--white',
	[BLOCK_COLOR_NAMES.ORANGE]: '--orange',
	[BLOCK_COLOR_NAMES.BLUE]: '--blue',
};

const TEST_RUN_ERROR_BORDER_COLOR = 'var(--ui-color-accent-main-alert)';

const TEST_RUN_STATE_MARKERS = Object.freeze({
	[TEST_RUN_NODE_STATES.RUNNING]: {
		icon: Outline.HOURGLASS,
		phrase: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_NODE_STATE_RUNNING',
		modifier: '--running',
	},
	[TEST_RUN_NODE_STATES.PASSED]: {
		icon: Outline.CIRCLE_CHECK,
		phrase: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_NODE_STATE_PASSED',
		modifier: '--passed',
	},
	[TEST_RUN_NODE_STATES.ERROR]: {
		icon: Outline.ALERT,
		phrase: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_NODE_STATE_ERROR',
		modifier: '--error',
	},
});

// @vue/component
export const BlockContainer = {
	name: 'BlockContainer',
	components: {
		AgentGlow,
		BIcon,
	},
	props: {
		/** @type Block */
		block: {
			type: Object,
			default: null,
		},
		/** @type Array<MenuItemOptions> */
		contextMenuItems: {
			type: Array,
			default: () => ([]),
		},
		width: {
			type: Number,
			default: null,
		},
		height: {
			type: Number,
			default: null,
		},
		highlighted: {
			type: Boolean,
			default: false,
		},
		disabled: {
			type: Boolean,
			default: false,
		},
		hoverable: {
			type: Boolean,
			default: true,
		},
		backgroundColor: {
			type: String,
			default: null,
		},
		borderColor: {
			type: String,
			default: null,
		},
	},
	setup(props): BlockContainerSetup
	{
		const {
			isOpen: isOpenContextMenu,
			showMenu,
			closeContextMenu,
		} = useContextMenu();

		const agentHighlightStore = useAgentHighlightStore();
		const testRunStore = useTestRunStore();

		const testRunNodeState = computed((): string | null => {
			return testRunStore.displayedNodeStates[props.block?.id] ?? null;
		});

		const testRunStateMarker = computed((): TestRunStateMarker | null => {
			const marker = TEST_RUN_STATE_MARKERS[toValue(testRunNodeState)] ?? null;
			if (marker === null)
			{
				return null;
			}

			return {
				icon: marker.icon,
				label: Loc.getMessage(marker.phrase) ?? '',
				modifier: marker.modifier,
			};
		});

		const isHighlighted = computed((): boolean => {
			return props.highlighted || toValue(testRunNodeState) === TEST_RUN_NODE_STATES.PASSED;
		});

		const isAgentHighlighted = computed((): boolean => {
			return agentHighlightStore.isBlockHighlighted(props.block?.id);
		});

		const isAgentHighlightAnimated = computed((): boolean => {
			return agentHighlightStore.isBlockHighlightAnimated(props.block?.id);
		});

		const isBlockActivated = computed((): boolean => {
			if (!props.block?.activity?.Activated)
			{
				return true;
			}

			return props.block.activity.Activated !== BX_FLAG_NO;
		});

		const blockContainerClassNames = computed((): { [string]: boolean } => ({
			[BLOCK_CONTAINER_CLASS_NAMES.base]: true,
			[BLOCK_CONTAINER_CLASS_NAMES.highlighted]: toValue(isHighlighted),
			[BLOCK_CONTAINER_CLASS_NAMES.testRunRunning]: toValue(testRunNodeState) === TEST_RUN_NODE_STATES.RUNNING,
			[BLOCK_CONTAINER_CLASS_NAMES.deactivated]: !toValue(isBlockActivated),
			[BLOCK_CONTAINER_CLASS_NAMES.hoverable]: props.hoverable,
			[BLOCK_CONTAINER_CLASS_NAMES.aiHighlighted]: toValue(isAgentHighlighted),
			[BLOCK_CONTAINER_CLASS_NAMES.aiHighlightAnimated]: toValue(isAgentHighlightAnimated),
		}));

		const blockContainerStyle = computed((): { [string]: string } => {
			const style: { [string]: string } = {};

			if (props.width !== null)
			{
				style.width = `${props.width}px`;
			}

			if (props.height !== null)
			{
				style.height = `${props.height}px`;
			}

			if (props.backgroundColor !== null)
			{
				style.backgroundColor = props.backgroundColor;
			}

			const nodeState = toValue(testRunNodeState);
			if (nodeState === TEST_RUN_NODE_STATES.ERROR)
			{
				style.borderColor = TEST_RUN_ERROR_BORDER_COLOR;
			}
			else if (props.borderColor !== null && !toValue(isHighlighted) && nodeState !== TEST_RUN_NODE_STATES.RUNNING)
			{
				style.borderColor = props.borderColor;
			}

			return style;
		});

		function onShowContextMenu(event: MouseEvent): void
		{
			event.preventDefault();

			if (props.disabled)
			{
				return;
			}

			showMenu(
				{ clientX: event.clientX, clientY: event.clientY },
				{ items: props.contextMenuItems },
			);
		}

		return {
			isOpenContextMenu,
			isBlockActivated,
			isAgentHighlighted,
			blockContainerClassNames,
			blockContainerStyle,
			testRunStateMarker,
			onShowContextMenu,
			closeContextMenu,
		};
	},
	template: `
		<div
			:class="blockContainerClassNames"
			:data-testid="block ? 'bizprocdesigner-block-' + block.id : null"
			:style="blockContainerStyle"
			@mousedown="closeContextMenu"
			@contextmenu.stop="onShowContextMenu"
		>
			<slot
				:isOpenContextMenu="isOpenContextMenu"
				:isBlockActivated="isBlockActivated"
			/>
			<span
				v-if="testRunStateMarker !== null"
				class="editor-chart-block-container__test-run-state"
				:class="testRunStateMarker.modifier"
				role="img"
				:aria-label="testRunStateMarker.label"
				:title="testRunStateMarker.label"
				data-testid="bizprocdesigner-block-test-run-state"
			>
				<BIcon :name="testRunStateMarker.icon" :size="16"/>
			</span>
			<AgentGlow v-if="isAgentHighlighted"/>
		</div>
	`,
};
