/**
 * The lane lists of the pools follow a single drag of an activity.
 *
 * The lane is decided once the gesture is over, by the position the store holds by then: the
 * placement rule of the engine and the insert controller subscribed before this one have both had
 * their say. The pools are written in the same synchronous tick as the move, so the deferred history
 * snapshot of `endDragBlock` takes the move and the lists as one step. An activity dropped from the
 * catalog is written the same way, in the tick of its `addBlock`.
 *
 * A write is said out loud right away, with no wait for the draft: a move does not wait for the
 * server, and a refused draft re-reads the schema anyway.
 */

import { Loc } from 'main.core';
import { LiveAnnouncer } from 'ui.a11y';
import { useBlockDiagram, useHistory } from 'ui.block-diagram';
import { onUnmounted, ref, toValue, watch } from 'ui.vue3';

import { diagramStore as useDiagramStore, poolLaneTitle } from '../../../entities/blocks';
import { isLaneActivity, laneMembershipChanges, laneTargetAt, listedLaneOf } from '../lib/pool-lane-membership.ts';
import { canEditPoolLanes } from './can-edit-pool-lanes';

const IN_LANE_ANNOUNCE_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_ACTIVITY_IN_LANE_ANNOUNCE';
const LEFT_POOL_ANNOUNCE_MESSAGE_ID = 'BIZPROCDESIGNER_EDITOR_POOL_BLOCK_ACTIVITY_LEFT_POOL_ANNOUNCE';

// One drag at a time on the canvas, and the pool draws the lane the drag aims at.
const dropTargetLane = ref(null);

/**
 * @returns {{ dropTargetLane: Ref<LaneTarget | null> }}
 */
export function useLaneDropTarget()
{
	return { dropTargetLane };
}

/**
 * A phrase that failed to load comes back as null, and the announcer takes a string.
 *
 * @param {Array<Block>} blocks The blocks the lists were rewritten from.
 * @param {Block} activity
 * @param {LaneTarget | null} before The lane listing the activity before the write.
 * @param {LaneTarget | null} target The lane the activity stands in now.
 */
function announceMembership(blocks, activity, before, target)
{
	const poolOf = (lane) => blocks.find((block) => block.id === lane.blockId) ?? null;
	const activityTitle = activity.node?.title ?? '';

	if (target)
	{
		const lane = poolOf(target)?.node.poolLanes[target.index];
		LiveAnnouncer.announce(Loc.getMessage(IN_LANE_ANNOUNCE_MESSAGE_ID, {
			'#TITLE#': activityTitle,
			'#LANE#': poolLaneTitle(lane, target.index),
		}) ?? '', 'polite');
	}
	else if (before)
	{
		LiveAnnouncer.announce(Loc.getMessage(LEFT_POOL_ANNOUNCE_MESSAGE_ID, {
			'#TITLE#': activityTitle,
			'#POOL#': poolOf(before)?.node?.title ?? '',
		}) ?? '', 'polite');
	}
}

/**
 * The value changes only with the lane, so a frame inside the same lane does not redraw the pool.
 *
 * @param {Array<Block>} blocks
 * @param {Block | null} activity
 * @param {{ x: number, y: number } | undefined} frameRect The rect of the gesture in `blocksRectMap`.
 */
function aimDropTarget(blocks, activity, frameRect)
{
	const target = activity && frameRect
		? laneTargetAt(blocks, { x: frameRect.x, y: frameRect.y, ...activity.dimensions })
		: null
	;

	const current = dropTargetLane.value;
	if (target?.blockId !== current?.blockId || target?.laneId !== current?.laneId)
	{
		dropTargetLane.value = target;
	}
}

export function useLaneMembership()
{
	const { hooks, blocksRectMap, gestureBlockIds, movingBlockId, replaceBlocks } = useBlockDiagram();
	const { makeSnapshot } = useHistory();
	const store = useDiagramStore();
	// { blockId, position, isGroup } of the drag that may write, null otherwise.
	let gesture = null;

	const findBlock = (blockId) => store.blocks.find((block) => block.id === blockId) ?? null;

	function resetGesture()
	{
		gesture = null;
		dropTargetLane.value = null;
	}

	function writeMembership(activity)
	{
		const blocks = store.blocks;
		const before = listedLaneOf(blocks, activity.id);
		const target = laneTargetAt(blocks, { ...activity.position, ...activity.dimensions });
		const changes = laneMembershipChanges(blocks, activity.id, target);
		if (changes.length === 0)
		{
			return;
		}

		// Not `updateBlock`: its hook raises the command flag of the canvas, and the watcher then skips the
		// full rebuild of the block index that a move published by the insert controller relies on, so the
		// placement rule would keep seeing the activity where the drag started.
		const changedById = new Map(changes.map((pool) => [pool.id, pool]));
		replaceBlocks(blocks.map((block) => changedById.get(block.id) ?? block));
		void makeSnapshot();
		announceMembership(blocks, activity, before, target);
	}

	// The selection says nothing here: the settings mediator, subscribed earlier, swaps it for the
	// block of an open panel. The participants of the gesture are set before it opens.
	const onStartDragBlock = (block) => {
		resetGesture();

		const blockId = toValue(block).id;
		const participants = toValue(gestureBlockIds);
		if (!canEditPoolLanes() || participants.size !== 1 || !participants.has(blockId))
		{
			return;
		}

		const activity = findBlock(blockId);
		if (activity && isLaneActivity(activity))
		{
			gesture = { blockId, position: { ...activity.position }, isGroup: false };
		}
	};

	// The model learns the position only at the commit; the frames move the measured rect.
	const onMoveDragBlock = (block) => {
		const blockId = toValue(block)?.id;
		if (gesture !== null && !gesture.isGroup && blockId === gesture.blockId)
		{
			aimDropTarget(store.blocks, findBlock(blockId), toValue(blocksRectMap)?.[blockId]);
		}
	};

	// The satellites of a group are written first, each reported by an end of its own.
	const onEndDragBlock = (block) => {
		if (gesture === null)
		{
			return;
		}

		if (toValue(block)?.id !== gesture.blockId)
		{
			gesture.isGroup = true;
			dropTargetLane.value = null;

			return;
		}

		const { blockId, position, isGroup } = gesture;
		resetGesture();

		const activity = findBlock(blockId);
		if (isGroup || !canEditPoolLanes() || !activity)
		{
			return;
		}

		if (activity.position.x !== position.x || activity.position.y !== position.y)
		{
			writeMembership(activity);
		}
	};

	// The engine reports the drop right after `addBlock`, so the store already holds the block where
	// the placement rule put it.
	const onDropNewBlock = (dropped) => {
		const activity = findBlock(dropped.id);
		if (canEditPoolLanes() && activity && isLaneActivity(activity))
		{
			writeMembership(activity);
		}
	};

	// A press without a move and Escape end the gesture with no end of the drag.
	const stopWatchingMove = watch(movingBlockId, (id) => {
		if (id === null)
		{
			resetGesture();
		}
	}, { flush: 'sync' });

	hooks.startDragBlock.on(onStartDragBlock);
	hooks.moveDragBlock.on(onMoveDragBlock);
	hooks.endDragBlock.on(onEndDragBlock);
	hooks.dropNewBlock.on(onDropNewBlock);

	onUnmounted(() => {
		hooks.startDragBlock.off(onStartDragBlock);
		hooks.moveDragBlock.off(onMoveDragBlock);
		hooks.endDragBlock.off(onEndDragBlock);
		hooks.dropNewBlock.off(onDropNewBlock);
		stopWatchingMove();
		resetGesture();
	});
}
