import { lockReadOnlySurface, releaseReadOnlySurface } from '../utils/read-only-surface';

type Binding = { value: boolean };

function apply(el: HTMLElement, { value }: Binding): void
{
	if (value)
	{
		lockReadOnlySurface(el);
	}
	else
	{
		releaseReadOnlySurface(el);
	}
}

// v-read-only-surface="isReadOnly": nothing inside the element can be changed while the value holds.
export const ReadOnlySurface = {
	mounted: apply,
	updated: apply,
	beforeUnmount(el: HTMLElement): void
	{
		releaseReadOnlySurface(el);
	},
};
