/**
 * The question asked before a note or a message goes for good. Both places that ask it - the
 * completion of a discussion and the deletion of the last message in it - lose the whole of a
 * conversation, so they ask it in the same window and in the same words.
 *
 * The dialog of the design system is what draws it: the message box of the old design is still in
 * the product, and these two questions asking with it would be windows of the editor built on the
 * design before this one. The question about text written but not sent
 * (`ask-to-discard-unsent-text.ts`) is the one that does still ask with that box, and what holds it
 * there is written in its own header.
 */

import { Tag, Text } from 'main.core';
import { AirButtonStyle, Button, ButtonSize, CancelButton } from 'ui.buttons';
import { Dialog } from 'ui.system.dialog';

const DIALOG_WIDTH = 470;

// The dataset key is lower-case on purpose: `testid` renders as data-testid, the attribute
// page.getByTestId() looks for, while a camel-cased `testId` would render data-test-id.
const CONTENT_TEST_ID = 'bizprocdesigner-note-confirm';
const CONFIRM_TEST_ID = 'bizprocdesigner-note-confirm-ok';
const CANCEL_TEST_ID = 'bizprocdesigner-note-confirm-cancel';

export type NoteConfirmParams = {
	title: string,
	text: string,
	confirmText: string,
	cancelText: string,
	onConfirm: () => void,
};

/** Asks, and calls back only on an answer: closing the window leaves everything as it was. */
export function askNoteAction(params: NoteConfirmParams): void
{
	const content = Tag.render`
		<div class="editor-chart-note-confirm" data-testid="${CONTENT_TEST_ID}">${Text.encode(params.text)}</div>
	`;

	const dialog = new Dialog({
		title: params.title,
		content,
		width: DIALOG_WIDTH,
		hasCloseButton: true,
		closeByEsc: true,
		hasOverlay: true,
		centerButtons: [
			new Button({
				text: params.confirmText,
				useAirDesign: true,
				size: ButtonSize.LARGE,
				style: AirButtonStyle.FILLED,
				dataset: { testid: CONFIRM_TEST_ID },
				onclick: () => {
					dialog.hide();
					params.onConfirm();
				},
			}),
			new CancelButton({
				text: params.cancelText,
				useAirDesign: true,
				size: ButtonSize.LARGE,
				style: AirButtonStyle.PLAIN,
				dataset: { testid: CANCEL_TEST_ID },
				onclick: () => dialog.hide(),
			}),
		],
	});

	dialog.show();
}
