import { Loader as CoreLoader } from 'main.loader';

import './icon-loader.css';

const ICON_LOADER_SIZE = 22;
const ICON_LOADER_COLOR = 'var(--ui-color-base-4)';

/**
 * A spinner the size of an icon, for a slot a state later fills with its result icon. main.loader
 * is the only ready-made one that animates: it renders the circle inline and runs the animation on
 * the element, while the animated icon set keeps its animation inside the svg file, where the mask
 * of ui.icon-set drops it.
 */
// @vue/component
export const IconLoader = {
	name: 'EditorChartIconLoader',
	props: {
		size: {
			type: Number,
			default: ICON_LOADER_SIZE,
		},
		color: {
			type: String,
			default: ICON_LOADER_COLOR,
		},
	},
	created(): void
	{
		// The instance stays out of reactive state: a Proxy around it breaks its private fields
		this.loader = null;
	},
	mounted(): void
	{
		this.loader = new CoreLoader({
			target: this.$refs.container,
			size: this.size,
			color: this.color,
			mode: 'inline',
		});

		void this.loader.show();
	},
	beforeUnmount(): void
	{
		this.loader?.destroy();
		this.loader = null;
	},
	template: `
		<span
			class="editor-chart-icon-loader"
			ref="container"
			aria-hidden="true"
		></span>
	`,
};
