import { BLOCK_TYPES, COMPLEX_NODE_PORT_LABELS, PORT_TYPES } from '../../../shared/constants';

const DEFAULT_MIN_RULE_ITEMS_COUNT = 5;
const SWITCH_NODE_ACTIVITY = 'SwitchNode';
const SWITCH_NODE_MIN_RULE_ITEMS_COUNT = 3;
const OUTPUT_POSITION = 'right';

export const COMPLEX_INSERT_PORT_PLAN_STATUS = Object.freeze({
	NOT_APPLICABLE: 'notApplicable',
	REJECT: 'reject',
	READY: 'ready',
});

const NOT_APPLICABLE_RESULT = Object.freeze({
	status: COMPLEX_INSERT_PORT_PLAN_STATUS.NOT_APPLICABLE,
});
const REJECT_RESULT = Object.freeze({
	status: COMPLEX_INSERT_PORT_PLAN_STATUS.REJECT,
});

function normalizeMinRuleItemsCount(minRuleItemsCount)
{
	return Number.isInteger(minRuleItemsCount) && minRuleItemsCount > 0
		? minRuleItemsCount
		: DEFAULT_MIN_RULE_ITEMS_COUNT
	;
}

function getTitleIndex(title, label)
{
	const match = title?.match(new RegExp(`^${label}([1-9]\\d*)$`));
	if (!match)
	{
		return null;
	}

	return match[1];
}

function compareDecimalIndexes(left, right)
{
	if (left.length !== right.length)
	{
		return left.length - right.length;
	}

	if (left === right)
	{
		return 0;
	}

	return left < right ? -1 : 1;
}

function incrementDecimalIndex(index)
{
	const digits = [...index];
	for (let position = digits.length - 1; position >= 0; position--)
	{
		if (digits[position] !== '9')
		{
			digits[position] = String(Number(digits[position]) + 1);

			return digits.join('');
		}

		digits[position] = '0';
	}

	return `1${digits.join('')}`;
}

function normalizeDecimalIndex(index)
{
	return index.replace(/^0+(?=\d)/, '');
}

function isPort(item)
{
	return item.type !== undefined;
}

function clonePort(port)
{
	return Object.freeze({ ...port });
}

export function getComplexNodeMinRuleItemsCount(block)
{
	return block?.activity?.Type === SWITCH_NODE_ACTIVITY
		? SWITCH_NODE_MIN_RULE_ITEMS_COUNT
		: DEFAULT_MIN_RULE_ITEMS_COUNT
	;
}

export function createComplexNodePlaceholderId(blockId, title)
{
	return `placeholder_${blockId}_${title}`;
}

export function buildComplexNodeRuleRows(options)
{
	const {
		blockId,
		ports = [],
		portType,
		label,
		minRuleItemsCount,
	} = options;
	const normalizedMinRuleItemsCount = normalizeMinRuleItemsCount(minRuleItemsCount);
	const columnPorts = ports.filter((port) => port.type === portType);
	const portsByIndex = new Map();
	const unindexedPorts = [];

	columnPorts.forEach((port) => {
		const index = getTitleIndex(port.title, label);
		if (index === null || portsByIndex.has(index))
		{
			unindexedPorts.push(port);

			return;
		}

		portsByIndex.set(index, port);
	});

	const reservedRows = Array.from({ length: normalizedMinRuleItemsCount }, (_, offset) => {
		const index = offset + 1;
		const port = portsByIndex.get(String(index));
		if (port)
		{
			return port;
		}

		const title = `${label}${index}`;

		return {
			id: createComplexNodePlaceholderId(blockId, title),
			title,
		};
	});
	const orderedIndexedPorts = [...portsByIndex.entries()]
		.sort(([left], [right]) => compareDecimalIndexes(left, right))
	;
	const orderedRestPorts = orderedIndexedPorts
		.filter(([index]) => compareDecimalIndexes(index, String(normalizedMinRuleItemsCount)) > 0)
		.map(([, port]) => port)
	;
	orderedRestPorts.push(...unindexedPorts);

	const maxIndexedPort = orderedIndexedPorts[orderedIndexedPorts.length - 1];
	const hasPortBeyondReserve = maxIndexedPort
		&& compareDecimalIndexes(maxIndexedPort[0], String(normalizedMinRuleItemsCount)) > 0;
	const hasLastReservedPort = portsByIndex.has(String(normalizedMinRuleItemsCount));
	let trailingPlaceholder = null;
	if (hasPortBeyondReserve || hasLastReservedPort)
	{
		const trailingIndex = hasPortBeyondReserve
			? incrementDecimalIndex(maxIndexedPort[0])
			: String(normalizedMinRuleItemsCount + 1);
		const title = `${label}${trailingIndex}`;
		trailingPlaceholder = {
			id: createComplexNodePlaceholderId(blockId, title),
			title,
		};
	}

	const rows = [...reservedRows, ...orderedRestPorts];
	if (trailingPlaceholder)
	{
		rows.push(trailingPlaceholder);
	}

	return {
		rows,
		reservedRows,
		restPorts: orderedRestPorts,
		trailingPlaceholder,
		firstPlaceholderIndex: findFirstComplexNodePlaceholderIndex(rows),
	};
}

export function findFirstComplexNodePlaceholderIndex(
	rows,
)
{
	return rows.findIndex((item) => !isPort(item));
}

function getMinimumActivePort(
	ports,
	portType,
	label,
)
{
	const candidates = [];
	ports.forEach((port) => {
		const index = getTitleIndex(port.title, label);
		if (port.type === portType && port.isActive !== false && index !== null)
		{
			candidates.push({ port, index });
		}
	});
	candidates.sort((left, right) => {
		return compareDecimalIndexes(left.index, right.index) || left.port.id.localeCompare(right.port.id);
	});

	return candidates[0]?.port ?? null;
}

function getNextOutputId(ports)
{
	const maxOutputId = ports.reduce((maxId, port) => {
		if (port.type !== PORT_TYPES.output && port.type !== PORT_TYPES.outputRelation)
		{
			return maxId;
		}

		const match = port.id.match(/^o(\d+)$/);

		if (!match)
		{
			return maxId;
		}

		const index = normalizeDecimalIndex(match[1]);

		return compareDecimalIndexes(index, maxId) > 0 ? index : maxId;
	}, '0');

	return `o${incrementDecimalIndex(maxOutputId)}`;
}

export function buildComplexInsertPortPlan(
	block,
	minRuleItemsCount,
)
{
	if (block?.type !== BLOCK_TYPES.COMPLEX)
	{
		return NOT_APPLICABLE_RESULT;
	}

	const ports = block.ports ?? [];
	const input = getMinimumActivePort(
		ports,
		PORT_TYPES.input,
		COMPLEX_NODE_PORT_LABELS.inputRule,
	);
	if (!input)
	{
		return REJECT_RESULT;
	}

	const output = getMinimumActivePort(
		ports,
		PORT_TYPES.output,
		COMPLEX_NODE_PORT_LABELS.outputRule,
	);
	if (output)
	{
		const selectedInput = clonePort(input);
		const selectedOutput = clonePort(output);

		return Object.freeze({
			status: COMPLEX_INSERT_PORT_PLAN_STATUS.READY,
			input: selectedInput,
			previewOutput: selectedOutput,
			publicationOutput: selectedOutput,
			materialize: false,
		});
	}

	const outputRows = buildComplexNodeRuleRows({
		blockId: block.id,
		ports,
		portType: PORT_TYPES.output,
		label: COMPLEX_NODE_PORT_LABELS.outputRule,
		minRuleItemsCount,
	});
	const placeholder = outputRows.rows[outputRows.firstPlaceholderIndex];
	if (!placeholder || isPort(placeholder))
	{
		return REJECT_RESULT;
	}

	const selectedInput = clonePort(input);
	const previewOutput = Object.freeze({
		...placeholder,
		type: PORT_TYPES.output,
		position: OUTPUT_POSITION,
	});
	const publicationOutput = Object.freeze({
		id: getNextOutputId(ports),
		title: placeholder.title,
		type: PORT_TYPES.output,
		position: OUTPUT_POSITION,
	});

	return Object.freeze({
		status: COMPLEX_INSERT_PORT_PLAN_STATUS.READY,
		input: selectedInput,
		previewOutput,
		publicationOutput,
		materialize: true,
	});
}
