import { BIcon, Outline } from 'ui.icon-set.api.vue';
import { Type } from 'main.core';

import './style.css';
import { InspectorViewItemTypeDict } from '../../../../constants';

/**
 * Header of a collapsible level of the scheme. Controls that belong to a node type go into the
 * `header-controls` slot: a click inside it must not toggle the level.
 */
export const InspectorSchemeCollapsibleItemView = {
	name: 'InspectorSchemeCollapsibleItemView',
	emits: ['toggle'],
	components: {
		BIcon,
	},
	props: {
		item: {
			/** @type InspectorViewItemBase */
			type: Object,
			required: true,
		},
		itemType: {
			/** @type InspectorViewItemType */
			type: String,
			default: '',
		},
		collapsed: {
			type: Boolean,
			default: false,
		},
		hasChildren: {
			type: Boolean,
			default: false,
		},
	},
	computed: {
		itemTitle(): string
		{
			return this.item.text;
		},
		nodeUserTitle(): string
		{
			if (!this.isNode)
			{
				return '';
			}

			return Type.isStringFilled(this.item?.userText) ? this.item.userText : '';
		},
		// Both titles in full: each of them keeps to its own line, so each of them may be truncated.
		nodeTitleHint(): ?string
		{
			if (!this.isNode)
			{
				return null;
			}

			return this.nodeUserTitle === '' ? this.itemTitle : `${this.itemTitle}\n${this.nodeUserTitle}`;
		},
		isGroup(): boolean
		{
			return this.itemType === InspectorViewItemTypeDict.GROUP;
		},
		isSection(): boolean
		{
			return this.itemType === InspectorViewItemTypeDict.SECTION;
		},
		isNode(): boolean
		{
			return this.itemType === InspectorViewItemTypeDict.NODE;
		},
		hasNodeIcon(): boolean
		{
			if (!Type.isStringFilled(this.item?.icon))
			{
				return false;
			}

			return Outline[this.item.icon] ?? false;
		},
		hasGroupIcon(): boolean
		{
			return Type.isStringFilled(this.item?.icon);
		},
		nodeIconName(): string
		{
			if (Type.isStringFilled(this.item?.icon))
			{
				return Outline[this.item.icon];
			}

			return Outline.FILE;
		},
		collapseIconName(): string
		{
			return this.collapsed ? Outline.CHEVRON_RIGHT_L : Outline.CHEVRON_DOWN_L;
		},
		typeClass(): string
		{
			return `--${this.itemType}`;
		},
		// A node is listed once as itself and once per output or child activity of its own, all under the
		// same item id, so such a header names its port or activity on top of the id and the anchors stay
		// one per element. A level with no id of its own is not addressable by one and takes no anchor.
		headerTestId(): ?string
		{
			if (!Type.isStringFilled(this.item?.id))
			{
				return null;
			}

			const suffix = [this.item.outputPortId, this.item.activityName].find((part) => Type.isStringFilled(part));

			return suffix
				? this.$testId('nodeDataInspectorSchemeItemHeader', this.item.id, suffix)
				: this.$testId('nodeDataInspectorSchemeItemHeader', this.item.id);
		},
		// levels grouping the nodes of a port carry no type of their own, and an empty suffix would
		// leave the anchor hanging on a dash
		titleTestId(): string
		{
			return Type.isStringFilled(this.itemType)
				? this.$testId('nodeDataInspectorSchemeItemTitle', this.itemType)
				: this.$testId('nodeDataInspectorSchemeItemTitle');
		},
	},
	template: `
		<div
			class="inspector-scheme-view__collapsible-header"
			:class="typeClass"
			:data-test-id="headerTestId"
		>
			<div
				v-if="hasChildren"
				class="inspector-scheme-view__collapsible-header__toggle-button"
				@click="$emit('toggle')"
			>
				<BIcon :name="collapseIconName" :size="16" />
			</div>
			<template v-if="isGroup">
				<div class="inspector-scheme-view__collapsible-item-group-title">
					<BIcon v-if="hasGroupIcon" :name="item.icon" :size="24"/>
					<span class="inspector-scheme-view__collapsible-group-item-title">{{ item.text }}</span>
				</div>
			</template>
			<template v-else>
				<div v-if="isNode" class="inspector-scheme-view__collapsible-header__icon">
					<BIcon :name="nodeIconName" :size="20"/>
				</div>
				<div class="inspector-scheme-view__collapsible-item-titles" :class="typeClass">
					<span
						class="inspector-scheme-view__collapsible-item-title"
						:class="typeClass"
						:title="nodeTitleHint"
						:data-test-id="titleTestId"
					>{{ item.text }}</span>
					<span
						v-if="nodeUserTitle"
						class="inspector-scheme-view__collapsible-item-user-title"
						:title="nodeTitleHint"
						:data-test-id="$testId('nodeDataInspectorSchemeNodeUserTitle')"
					>{{ nodeUserTitle }}</span>
				</div>
			</template>
			<div
				v-if="$slots['header-controls']"
				class="inspector-scheme-view__collapsible-header__controls"
				@click.stop
			>
				<slot name="header-controls" :item="item"/>
			</div>
		</div>
	`,
};
