import { Dom, Loc, Text, Type } from 'main.core';
import { LiveAnnouncer } from 'ui.a11y';
import { AirButtonStyle, Button } from 'ui.buttons';
import { MessageBox } from 'ui.dialogs.messagebox';
import { BIcon, Outline } from 'ui.icon-set.api.vue';
import { UI } from 'ui.notification';
import { Dialog } from 'ui.system.dialog';
import { markRaw } from 'ui.vue3';

import { diagramStore } from '../../../entities/blocks';
import {
	type ActiveRun,
	type TestRunDocument,
	type TestRunDocumentPayload,
	type TestRunField,
	formatActiveRunStartTime,
	TestRunErrorCode,
	useTestRunStore,
} from '../../../entities/test-run';
import {
	findDialogPopup,
	getErrorCode,
	getErrorCustomData,
	getErrorMessage,
	handleResponseError,
	isRequiredField,
	toSafeLinkUrl,
} from '../../../shared/utils';
import { DocumentSourceControl } from './document-source-control';
import { TEST_RUN_ERROR_ID, TestRunForm } from './test-run-form';
import './test-run-dialog.css';

const DIALOG_WIDTH = 560;
const DIALOG_VIEWPORT_GAP = 32;
const DIALOG_POPUP_CLASS = 'bizprocdesigner-test-run-popup';
const NOTIFICATION_DELAY = 4000;

/** Emptiness as bizproc reads it: `0` and `'0'` are values, and only a missing or blank one is not. */
function isEmptyFieldValue(value: mixed): boolean
{
	if (Type.isArray(value))
	{
		return value.every((item: mixed): boolean => isEmptyFieldValue(item));
	}

	return Type.isNil(value) || value === '';
}

function findEmptyRequiredFields(fields: TestRunField[], values: { [fieldName: string]: mixed }): string[]
{
	return fields
		.filter((field: TestRunField): boolean => isRequiredField(field) && isEmptyFieldValue(values[field.name]))
		.map((field: TestRunField): string => field.name)
	;
}

// @vue/component
export const TestRunDialog = {
	name: 'TestRunDialog',
	components: { BIcon, DocumentSourceControl, TestRunForm },
	setup(): Object
	{
		return {
			diagram: diagramStore(),
			testRunStore: useTestRunStore(),
			errorId: TEST_RUN_ERROR_ID,
			iconSet: Outline,
		};
	},
	data(): {
		instance: Dialog | null,
		primaryButton: Button | null,
		activeRun: ActiveRun | null,
		invalidFieldNames: string[],
		invalidDocumentFieldNames: string[],
		startErrorMessage: string,
		createdDocumentUrl: string,
		isCreateRetryBlocked: boolean,
		isDocumentSelectionMissing: boolean,
		isFinishing: boolean,
		isFormRendered: boolean,
		isDocumentFormRendered: boolean,
		isTriggerDataExpanded: boolean,
		isPrimaryFocusToRestore: boolean,
		}
	{
		return {
			instance: null,
			primaryButton: null,
			activeRun: null,
			invalidFieldNames: [],
			invalidDocumentFieldNames: [],
			startErrorMessage: '',
			createdDocumentUrl: '',
			isCreateRetryBlocked: false,
			isDocumentSelectionMissing: false,
			isFinishing: false,
			isFormRendered: false,
			isDocumentFormRendered: false,
			isTriggerDataExpanded: false,
			isPrimaryFocusToRestore: false,
		};
	},
	computed: {
		blockId(): string
		{
			return this.testRunStore.dialogBlockId ?? '';
		},
		fields(): TestRunField[]
		{
			return this.testRunStore.form?.returnFields ?? [];
		},
		hasFields(): boolean
		{
			return this.fields.length > 0;
		},
		runDocument(): TestRunDocument | null
		{
			return this.testRunStore.form?.document ?? null;
		},
		// A scheme of the `Workflow` type carries triggers of documents of modules, so the controls are
		// drawn by the document type of the trigger and not by the one of the template.
		documentType(): string[]
		{
			return this.testRunStore.form?.documentType ?? [];
		},
		hasDocumentSection(): boolean
		{
			return Boolean(this.runDocument) && this.runDocument.source !== 'none';
		},
		hasDocumentCreateFields(): boolean
		{
			return this.hasDocumentSection
				&& this.runDocument.canCreate
				&& this.runDocument.createFields.length > 0
			;
		},
		formKey(): string
		{
			return `${this.blockId}:${this.testRunStore.form?.draftRevision ?? 0}`;
		},
		triggerTitle(): string
		{
			return this.testRunStore.form?.trigger?.title ?? '';
		},
		isActiveRunShown(): boolean
		{
			return this.activeRun !== null;
		},
		isPreparing(): boolean
		{
			return this.testRunStore.form === null && !this.isActiveRunShown;
		},
		hasInvalidFields(): boolean
		{
			return this.invalidFieldNames.length > 0 || this.invalidDocumentFieldNames.length > 0;
		},
		formErrorText(): string
		{
			if (this.startErrorMessage !== '')
			{
				return this.startErrorMessage;
			}

			if (this.isDocumentSelectionMissing)
			{
				return this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DOCUMENT_REQUIRED_ERROR');
			}

			return this.hasInvalidFields ? this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_REQUIRED_FIELDS_ERROR') : '';
		},
		startErrorDocumentLink(): string
		{
			return toSafeLinkUrl(this.createdDocumentUrl);
		},
		activeRunDescription(): string
		{
			return this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_DESCRIPTION', {
				'#TIME#': formatActiveRunStartTime(this.activeRun),
			});
		},
		primaryButtonText(): string
		{
			return this.loc(
				this.isActiveRunShown
					? 'BIZPROCDESIGNER_EDITOR_TEST_RUN_BUTTON_FINISH'
					: 'BIZPROCDESIGNER_EDITOR_TEST_RUN_BUTTON_START',
			);
		},
		isPrimaryButtonDisabled(): boolean
		{
			return this.testRunStore.isStarting
				|| this.isFinishing
				|| this.isPreparing
				|| (this.hasFields && !this.isFormRendered)
				|| (this.hasDocumentCreateFields && !this.isDocumentFormRendered)
				|| this.isCreateRetryBlocked
			;
		},
	},
	watch: {
		blockId(): void
		{
			// The item of another node lands in the window that is already open.
			if (this.testRunStore.isDialogOpen)
			{
				void this.prepareRun();
			}
		},
		formKey(): void
		{
			// A new key mounts a new form, and its controls are waited for anew.
			this.isFormRendered = false;
			this.isDocumentFormRendered = false;
		},
		primaryButtonText(text: string): void
		{
			this.primaryButton?.setText(text);
		},
		isPrimaryButtonDisabled(disabled: boolean): void
		{
			const container = this.primaryButton?.getContainer();
			if (disabled)
			{
				this.isPrimaryFocusToRestore = container === document.activeElement;
			}

			this.primaryButton?.setDisabled(disabled);

			// `setDisabled` takes the button out of the tab order along with the focus that was on it,
			// while the window stays open: without this the focus is left on `body`.
			if (!disabled && this.isPrimaryFocusToRestore && document.activeElement === document.body)
			{
				container.focus();
			}
		},
	},
	async mounted(): Promise<void>
	{
		// The window appears only once the run is prepared, and the popup takes the content only on show:
		// until then the content stays out of the markup of the editor. The root stays in place,
		// because Vue patches the parent of the root when the editor unmounts the dialog.
		Dom.remove(this.$refs.content);

		await this.prepareRun();
	},
	unmounted(): void
	{
		this.popupResizeObserver?.disconnect();
		this.instance?.hide();
	},
	methods: {
		loc(phraseCode: string, replacements: { [string]: string } | null = null): string
		{
			return Loc.getMessage(phraseCode, replacements) ?? '';
		},
		isOpenFor(blockId: string): boolean
		{
			return this.testRunStore.dialogBlockId === blockId;
		},
		async prepareRun(): Promise<void>
		{
			const blockId = this.blockId;
			LiveAnnouncer.announce(this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_PREPARING_ANNOUNCE'));

			// The draft on the server is what the run executes, so it must match the scheme on the screen.
			const isSaved = await this.diagram.saveDraftWithStatus();
			if (!this.isOpenFor(blockId))
			{
				return;
			}

			if (!isSaved)
			{
				this.close();

				return;
			}

			await this.load();

			// The window is placed by the size of its content, so the content has to be rendered by then.
			await this.$nextTick();
			if (this.isOpenFor(blockId))
			{
				this.showDialog();
			}
		},
		async load(): Promise<void>
		{
			const blockId = this.blockId;
			this.activeRun = null;
			this.resetInvalidFields();
			this.createdDocumentUrl = '';
			this.isCreateRetryBlocked = false;

			try
			{
				const form = await this.testRunStore.prepare(blockId);
				if (!this.isOpenFor(blockId))
				{
					return;
				}

				if (form === null)
				{
					this.close();

					return;
				}

				this.isTriggerDataExpanded = !this.hasDocumentSection;
			}
			catch (error)
			{
				if (this.isOpenFor(blockId))
				{
					this.handlePrepareError(error);
				}
			}
		},
		handlePrepareError(error: Object): void
		{
			const code = getErrorCode(error);

			if (code === TestRunErrorCode.activeRunExists)
			{
				this.activeRun = getErrorCustomData(error)?.activeRun ?? null;
			}

			if (this.isActiveRunShown)
			{
				return;
			}

			if (code === TestRunErrorCode.triggerNotSupported)
			{
				MessageBox.alert(this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_TRIGGER_NOT_SUPPORTED'));
			}
			else
			{
				handleResponseError(error);
			}

			this.close();
		},
		showDialog(): void
		{
			if (this.instance)
			{
				return;
			}

			this.primaryButton = markRaw(this.createPrimaryButton());
			this.instance = markRaw(this.createDialog(this.primaryButton));
			this.instance.setContent(this.$refs.content);
			this.instance.show();
			this.fitPopupIntoViewport();
		},
		fitPopupIntoViewport(): void
		{
			const popup = findDialogPopup(this.$refs.content);
			if (!popup)
			{
				return;
			}

			const container = popup.getPopupContainer();
			Dom.addClass(container, DIALOG_POPUP_CLASS);
			// The popup is centered once on show, while the form keeps growing and shrinking after it.
			this.popupResizeObserver = new ResizeObserver(() => popup.adjustPosition());
			this.popupResizeObserver.observe(container);
		},
		createPrimaryButton(): Button
		{
			const primary = new Button({
				text: this.primaryButtonText,
				useAirDesign: true,
				style: AirButtonStyle.FILLED,
				dataset: { testid: 'bizprocdesigner-editor-test-run-primary' },
			});
			primary.setDisabled(this.isPrimaryButtonDisabled);
			primary.bindEvent('click', () => {
				void this.onPrimaryClick();
			});

			return primary;
		},
		createDialog(primaryButton: Button): Dialog
		{
			const cancel = new Button({
				text: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_BUTTON_CANCEL'),
				useAirDesign: true,
				style: AirButtonStyle.OUTLINE,
				dataset: { testid: 'bizprocdesigner-editor-test-run-cancel' },
			});
			cancel.bindEvent('click', () => {
				this.close();
			});

			return new Dialog({
				title: this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DIALOG_TITLE'),
				centerButtons: [primaryButton, cancel],
				events: {
					onHide: this.close,
				},
				width: Math.min(DIALOG_WIDTH, window.innerWidth - DIALOG_VIEWPORT_GAP),
				// Every click on the scheme lands outside the window, and the run is filled in by hand.
				closeByClickOutside: false,
			});
		},
		async onPrimaryClick(): Promise<void>
		{
			if (this.isActiveRunShown)
			{
				await this.finishActiveRun();

				return;
			}

			await this.startRun();
		},
		async finishActiveRun(): Promise<void>
		{
			const blockId = this.blockId;
			const expectedSessionId = this.activeRun?.sessionId ?? null;
			this.isFinishing = true;

			try
			{
				// The store finishes the run it holds, and only the status fills it: the refusal of
				// `prepare` brought the summary to the dialog and not to the store.
				await this.testRunStore.loadStatus();
				if (expectedSessionId !== null && this.testRunStore.activeRun?.sessionId === expectedSessionId)
				{
					await this.testRunStore.finish(expectedSessionId);
				}
				else
				{
					UI.Notification.Center.notify({
						content: Text.encode(this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_CHANGED')),
						autoHideDelay: NOTIFICATION_DELAY,
					});
				}
			}
			finally
			{
				this.isFinishing = false;
			}

			if (this.isOpenFor(blockId))
			{
				await this.load();
			}
		},
		async startRun(): Promise<void>
		{
			const blockId = this.blockId;
			const values = this.$refs.runForm?.collectValues() ?? {};
			const documentPayload = this.$refs.documentControl?.collectDocument() ?? null;
			this.resetInvalidFields();
			this.invalidFieldNames = findEmptyRequiredFields(this.fields, values);
			this.invalidDocumentFieldNames = documentPayload?.source === 'create'
				? findEmptyRequiredFields(this.runDocument.createFields, documentPayload.fields)
				: []
			;

			if (this.hasInvalidFields)
			{
				await this.focusFirstInvalidField();

				return;
			}

			if (documentPayload?.source === 'select' && Type.isNil(documentPayload.documentId))
			{
				this.isDocumentSelectionMissing = true;
				await this.focusFirstInvalidField();

				return;
			}

			// The run goes on the draft the form was prepared on: a scheme edited since then is refused.
			const { draftId, draftRevision } = this.testRunStore.form;

			try
			{
				const startedRun = await this.testRunStore.start({
					blockId,
					draftId,
					draftRevision,
					values,
					...this.getDocumentPayload(documentPayload),
				});

				if (startedRun !== null)
				{
					LiveAnnouncer.announce(this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_STARTED_ANNOUNCE'));
				}
			}
			catch (error)
			{
				// A value the server could not read is corrected in the same form, so the window stays.
				if (getErrorCode(error) === TestRunErrorCode.invalidValues && this.isOpenFor(blockId))
				{
					await this.markInvalidValues(error);

					return;
				}

				if (this.isOpenFor(blockId) && await this.showDocumentError(error, documentPayload?.source ?? null))
				{
					return;
				}

				this.reportStartError(error);
			}

			this.close();
		},
		async markInvalidValues(error: Object): Promise<void>
		{
			const customFieldNames = getErrorCustomData(error)?.fields;
			const fieldNames: string[] = Type.isArray(customFieldNames) ? customFieldNames : [];
			const documentFields = this.$refs.documentControl?.isCreate ? this.runDocument.createFields : [];
			const hasField = (fields: TestRunField[], name: string): boolean => {
				return fields.some((field: TestRunField): boolean => field.name === name);
			};

			this.startErrorMessage = getErrorMessage(error) ?? '';
			this.invalidFieldNames = fieldNames.filter((name: string): boolean => hasField(this.fields, name));
			this.invalidDocumentFieldNames = fieldNames.filter((name: string): boolean => hasField(documentFields, name));

			await this.focusFirstInvalidField();
		},
		async focusFirstInvalidField(): Promise<void>
		{
			if (this.invalidFieldNames.length > 0)
			{
				this.isTriggerDataExpanded = true;
			}

			await this.$nextTick();
			if (!this.$refs.documentControl?.focusFirstInvalidField())
			{
				this.$refs.runForm?.focusFirstInvalidField();
			}
		},
		getDocumentPayload(document: TestRunDocumentPayload | null): { document?: TestRunDocumentPayload }
		{
			return document === null ? {} : { document };
		},
		async showDocumentError(error: Object, documentSource: string | null): Promise<boolean>
		{
			const { documentId, documentUrl } = getErrorCustomData(error) ?? {};
			const isStartFailedOnDocument = getErrorCode(error) === TestRunErrorCode.startFailed
				&& (Type.isStringFilled(documentUrl) || Type.isArray(documentId))
			;
			if (!this.isDocumentError(error) && !isStartFailedOnDocument)
			{
				return false;
			}

			if (isStartFailedOnDocument)
			{
				this.createdDocumentUrl = Type.isStringFilled(documentUrl) ? documentUrl : '';
				if (documentSource === 'create')
				{
					this.isCreateRetryBlocked = !this.selectCreatedDocument(documentId);
					await this.$nextTick();
				}
			}

			this.startErrorMessage = getErrorMessage(error) ?? '';

			return true;
		},
		selectCreatedDocument(documentId: mixed): boolean
		{
			const localId = Type.isArray(documentId) ? documentId[2] : null;

			return (Type.isStringFilled(localId) || Type.isNumber(localId))
				&& (this.$refs.documentControl?.selectDocument(String(localId)) ?? false)
			;
		},
		isDocumentError(error: Object): boolean
		{
			return [TestRunErrorCode.documentCreateFailed, TestRunErrorCode.documentNotFound]
				.includes(getErrorCode(error))
			;
		},
		reportStartError(error: Object): void
		{
			if (getErrorCode(error) === TestRunErrorCode.draftChanged)
			{
				UI.Notification.Center.notify({
					content: Text.encode(this.loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_DRAFT_CHANGED')),
					autoHideDelay: NOTIFICATION_DELAY,
				});

				return;
			}

			handleResponseError(error);
		},
		resetInvalidFields(): void
		{
			this.invalidFieldNames = [];
			this.invalidDocumentFieldNames = [];
			this.startErrorMessage = '';
			this.isDocumentSelectionMissing = false;
		},
		close(): void
		{
			this.testRunStore.closeDialog();
		},
	},
	template: `
		<div hidden>
			<div
				ref="content"
				class="bizprocdesigner-test-run"
				data-testid="bizprocdesigner-editor-test-run"
			>
				<template v-if="isActiveRunShown">
					<div class="bizprocdesigner-test-run__title">
						{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_ACTIVE_RUN_TITLE') }}
					</div>
					<div
						class="bizprocdesigner-test-run__description"
						data-testid="bizprocdesigner-editor-test-run-active-run"
					>{{ activeRunDescription }}</div>
				</template>
				<template v-else-if="hasFields || hasDocumentSection">
					<div
						v-if="formErrorText || startErrorDocumentLink"
						:id="errorId"
						class="bizprocdesigner-test-run__error"
						data-testid="bizprocdesigner-editor-test-run-error"
						role="alert"
					>
						{{ formErrorText }}
						<a
							v-if="startErrorDocumentLink"
							:href="startErrorDocumentLink"
							data-testid="bizprocdesigner-editor-test-run-error-document-link"
						>{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_START_FAILED_DOCUMENT_LINK') }}</a>
					</div>
					<DocumentSourceControl
						v-if="hasDocumentSection"
						ref="documentControl"
						:key="formKey"
						:document="runDocument"
						:document-type="documentType"
						:invalid-field-names="invalidDocumentFieldNames"
						:is-selection-invalid="isDocumentSelectionMissing"
						@change="resetInvalidFields"
						@rendered="isDocumentFormRendered = true"
					/>
					<template v-if="hasFields">
						<button
							type="button"
							class="bizprocdesigner-test-run__title bizprocdesigner-test-run__section-toggle"
							:aria-expanded="isTriggerDataExpanded ? 'true' : 'false'"
							aria-controls="bizprocdesigner-test-run-trigger-data"
							data-testid="bizprocdesigner-editor-test-run-trigger-data-toggle"
							@click="isTriggerDataExpanded = !isTriggerDataExpanded"
						>
							<BIcon :name="isTriggerDataExpanded ? iconSet.CHEVRON_DOWN_M : iconSet.CHEVRON_RIGHT_M" :size="18"/>
							{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_FIELDS_TITLE') }}
						</button>
						<div
							v-show="isTriggerDataExpanded"
							id="bizprocdesigner-test-run-trigger-data"
							class="bizprocdesigner-test-run__section"
						>
							<div v-if="triggerTitle" class="bizprocdesigner-test-run__description">{{ triggerTitle }}</div>
							<TestRunForm
								ref="runForm"
								:key="formKey"
								:fields="fields"
								:document-type="documentType"
								:invalid-field-names="invalidFieldNames"
								@change="resetInvalidFields"
								@rendered="isFormRendered = true"
							/>
						</div>
					</template>
				</template>
				<div
					v-else-if="isPreparing"
					class="bizprocdesigner-test-run__description"
					data-testid="bizprocdesigner-editor-test-run-preparing"
				>
					{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_PREPARING_ANNOUNCE') }}
				</div>
				<div
					v-else
					class="bizprocdesigner-test-run__description"
					data-testid="bizprocdesigner-editor-test-run-empty"
				>
					{{ loc('BIZPROCDESIGNER_EDITOR_TEST_RUN_NO_FIELDS') }}
				</div>
			</div>
		</div>
	`,
};
