import { Type } from 'main.core';
import { Groupable, ResizableBlock } from 'ui.block-diagram';
import { Outline } from 'ui.icon-set.api.vue';
import { type MenuItemOptions } from 'ui.vue3.components.menu';

import { IconDivider, IconButton } from '../../../../shared/ui';
import {
	BlockContainer,
	BlockLayout,
	BLOCK_LAYOUT_SLOT_NAMES,
	ColorMenuTopBtn,
	// ContentSeparator,
	FRAME_BG_COLORS,
	FRAME_BORDER_COLORS,
	FRAME_TEXT_ALIGN_OPTIONS,
	SEPARATOR_SIZE,
	getContextMenuName,
} from '../../../../entities/blocks';
import {
	DeleteBlockIconBtn,
	UpdatePublishedStatusLabel,
	ChangeFrameColorTopBtn,
	ChangeFrameTextAlignTopBtn,
	EditFrameContent,
	ChangeEditFrameContentTopBtn,
	EditNodeTitle,
} from '../../../../features/blocks';
import { useEditFrameContent } from '../../../../features/blocks/composables/use-edit-frame-content';
import { BlockLayoutWidget } from '../block-layout/block-layout';

import { type Block } from '../../../../shared/types';

import { BlockMediator } from '../../lib';

import './block-frame.css';

type Props = {
	block: Block,
	dragPreview?: boolean,
};

type Setup = {
	iconSet: { [string]: string },
	blockMediator: BlockMediator,
};

const MIN_CONTENT_SIZE = 380;
const DRAG_PREVIEW_INSET = 24;
const FRAME_TEXT_CONTENT_SELECTOR = '[data-bizprocdesigner-frame-text-content]';
const FRAME_TEXT_EDITOR_SELECTOR = '.editor-chart-text-editor__editor-content';
const SCROLLABLE_OVERFLOW_VALUES = new Set(['auto', 'scroll']);
const OVERLAY_SCROLLBAR_SIZE = 12;

export const BlockFrame = {
	name: 'BlockFrame',
	components: {
		Groupable,
		ResizableBlock,
		BlockContainer,
		BlockLayout,
		BlockLayoutWidget,
		EditNodeTitle,
		DeleteBlockIconBtn,
		UpdatePublishedStatusLabel,
		IconDivider,
		IconButton,
		ColorMenuTopBtn,
		ChangeFrameColorTopBtn,
		ChangeFrameTextAlignTopBtn,
		// ContentSeparator,
		EditFrameContent,
		ChangeEditFrameContentTopBtn,
	},
	props: {
		/** @type Block */
		block: {
			type: Object,
			required: true,
		},
		dragPreview: {
			type: Boolean,
			default: false,
		},
	},
	setup(props: Props): Setup
	{
		// const { zoom } = useBlockDiagram();

		const { editFrameContent } = useEditFrameContent();

		return {
			iconSet: Outline,
			editFrameContent,
			blockMediator: new BlockMediator(),
			frameBgColors: FRAME_BG_COLORS,
			frameBorderColors: FRAME_BORDER_COLORS,
			getContextMenuName,
			blockLayoutSlotNames: BLOCK_LAYOUT_SLOT_NAMES,
			// zoom,
		};
	},
	computed: {
		dragPreviewInset(): number
		{
			return this.dragPreview ? DRAG_PREVIEW_INSET : 0;
		},
		frameTextAlign(): string
		{
			return this.block?.node?.frameTextAlign ?? FRAME_TEXT_ALIGN_OPTIONS.NONE;
		},
		contextMenuItems(): Array<MenuItemOptions>
		{
			return this.blockMediator.getFrameBlockMenuOptions(this.block);
		},
		frameWidth(): number
		{
			return this.block.dimensions.width;
		},
		frameHeight(): number
		{
			return this.block.dimensions.height;
		},
		preparedFrameMinWith(): number
		{
			return (
				this.frameTextAlign === FRAME_TEXT_ALIGN_OPTIONS.LEFT
				|| this.frameTextAlign === FRAME_TEXT_ALIGN_OPTIONS.RIGHT
			)
				? MIN_CONTENT_SIZE + SEPARATOR_SIZE
				: MIN_CONTENT_SIZE;
		},
		preparedFrameMinHeight(): number
		{
			return (
				this.frameTextAlign === FRAME_TEXT_ALIGN_OPTIONS.TOP
				|| this.frameTextAlign === FRAME_TEXT_ALIGN_OPTIONS.BOTTOM
			)
				? MIN_CONTENT_SIZE + SEPARATOR_SIZE
				: MIN_CONTENT_SIZE;
		},
	},
	methods: {
		canStartFrameMove(event: MouseEvent): boolean
		{
			const target = this.getEventTargetElement(event.target);

			if (target === null)
			{
				return true;
			}

			if (this.isFrameTextMoveBlocked(event, target))
			{
				event.stopPropagation();

				return false;
			}

			return true;
		},
		getEventTargetElement(target: EventTarget | null): HTMLElement | null
		{
			if (Type.isElementNode(target))
			{
				return target;
			}

			if (Type.isDomNode(target) && Type.isElementNode(target.parentElement))
			{
				return target.parentElement;
			}

			return null;
		},
		isFrameTextMoveBlocked(event: MouseEvent, target: HTMLElement): boolean
		{
			const frameTextContent = target.closest(FRAME_TEXT_CONTENT_SELECTOR);
			if (!Type.isElementNode(frameTextContent))
			{
				return false;
			}

			if (target.closest(FRAME_TEXT_EDITOR_SELECTOR))
			{
				return true;
			}

			let current = target;
			while (Type.isElementNode(current) && frameTextContent.contains(current))
			{
				if (this.isElementScrollbarEvent(event, current))
				{
					return true;
				}

				current = current.parentElement;
			}

			return false;
		},
		isElementScrollbarEvent(event: MouseEvent, element: HTMLElement): boolean
		{
			const { direction, overflowX, overflowY } = getComputedStyle(element);
			const rect = element.getBoundingClientRect();
			const scaleX = this.getElementScale(rect.width, element.offsetWidth);
			const scaleY = this.getElementScale(rect.height, element.offsetHeight);

			if (SCROLLABLE_OVERFLOW_VALUES.has(overflowY) && element.scrollHeight > element.clientHeight)
			{
				const scrollbarWidth = (element.offsetWidth - element.clientWidth || OVERLAY_SCROLLBAR_SIZE) * scaleX;
				const isVerticalScrollbar = direction === 'rtl'
					? event.clientX <= rect.left + scrollbarWidth
					: event.clientX >= rect.right - scrollbarWidth;

				if (
					isVerticalScrollbar
					&& event.clientX >= rect.left
					&& event.clientX <= rect.right
					&& event.clientY >= rect.top
					&& event.clientY <= rect.bottom
				)
				{
					return true;
				}
			}

			if (SCROLLABLE_OVERFLOW_VALUES.has(overflowX) && element.scrollWidth > element.clientWidth)
			{
				const scrollbarHeight = (element.offsetHeight - element.clientHeight || OVERLAY_SCROLLBAR_SIZE) * scaleY;

				if (
					event.clientY >= rect.bottom - scrollbarHeight
					&& event.clientY <= rect.bottom
					&& event.clientX >= rect.left
					&& event.clientX <= rect.right
				)
				{
					return true;
				}
			}

			return false;
		},
		getElementScale(rectSize: number, offsetSize: number): number
		{
			return rectSize > 0 && offsetSize > 0 ? rectSize / offsetSize : 1;
		},
		// The handler takes the gesture on the frame body as a whole, so the neighbours inside the
		// body stop it themselves: the toolbar in entities/blocks/ui/block-layout and the title in
		// entities/blocks/ui/node-title. A double click on the text of an open editor - where it
		// selects a word - does reach here, and the entry point ignores a frame already being edited.
		onDblClick(event: MouseEvent): void
		{
			event.stopPropagation();

			this.editFrameContent(this.block.id);
		},
	},
	template: `
		<Groupable :block="block">
			<ResizableBlock
				:block="block"
				:minHeight="preparedFrameMinHeight"
				:minWidth="preparedFrameMinWith"
				:canStartMove="canStartFrameMove"
			>
				<template #default="{ isHighlighted, isResize, isDragged, isDisabled, isMakeNewConnection, width, height }">
					<BlockContainer
						class="bizprocdesigner-block-frame"
						:class="{ '--drag-preview': dragPreview }"
						:style="dragPreview ? { '--drag-preview-inset': dragPreviewInset + 'px' } : null"
						:highlighted="(isHighlighted || isResize) && !isDragged"
						:disabled="isDisabled"
						:hoverable="!isMakeNewConnection"
						:contextMenuItems="contextMenuItems"
						:backgroundColor="frameBgColors[block.node.frameColorName]"
						:borderColor="frameBorderColors[block.node.frameColorName]"
						@mouseup="blockMediator.handleMouseUp($event, block)"
						@mousedown="blockMediator.handleMouseDown($event)"
						@dblclick="onDblClick"
					>
						<BlockLayoutWidget
							:data-testid="$testId('bizprocdesigner-block-frame', block.id)"
							:block="block"
							:moreMenuItems="contextMenuItems"
							:dragged="isDragged"
							:resized="isResize"
							:disabled="isDisabled"
							:hoverable="!isMakeNewConnection"
						>
							<template #[blockLayoutSlotNames.TOP_MENU_TITLE]>
								<EditNodeTitle :block="block"/>
							</template>

							<template #[blockLayoutSlotNames.TOP_MENU]>
								<DeleteBlockIconBtn
									:blockId="block.id"
									:disabled="isDisabled"
									@deletedBlock="blockMediator.hideCurrentBlockSettings($event)"
								/>
								<IconDivider/>
								<ChangeEditFrameContentTopBtn :blockId="block.id"/>
								<ChangeFrameTextAlignTopBtn :block="block"/>
								<ChangeFrameColorTopBtn :block="block"/>
							</template>

							<template #[blockLayoutSlotNames.DEFAULT]>
								<!--<ContentSeparator
									v-model:separatorPosition="block.node.frameSeparatorPosition"
									:blockId="block.id"
									:contentPosition="frameTextAlign"
									:width="width"
									:height="height"
									:zoom="zoom"
								>
									<template #content="{ height }">
										<EditFrameContent
											:block="block"
											:height="height"
										/>
									</template>
								</ContentSeparator>-->

								<EditFrameContent
									:block="block"
									:width="width - 2 * dragPreviewInset"
									:height="height - 2 * dragPreviewInset"
									:resizing="isResize"
								/>
							</template>

							<template #[blockLayoutSlotNames.STATUS]>
								<UpdatePublishedStatusLabel :block="block"/>
							</template>
						</BlockLayoutWidget>
					</BlockContainer>
				</template>
			</ResizableBlock>
		</Groupable>
	`,
};
