import { FeatureCode } from 'bizprocdesigner.feature';

import { diagramStore as useDiagramStore } from '../../../entities/blocks';
import { useFeature } from '../../../shared/composables';

/**
 * The one rule that decides whether the lanes of a pool may be edited at all.
 *
 * It is asked three times over a single operation - while the menu is built, when the item or the
 * double click fires, and immediately before the write - because a lease or a flag can be lost
 * between any two of them. Three questions, one rule: a menu that offers what the write refuses is
 * exactly what the repetition guards against.
 */
export function canEditPoolLanes(): boolean
{
	return !useDiagramStore().isWriteLocked
		&& useFeature().isFeatureAvailable(FeatureCode.poolNode)
	;
}
