/**
 * What a lane holds, and what a deletion of one leaves behind.
 *
 * Membership is read from the explicit list of a lane. Geometry only guards a deletion: an activity that
 * stands in a pool without being listed in it refuses the deletion of its lane and withholds the shrink,
 * and is never written into a list here. The refusal to delete, the pool that remains and the moves of
 * the activities are decided here, away from the diagram, so a menu builder and a test get the same answer.
 */

import { Type } from 'main.core';

import { BLOCK_TYPES, isBackdropBlockType } from '../../../shared/constants';
import { type Block, type BlockId } from '../../../shared/types';
import { type PoolLaneModel } from './create-lane-id';
import { insertLineY, lanesWithHeights, poolHeightAfterDelete } from './pool-geometry';
import { isLaneActivity, laneTargetAt } from './pool-lane-membership.ts';

export type LaneDeleteChanges = { pool: Block, updates: Array<Block> };

/**
 * Without `blocks` every filled id counts; with them only the ids of blocks that exist, so a list left
 * with dead ids alone is empty. A list of a malformed shape is never empty.
 */
export function isLaneEmpty(lane: PoolLaneModel, blocks?: Array<Block>): boolean
{
	if (lane.activityIds === undefined)
	{
		return true;
	}

	if (!Array.isArray(lane.activityIds) || lane.activityIds.some((id) => !Type.isStringFilled(id)))
	{
		return false;
	}

	if (!blocks)
	{
		return lane.activityIds.length === 0;
	}

	const existingIds = new Set(blocks.map((block) => block.id));

	return !lane.activityIds.some((id) => existingIds.has(id));
}

/** Activities whose centre lies in the pool - or in its lane `laneIndex` - and no lane of it lists. */
export function unlistedActivityIds(pool: Block, blocks: Array<Block>, laneIndex?: number): Array<BlockId>
{
	const listedIds = new Set((pool.node?.poolLanes ?? []).flatMap((lane) => [...laneActivityIds(lane)]));

	return blocks
		.filter((block) => {
			if (block.id === pool.id || !isLaneActivity(block) || listedIds.has(block.id))
			{
				return false;
			}

			const target = laneTargetAt([pool], { ...block.position, ...block.dimensions });

			return target !== null && (laneIndex === undefined || target.index === laneIndex);
		})
		.map((block) => block.id)
	;
}

/**
 * Whether every lane of the pool declared what it holds - an empty list counts as a declaration - and,
 * given `blocks`, nothing stands in the pool unlisted.
 *
 * A lane that declared nothing is not an empty lane, so there is nothing to carry along with a
 * shrink: shrinking a pool of an unknown composition would leave its nodes below the new bottom edge.
 */
export function isPoolCompositionKnown(pool: Block, blocks?: Array<Block>): boolean
{
	return (pool.node?.poolLanes ?? []).every((lane) => Array.isArray(lane.activityIds))
		&& (!blocks || unlistedActivityIds(pool, blocks).length === 0)
	;
}

export function laneActivityIds(lane: PoolLaneModel): Set<BlockId>
{
	if (!Array.isArray(lane.activityIds))
	{
		return new Set();
	}

	return new Set(lane.activityIds.filter((id) => Type.isStringFilled(id)));
}

/** The lane addressed by its place, looked up by its id in the pool as it stands now. */
export function currentLane(blocks: Array<Block>, pool: Block, laneIndex: number): ?{ pool: Block, index: number }
{
	const laneId = pool.node?.poolLanes?.[laneIndex]?.id;
	const currentPool = blocks.find((block) => block.id === pool.id);
	if (!laneId || currentPool?.type !== BLOCK_TYPES.POOL)
	{
		return null;
	}

	const index = (currentPool.node?.poolLanes ?? []).findIndex((lane) => lane.id === laneId);

	return index === -1 ? null : { pool: currentPool, index };
}

function laneHasUnsupportedContent(lane: PoolLaneModel, blocksById: Map<BlockId, Block>): boolean
{
	if (lane.activityIds !== undefined && (!Array.isArray(lane.activityIds)
		|| lane.activityIds.some((id) => !Type.isStringFilled(id))))
	{
		return true;
	}

	return [...laneActivityIds(lane)].some((id) => {
		const block = blocksById.get(id);

		return block && isBackdropBlockType(block.type);
	});
}

function blocksAfterLaneDelete(oldPool: Block, nextPool: Block, blocks: Array<Block>): ?Array<Block>
{
	const blocksById = new Map(blocks.map((block) => [block.id, block]));
	const remaining = nextPool.node.poolLanes;
	if (remaining.some((lane) => laneHasUnsupportedContent(lane, blocksById)))
	{
		return null;
	}

	const moved = new Set();
	const updates = [];
	for (const [index, lane] of remaining.entries())
	{
		const oldIndex = oldPool.node.poolLanes.findIndex((item) => item.id === lane.id);
		const deltaY = insertLineY(nextPool, index) - insertLineY(oldPool, oldIndex);
		for (const id of laneActivityIds(lane))
		{
			const block = blocksById.get(id);
			if (!block || moved.has(id))
			{
				continue;
			}

			moved.add(id);
			if (deltaY !== 0)
			{
				updates.push({ ...block, position: { ...block.position, y: block.position.y + deltaY } });
			}
		}
	}

	return updates;
}

export function laneDeleteChanges(
	oldPool: Block,
	laneIndex: number,
	blocks: Array<Block>,
): LaneDeleteChanges | 'last-lane' | 'not-empty'
{
	const lanes = oldPool.node.poolLanes;
	if (lanes.length === 1)
	{
		return 'last-lane';
	}

	if (!isLaneEmpty(lanes[laneIndex], blocks) || unlistedActivityIds(oldPool, blocks, laneIndex).length > 0)
	{
		return 'not-empty';
	}

	const remaining = oldPool.node.poolLanes.filter((lane, index) => index !== laneIndex);
	const height = isPoolCompositionKnown(oldPool, blocks)
		? poolHeightAfterDelete(oldPool, laneIndex)
		: oldPool.dimensions.height
	;
	const shrunk = {
		...oldPool,
		dimensions: { ...oldPool.dimensions, height },
		node: { ...oldPool.node, poolLanes: remaining },
	};
	// Heights are reconciled against the pool as it will be, not the one the deletion starts from: a
	// shrink the floor refuses, and the one an unknown composition withholds, leave the body as tall
	// as it was, and the heights of the previous state no longer add up to it. A pool that never
	// saved heights would come back divided by the lane count it no longer has.
	const nextPool = { ...shrunk, node: { ...shrunk.node, poolLanes: lanesWithHeights(shrunk) } };
	const updates = blocksAfterLaneDelete(oldPool, nextPool, blocks);
	if (!updates)
	{
		return 'not-empty';
	}

	return { pool: nextPool, updates };
}
