import { Type } from 'main.core';
import { KEY_TOKEN, useBlockDiagram, type InputState } from 'ui.block-diagram';
import { computed, defineComponent, getCurrentInstance, toValue, type Ref } from 'ui.vue3';

import {
	createConnectionIndex,
	resolveMarkerPosition,
	useNotesStore,
	type NoteConnectionIndex,
	type NoteSchemaConnection,
	type NoteSchemaRect,
	type NotesSchema,
	type TemplateNote,
} from '../../../../entities/notes';
import { NotePreview } from '../../../../features/notes';
import { forgetUnansweredEditorUsers, useEditorUsers } from '../../../../shared/composables';
import { type EditorUser } from '../../../../shared/api';
import { NoteMarker } from '../note-marker/note-marker';

import './notes-layer.css';

/**
 * The camera of the canvas as the layer reads it. A marker lives in the coordinates of the canvas, so
 * the same camera that moves the schema is what puts the marker over its place on the screen.
 */
export type MarkerCamera = {
	x: number,
	y: number,
	zoom: number,
};

/** The area the canvas draws into, in screen pixels. */
export type MarkerViewport = {
	width: number,
	height: number,
};

/** A marker ready to be drawn: the note it stands for and the point of the screen it sits at. */
export type NoteMarkerView = {
	note: TemplateNote,
	x: number,
	y: number,
};

const LAYER_TEST_ID = 'bizprocdesigner-notes-layer';

/**
 * How long the pointer has to stand on a marker before its note is previewed. A schema crossed by the
 * mouse asks the server about nothing: the wait is what tells a glance from an intent to read.
 */
const PREVIEW_DELAY = 300;

/**
 * How long the card outlives the pointer that left the marker. WCAG 1.4.13: the card stands beside
 * its marker and not under it, so a pointer on its way to the card is off both of them for as long
 * as it takes to cross the gap - a card closing at once could never be reached.
 */
const PREVIEW_CLOSE_DELAY = 200;

// Markers just outside the drawn area are kept, so panning does not add and drop them pixel by pixel.
const VIEWPORT_MARGIN = 96;

function isPositive(value: mixed): boolean
{
	return Type.isNumber(value) && value > 0;
}

/**
 * The markers of the visible part of the schema in one pass: a camera that moved needs the whole set
 * counted anew, and the 200 notes of the limit may not cost 200 passes.
 *
 * The canvas draws its own content with the same translation, so a marker keeps its place on the
 * schema while the camera moves. A note whose anchor is missing from the drawn schema falls back to
 * its own coordinates - that is the doing of the anchor utility, and no data of the note changes over
 * it. Nothing travels the other way either: a marker never becomes a part of the graph.
 */
export function selectVisibleMarkers(
	notes: TemplateNote[],
	schema: NotesSchema,
	camera: MarkerCamera,
	viewport: MarkerViewport,
): NoteMarkerView[]
{
	// The canvas has not measured itself yet, so there is no screen to put a marker on.
	if (!isPositive(camera?.zoom) || !isPositive(viewport?.width) || !isPositive(viewport?.height))
	{
		return [];
	}

	const markers: NoteMarkerView[] = [];

	for (const note of notes)
	{
		const point = resolveMarkerPosition(note, schema);
		const x = Math.round((point.x - camera.x) * camera.zoom);
		const y = Math.round((point.y - camera.y) * camera.zoom);

		const isVisible = x >= -VIEWPORT_MARGIN
			&& x <= viewport.width + VIEWPORT_MARGIN
			&& y >= -VIEWPORT_MARGIN
			&& y <= viewport.height + VIEWPORT_MARGIN
		;

		if (isVisible)
		{
			markers.push({ note, x, y });
		}
	}

	return markers;
}

/** The part of the state of the canvas the layer reads: the geometry it draws by and the camera. */
type CanvasState = {
	blocksRectMap: Ref<{ [blockId: string]: NoteSchemaRect }>,
	portsRectMap: Ref<{ [blockId: string]: { [portId: string]: NoteSchemaRect } }>,
	connections: Ref<NoteSchemaConnection[]>,
	transform: Ref<MarkerCamera>,
	canvasWidth: Ref<number>,
	canvasHeight: Ref<number>,
	inputState: InputState,
};

/**
 * The state of the canvas, and only once the canvas itself has built it. It lives in the global
 * properties of the application, and whoever asks for it first is who creates it - a later caller
 * gets what is already there. So asking ahead of the canvas would leave it with a state built without
 * its own options, and its blocks and connections would be dropped without a word. The layer reads a
 * state that exists and draws nothing until it does; the section of the layer therefore belongs after
 * the canvas in the markup of the editor.
 */
function useCanvasState(): CanvasState | null
{
	const app = getCurrentInstance()?.appContext?.app;

	if (!app?.config?.globalProperties?.$blockDiagram)
	{
		return null;
	}

	return useBlockDiagram();
}

/**
 * The layer of the markers above the schema. It lives beside the canvas and not inside it, but within
 * the same application: the geometry of the nodes and the ports is only reachable from there.
 */
export const NotesLayer = defineComponent({
	name: 'BizprocdesignerNotesLayer',
	components: { NoteMarker, NotePreview },
	props: {
		// the template the notes belong to: the preview renders their text with the same editor the
		// conversation is written in, and that editor resolves mentions against the template
		templateId: {
			type: Number,
			required: true,
		},
	},
	setup(): Object
	{
		const notesStore = useNotesStore();
		const canvas = useCanvasState();
		const { users, ensureUsers } = useEditorUsers();

		/**
		 * The index of the connections is owed to the set of the connections and to nothing else: a
		 * camera that moved leaves it as it is, so a frame of a drag pays for the notes alone.
		 */
		const connectionIndex = computed((): NoteConnectionIndex => (
			canvas === null ? createConnectionIndex([]) : createConnectionIndex(toValue(canvas.connections))
		));

		const viewport = computed((): MarkerViewport => (
			canvas === null
				? { width: 0, height: 0 }
				: { width: toValue(canvas.canvasWidth), height: toValue(canvas.canvasHeight) }
		));

		const markers = computed((): NoteMarkerView[] => {
			if (canvas === null)
			{
				return [];
			}

			return selectVisibleMarkers(
				notesStore.notes,
				{
					nodeRects: toValue(canvas.blocksRectMap),
					portRects: toValue(canvas.portsRectMap),
					connections: toValue(canvas.connections),
					connectionIndex: connectionIndex.value,
				},
				toValue(canvas.transform),
				viewport.value,
			);
		});

		return {
			notesStore,
			markers,
			viewport,
			users,
			ensureUsers,
			// The keyboard of the canvas as the card reads it: Escape over an open card belongs to it.
			inputState: canvas?.inputState ?? null,
		};
	},
	data(): Object
	{
		return {
			previewNoteId: null,
		};
	},
	computed: {
		openedNoteId(): number | null
		{
			return this.notesStore.openedNoteId;
		},
		/**
		 * The marker the card stands beside, if there is one. A note whose thread is open has nothing
		 * to preview - the conversation itself is already on the screen - and a marker carried off the
		 * drawn area by the camera takes its card with it.
		 */
		previewMarker(): NoteMarkerView | null
		{
			if (this.previewNoteId === null || this.previewNoteId === this.openedNoteId)
			{
				return null;
			}

			return this.markers.find(
				(marker: NoteMarkerView) => marker.note.id === this.previewNoteId,
			) ?? null;
		},
		// Whether there is a card on the screen at all. A note asked for is not a card drawn: the
		// thread of that note may be open already, and the camera may have carried its marker off the
		// drawn area.
		isPreviewShown(): boolean
		{
			return this.previewMarker !== null;
		},
		// The point the marker is pinned by: the card works the pin around it out on its own and opens
		// beside that, so the marker it speaks of stays uncovered.
		previewAnchor(): { x: number, y: number }
		{
			return {
				x: this.previewMarker?.x ?? 0,
				y: this.previewMarker?.y ?? 0,
			};
		},
		notes(): TemplateNote[]
		{
			return this.notesStore.notes;
		},
		layerTestId(): string
		{
			return this.$testId(LAYER_TEST_ID);
		},
	},
	watch: {
		// The authors are owed to the set of the notes and not to the camera: a schema being dragged
		// redraws every marker of it and asks the portal about nobody.
		notes: {
			immediate: true,
			handler(): void
			{
				void this.loadAuthors();
			},
		},
		/**
		 * WCAG 1.4.13. An open card is dismissed by Escape without the pointer moving anywhere. The
		 * key is taken through the exclusive stack of the canvas, so the press that closes the card
		 * is not the press that leaves the mode of the notes as well: the claim of the card lies over
		 * the one of the mode and is given back with the card.
		 *
		 * The claim is taken by the card that is drawn and not by the note that was asked for: one
		 * held for a card nobody sees would swallow the Escape of the mode of the notes and keep the
		 * focus off the canvas for as long as it lies on the stack.
		 */
		isPreviewShown(isShown: boolean): void
		{
			if (!isShown)
			{
				this.releaseEscapeClaim?.();
				this.releaseEscapeClaim = null;

				return;
			}

			this.releaseEscapeClaim ??= this.inputState?.onExclusive(
				KEY_TOKEN.ESCAPE,
				this.closePreview,
			) ?? null;
		},
	},
	created(): void
	{
		// Off data() on purpose: neither a timer nor the release of a claim is rendered, and a
		// reactive proxy over them buys nothing.
		this.previewTimeout = null;
		this.previewCloseTimeout = null;
		this.releaseEscapeClaim = null;
	},
	beforeUnmount(): void
	{
		this.closePreview();
		this.releaseEscapeClaim?.();
		this.releaseEscapeClaim = null;
	},
	methods: {
		// Somebody wrote into the note while it was closed here: the marker says so until it is opened.
		hasUnseen(note: TemplateNote): boolean
		{
			return this.notesStore.unseenNoteIds.includes(note.id);
		},
		/**
		 * The pointer came to a marker. The card is not opened by that alone: it waits, and a pointer
		 * that left before the wait was over opens nothing and asks for nothing. The card of this very
		 * marker is already standing - then the pointer came back to it and it stays where it is.
		 */
		handlePreviewStart(noteId: number): void
		{
			this.cancelPreview();

			if (this.previewNoteId === noteId)
			{
				this.cancelPreviewClose();

				return;
			}

			this.previewTimeout = setTimeout(() => {
				this.previewTimeout = null;
				this.previewNoteId = noteId;
			}, PREVIEW_DELAY);
		},
		/**
		 * The pointer left the marker or the card. The card goes after a wait of its own (WCAG 1.4.13):
		 * the gap between the marker and the card is crossed within it, and the pointer that arrives
		 * keeps the card open.
		 */
		handlePreviewEnd(): void
		{
			this.cancelPreview();
			this.schedulePreviewClose();
		},
		/** The pointer is on the card itself: the closing the marker asked for is called off. */
		handlePreviewHold(): void
		{
			this.cancelPreviewClose();
		},
		schedulePreviewClose(): void
		{
			this.cancelPreviewClose();
			this.previewCloseTimeout = setTimeout(() => {
				this.previewCloseTimeout = null;
				this.previewNoteId = null;
			}, PREVIEW_CLOSE_DELAY);
		},
		/** The card goes now and not after a wait: a thread is opening over it, or the layer is going. */
		closePreview(): void
		{
			this.cancelPreview();
			this.cancelPreviewClose();
			this.previewNoteId = null;
		},
		cancelPreview(): void
		{
			if (this.previewTimeout !== null)
			{
				clearTimeout(this.previewTimeout);
				this.previewTimeout = null;
			}
		},
		cancelPreviewClose(): void
		{
			if (this.previewCloseTimeout !== null)
			{
				clearTimeout(this.previewCloseTimeout);
				this.previewCloseTimeout = null;
			}
		},
		/**
		 * The faces of everyone whose note is on the schema, in one request for all of them. Who is
		 * already known is never asked for again - that is the doing of the shared map itself.
		 *
		 * Whoever the portal left without an answer is asked about once more here and nowhere else:
		 * the list of the notes has just been read, and asking again on every redraw of the markers
		 * is what the map exists to avoid.
		 */
		async loadAuthors(): Promise<void>
		{
			forgetUnansweredEditorUsers();

			try
			{
				await this.ensureUsers(this.notes.map((note: TemplateNote) => note.authorId));
			}
			catch
			{
				// A note whose author has no face is still a note that opens and reads.
			}
		},
		authorOf(note: TemplateNote): EditorUser | null
		{
			return this.users[String(note.authorId)] ?? null;
		},
		/**
		 * One thread is open at a time (AC-012), and the store is what holds that - a marker only asks
		 * for its own. A conversation that could not be read leaves no thread open: naming the refusal
		 * belongs to the thread itself, which the layer gains later.
		 */
		async handleToggleThread(noteId: number): Promise<void>
		{
			this.closePreview();

			if (this.openedNoteId === noteId)
			{
				this.notesStore.closeThread();

				return;
			}

			try
			{
				await this.notesStore.openThread(noteId);
			}
			catch
			{
				if (this.notesStore.openedNoteId === noteId)
				{
					this.notesStore.closeThread();
				}
			}
		},
	},
	template: `
		<div class="editor-chart-notes-layer" :data-testid="layerTestId">
			<NoteMarker
				v-for="marker in markers"
				:key="marker.note.id"
				:note="marker.note"
				:author="authorOf(marker.note)"
				:x="marker.x"
				:y="marker.y"
				:isOpened="marker.note.id === openedNoteId"
				:hasUnseen="hasUnseen(marker.note)"
				@toggle="handleToggleThread(marker.note.id)"
				@preview-start="handlePreviewStart(marker.note.id)"
				@preview-end="handlePreviewEnd"
			/>
			<!-- The pointer that reaches the card keeps it open, and the one that leaves it closes it
				the way leaving the marker does (WCAG 1.4.13). -->
			<NotePreview
				v-if="previewMarker !== null"
				:key="previewMarker.note.id"
				:note="previewMarker.note"
				:templateId="templateId"
				:anchorX="previewAnchor.x"
				:anchorY="previewAnchor.y"
				:viewportWidth="viewport.width"
				:viewportHeight="viewport.height"
				@mouseenter="handlePreviewHold"
				@mouseleave="handlePreviewEnd"
				@failed="closePreview"
			/>
		</div>
	`,
});
